// JVKind represents the type of a JV value
type JVKind int

const (
	JVKindNull JVKind = iota
	JVKindFalse
	JVKindTrue
	JVKindNumber
	JVKindString
	JVKindArray
	JVKindObject
)

func (k JVKind) String() string {
	switch k {
	case JVKindNull:
		return "null"
	case JVKindFalse:
		return "false (boolean)"
	case JVKindTrue:
		return "true (boolean)"
	case JVKindNumber:
		return "number"
	case JVKindString:
		return "string"
	case JVKindArray:
		return "array"
	case JVKindObject:
		return "object"
	}
	return "unknown"
}

func (k JVKind) TypeName() string {
	switch k {
	case JVKindNull:
		return "null"
	case JVKindFalse, JVKindTrue:
		return "boolean"
	case JVKindNumber:
		return "number"
	case JVKindString:
		return "string"
	case JVKindArray:
		return "array"
	case JVKindObject:
		return "object"
	}
	return "unknown"
}

// JV represents a jq value
type JV struct {
	kind    JVKind
	numVal  float64
	strVal  string
	arrVal  []*JV
	objKeys []string
	objVals map[string]*JV
}

var JVNull = &JV{kind: JVKindNull}
var JVFalse = &JV{kind: JVKindFalse}
var JVTrue = &JV{kind: JVKindTrue}

func JVFromBool(b bool) *JV {
	if b {
		return JVTrue
	}
	return JVFalse
}

func JVFromFloat(f float64) *JV {
	return &JV{kind: JVKindNumber, numVal: f}
}

func JVFromInt(n int) *JV {
	return &JV{kind: JVKindNumber, numVal: float64(n)}
}

func JVFromString(s string) *JV {
	return &JV{kind: JVKindString, strVal: s}
}

func JVArray(items ...*JV) *JV {
	arr := make([]*JV, len(items))
	copy(arr, items)
	return &JV{kind: JVKindArray, arrVal: arr}
}

func JVEmptyArray() *JV {
	return &JV{kind: JVKindArray, arrVal: []*JV{}}
}

func JVEmptyObject() *JV {
	return &JV{kind: JVKindObject, objKeys: []string{}, objVals: map[string]*JV{}}
}

func (v *JV) Kind() JVKind {
	return v.kind
}

func (v *JV) IsNull() bool   { return v.kind == JVKindNull }
func (v *JV) IsFalse() bool  { return v.kind == JVKindFalse }
func (v *JV) IsTrue() bool   { return v.kind == JVKindTrue }
func (v *JV) IsBool() bool   { return v.kind == JVKindFalse || v.kind == JVKindTrue }
func (v *JV) IsNumber() bool { return v.kind == JVKindNumber }
func (v *JV) IsString() bool { return v.kind == JVKindString }
func (v *JV) IsArray() bool  { return v.kind == JVKindArray }
func (v *JV) IsObject() bool { return v.kind == JVKindObject }

func (v *JV) IsTruthy() bool {
	return v.kind != JVKindNull && v.kind != JVKindFalse
}

func (v *JV) Number() float64 {
	return v.numVal
}

func (v *JV) Str() string {
	return v.strVal
}

func (v *JV) Len() int {
	switch v.kind {
	case JVKindArray:
		return len(v.arrVal)
	case JVKindObject:
		return len(v.objKeys)
	}
	return 0
}

func (v *JV) Get(idx int) *JV {
	n := len(v.arrVal)
	if idx < 0 {
		idx += n
	}
	if idx < 0 || idx >= n {
		return JVNull
	}
	return v.arrVal[idx]
}

func (v *JV) GetField(key string) *JV {
	if v.kind != JVKindObject {
		return JVNull
	}
	if val, ok := v.objVals[key]; ok {
		return val
	}
	return JVNull
}

func (v *JV) HasField(key string) bool {
	if v.kind != JVKindObject {
		return false
	}
	_, ok := v.objVals[key]
	return ok
}

func (v *JV) SetField(key string, val *JV) *JV {
	newObj := &JV{kind: JVKindObject}
	if v.objVals != nil {
		newObj.objVals = make(map[string]*JV, len(v.objVals)+1)
		for k, vv := range v.objVals {
			newObj.objVals[k] = vv
		}
		newObj.objKeys = make([]string, len(v.objKeys))
		copy(newObj.objKeys, v.objKeys)
	} else {
		newObj.objVals = make(map[string]*JV)
		newObj.objKeys = []string{}
	}
	if _, exists := newObj.objVals[key]; !exists {
		newObj.objKeys = append(newObj.objKeys, key)
	}
	newObj.objVals[key] = val
	return newObj
}

func (v *JV) ObjKeys() []string {
	return v.objKeys
}

func (v *JV) ObjValues() []*JV {
	result := make([]*JV, len(v.objKeys))
	for i, k := range v.objKeys {
		result[i] = v.objVals[k]
	}
	return result
}

func (v *JV) ArrItems() []*JV {
	return v.arrVal
}

// Deep equality
func JVEqual(a, b *JV) bool {
	if a.kind != b.kind {
		return false
	}
	switch a.kind {
	case JVKindNull, JVKindFalse, JVKindTrue:
		return true
	case JVKindNumber:
		if math.IsNaN(a.numVal) && math.IsNaN(b.numVal) {
			return true
		}
		return a.numVal == b.numVal
	case JVKindString:
		return a.strVal == b.strVal
	case JVKindArray:
		if len(a.arrVal) != len(b.arrVal) {
			return false
		}
		for i := range a.arrVal {
			if !JVEqual(a.arrVal[i], b.arrVal[i]) {
				return false
			}
		}
		return true
	case JVKindObject:
		if len(a.objKeys) != len(b.objKeys) {
			return false
		}
		for _, k := range a.objKeys {
			bv, ok := b.objVals[k]
			if !ok {
				return false
			}
			if !JVEqual(a.objVals[k], bv) {
				return false
			}
		}
		return true
	}
	return false
}

// JV comparison for sorting (returns -1, 0, 1)
func JVCompare(a, b *JV) int {
	// null < false < true < numbers < strings < arrays < objects
	orderA := typeOrder(a)
	orderB := typeOrder(b)
	if orderA != orderB {
		if orderA < orderB {
			return -1
		}
		return 1
	}
	switch a.kind {
	case JVKindNull, JVKindFalse, JVKindTrue:
		return 0
	case JVKindNumber:
		if a.numVal < b.numVal {
			return -1
		}
		if a.numVal > b.numVal {
			return 1
		}
		return 0
	case JVKindString:
		if a.strVal < b.strVal {
			return -1
		}
		if a.strVal > b.strVal {
			return 1
		}
		return 0
	case JVKindArray:
		la, lb := len(a.arrVal), len(b.arrVal)
		min := la
		if lb < min {
			min = lb
		}
		for i := 0; i < min; i++ {
			c := JVCompare(a.arrVal[i], b.arrVal[i])
			if c != 0 {
				return c
			}
		}
		if la < lb {
			return -1
		}
		if la > lb {
			return 1
		}
		return 0
	case JVKindObject:
		// Compare by sorted keys first
		akeys := make([]string, len(a.objKeys))
		copy(akeys, a.objKeys)
		sort.Strings(akeys)
		bkeys := make([]string, len(b.objKeys))
		copy(bkeys, b.objKeys)
		sort.Strings(bkeys)
		la, lb := len(akeys), len(bkeys)
		min := la
		if lb < min {
			min = lb
		}
		for i := 0; i < min; i++ {
			if akeys[i] < bkeys[i] {
				return -1
			}
			if akeys[i] > bkeys[i] {
				return 1
			}
			c := JVCompare(a.objVals[akeys[i]], b.objVals[bkeys[i]])
			if c != 0 {
				return c
			}
		}
		if la < lb {
			return -1
		}
		if la > lb {
			return 1
		}
		return 0
	}
	return 0
}

func typeOrder(v *JV) int {
