	case JVKindNull:
		return 0
	case JVKindFalse:
		return 1
	case JVKindTrue:
		return 2
	case JVKindNumber:
		return 3
	case JVKindString:
		return 4
	case JVKindArray:
		return 5
	case JVKindObject:
		return 6
	}
	return -1
}

