		return false
	}
	switch a.kind {
	case JVKindNull, JVKindFalse, JVKindTrue:
		return true
	case JVKindNumber:
		if math.IsNaN(a.numVal) && math.IsNaN(b.numVal) {
			return true
		}
		return a.numVal == b.numVal
	case JVKindString:
		return a.strVal == b.strVal
	case JVKindArray:
		if len(a.arrVal) != len(b.arrVal) {
			return false
		}
		for i := range a.arrVal {
			if !JVEqual(a.arrVal[i], b.arrVal[i]) {
				return false
			}
		}
		return true
	case JVKindObject:
		if len(a.objKeys) != len(b.objKeys) {
			return false
		}
		for _, k := range a.objKeys {
			bv, ok := b.objVals[k]
			if !ok {
				return false
			}
			if !JVEqual(a.objVals[k], bv) {
				return false
			}
		}
		return true
	}
	return false
}

// JV comparison for sorting (returns -1, 0, 1)
func JVCompare(a, b *JV) int {
	// null < false < true < numbers < strings < arrays < objects
	orderA := typeOrder(a)
	orderB := typeOrder(b)
	if orderA != orderB {
		if orderA < orderB {
			return -1
		}
		return 1
	}
	switch a.kind {
	case JVKindNull, JVKindFalse, JVKindTrue:
		return 0
	case JVKindNumber:
		if a.numVal < b.numVal {
			return -1
		}
		if a.numVal > b.numVal {
			return 1
		}
		return 0
	case JVKindString:
		if a.strVal < b.strVal {
			return -1
		}
		if a.strVal > b.strVal {
			return 1
		}
		return 0
	case JVKindArray:
		la, lb := len(a.arrVal), len(b.arrVal)
		min := la
		if lb < min {
			min = lb
		}
		for i := 0; i < min; i++ {
			c := JVCompare(a.arrVal[i], b.arrVal[i])
			if c != 0 {
				return c
			}
		}
		if la < lb {
			return -1
		}
		if la > lb {
			return 1
		}
		return 0
	case JVKindObject:
		// Compare by sorted keys first
		akeys := make([]string, len(a.objKeys))
		copy(akeys, a.objKeys)
		sort.Strings(akeys)
		bkeys := make([]string, len(b.objKeys))
		copy(bkeys, b.objKeys)
		sort.Strings(bkeys)
		la, lb := len(akeys), len(bkeys)
		min := la
		if lb < min {
			min = lb
		}
		for i := 0; i < min; i++ {
			if akeys[i] < bkeys[i] {
				return -1
			}
			if akeys[i] > bkeys[i] {
				return 1
			}
			c := JVCompare(a.objVals[akeys[i]], b.objVals[bkeys[i]])
			if c != 0 {
				return c
			}
		}
		if la < lb {
			return -1
		}
		if la > lb {
			return 1
		}
		return 0
	}
	return 0
}

func typeOrder(v *JV) int {
	switch v.kind {
	case JVKindNull:
		return 0
	case JVKindFalse:
		return 1
	case JVKindTrue:
		return 2
	case JVKindNumber:
		return 3
	case JVKindString:
		return 4
	case JVKindArray:
		return 5
	case JVKindObject:
		return 6
	}
	return -1
}

// Type description for error messages
func (v *JV) TypeDesc() string {
	switch v.kind {
	case JVKindNull:
		return "null (null)"
	case JVKindFalse:
		return "boolean (false)"
	case JVKindTrue:
		return "boolean (true)"
	case JVKindNumber:
		s := formatNumber(v.numVal)
		return fmt.Sprintf("number (%s)", s)
	case JVKindString:
		if len(v.strVal) > 15 {
			return fmt.Sprintf("string (%q...)", v.strVal[:15])
		}
		return fmt.Sprintf("string (%q)", v.strVal)
	case JVKindArray:
		return "array"
	case JVKindObject:
		return "object"
	}
	return "unknown"
}

// Deep copy
func (v *JV) Copy() *JV {
	switch v.kind {
	case JVKindNull, JVKindFalse, JVKindTrue:
		return v
	case JVKindNumber:
		return &JV{kind: JVKindNumber, numVal: v.numVal}
	case JVKindString:
		return &JV{kind: JVKindString, strVal: v.strVal}
	case JVKindArray:
		arr := make([]*JV, len(v.arrVal))
		for i, item := range v.arrVal {
			arr[i] = item.Copy()
		}
		return &JV{kind: JVKindArray, arrVal: arr}
	case JVKindObject:
		keys := make([]string, len(v.objKeys))
		copy(keys, v.objKeys)
		vals := make(map[string]*JV, len(v.objVals))
		for k, val := range v.objVals {
			vals[k] = val.Copy()
		}
		return &JV{kind: JVKindObject, objKeys: keys, objVals: vals}
	}
	return JVNull
}

// Number formatting - matches jq's output format
func formatNumber(f float64) string {
	if math.IsNaN(f) {
		return "null" // jq outputs null for NaN in JSON
	}
	if math.IsInf(f, 1) {
		return "1.7976931348623157e+308" // jq clips to max float
	}
	if math.IsInf(f, -1) {
		return "-1.7976931348623157e+308"
	}

	// Use strconv with special handling
	// jq uses David Gay's dtoa which produces shortest representation
	s := strconv.AppendFloat(nil, f, 'g', -1, 64)
	str := string(s)

	// Check if it needs special handling
	// For integers stored as float, jq outputs them without decimal
	// e.g., 1.0 -> "1.0" but only if originally parsed as 1.0
	// Actually, jq tracks whether number has literal decimal point
	// For now, use standard Go formatting and fix up

	return str
}

// This matches jq's number-to-string conversion
func numberToString(f float64) string {
	if math.IsNaN(f) {
		return "null"
	}
	if math.IsInf(f, 1) {
		return "1.7976931348623157e+308"
	}
	if math.IsInf(f, -1) {
		return "-1.7976931348623157e+308"
	}
	return strconv.FormatFloat(f, 'g', 17, 64)
}

// JVContains implements jq's contains semantics
func JVContains(a, b *JV) bool {
	switch b.kind {
	case JVKindNull:
		return true
	case JVKindFalse, JVKindTrue:
		return JVEqual(a, b)
	case JVKindNumber:
		return a.kind == JVKindNumber && a.numVal == b.numVal
	case JVKindString:
		if a.kind != JVKindString {
			return false
		}
		return strings.Contains(a.strVal, b.strVal)
	case JVKindArray:
		if a.kind != JVKindArray {
			return false
		}
		for _, bitem := range b.arrVal {
			found := false
			for _, aitem := range a.arrVal {
				if JVContains(aitem, bitem) {
					found = true
					break
				}
			}
			if !found {
				return false
			}
		}
		return true
	case JVKindObject:
		if a.kind != JVKindObject {
			return false
		}
		for _, bk := range b.objKeys {
			av, ok := a.objVals[bk]
			if !ok {
				return false
			}
			if !JVContains(av, b.objVals[bk]) {
				return false
			}
		}
		return true
	}
	return false
}

// String UTF-8 length
func stringLength(s string) int {
	return utf8.RuneCountInString(s)
}

// UTF-8 byte length
func utf8ByteLength(s string) int {
	return len(s)
}
