					} else {
						sb.WriteString(keyStr)
						sb.WriteString(":")
					}
					writeJV(sb, v.objVals[k], depth+1, indent, indentStr, colorize, sortKeys, asciiOnly, tab, numFlags)
				}
			}
		}
		if colorize {
			sb.WriteString(colorBrace)
			sb.WriteString("}")
			sb.WriteString(colorReset)
		} else {
			sb.WriteString("}")
		}
	}
}

func writeIndent(sb *strings.Builder, depth int, indent int, indentStr string, tab bool) {
	if tab {
		for i := 0; i < depth; i++ {
			sb.WriteString("\t")
		}
	} else if indentStr != "" {
		for i := 0; i < depth; i++ {
			sb.WriteString(indentStr)
		}
	} else {
		for i := 0; i < depth*indent; i++ {
			sb.WriteString(" ")
		}
	}
}

func formatJVNumber(v *JV, numFlags map[*JV]NumFlags) string {
	f := v.numVal
	if math.IsNaN(f) {
		return "null"
	}
	if math.IsInf(f, 1) {
		return "1.7976931348623157e+308"
	}
	if math.IsInf(f, -1) {
		return "-1.7976931348623157e+308"
	}

	// Check number flags for literal number representation
	if numFlags != nil {
		if flags, ok := numFlags[v]; ok {
			if flags&NumFlagHasDot != 0 || flags&NumFlagHasExp != 0 {
				// Preserve the original representation
				// Use strconv with enough precision
				s := strconv.FormatFloat(f, 'g', 17, 64)
				// Ensure it has a decimal or exponent to match the original flag
				if flags&NumFlagHasDot != 0 && !strings.Contains(s, ".") && !strings.Contains(s, "e") && !strings.Contains(s, "E") {
					s += ".0"
				}
				return formatNumberStr(s)
			}
		}
	}

	// Standard jq number formatting
	return formatStandardNumber(f)
}

func formatStandardNumber(f float64) string {
	// jq uses David Gay's dtoa which produces shortest decimal representation
	// Go's strconv.FormatFloat with 'g' and -1 precision should work similarly
	s := strconv.FormatFloat(f, 'g', -1, 64)
	return formatNumberStr(s)
}

func formatNumberStr(s string) string {
	// Convert Go's number notation to jq notation
	// jq uses E+100 instead of e+100 for large exponents
	if idx := strings.IndexByte(s, 'e'); idx >= 0 {
		exp := s[idx+1:]
		mantissa := s[:idx]
		// Ensure exponent sign
		var expSign string
		if len(exp) > 0 && (exp[0] == '+' || exp[0] == '-') {
			expSign = string(exp[0])
			exp = exp[1:]
		} else {
			expSign = "+"
		}
		// Remove leading zeros in exponent
		for len(exp) > 1 && exp[0] == '0' {
			exp = exp[1:]
		}
		return fmt.Sprintf("%sE%s%s", mantissa, expSign, exp)
	}
	return s
}

func formatJSONString(s string, asciiOnly bool) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s {
		if asciiOnly && r > 127 {
			// Escape as \uXXXX or \uXXXX\uXXXX for surrogate pairs
			if r > 0xFFFF {
				// Encode as surrogate pair
				r -= 0x10000
				high := 0xD800 + (r>>10)&0x3FF
				low := 0xDC00 + r&0x3FF
				fmt.Fprintf(&sb, "\\u%04x\\u%04x", high, low)
			} else {
				fmt.Fprintf(&sb, "\\u%04x", r)
			}
			continue
		}
		switch r {
		case '"':
			sb.WriteString(`\"`)
		case '\\':
			sb.WriteString(`\\`)
		case '\b':
			sb.WriteString(`\b`)
		case '\f':
			sb.WriteString(`\f`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		default:
			if r < 0x20 {
				fmt.Fprintf(&sb, "\\u%04x", r)
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

func sortStringSlice(ss []string) {
	for i := 1; i < len(ss); i++ {
		for j := i; j > 0 && ss[j] < ss[j-1]; j-- {
			ss[j], ss[j-1] = ss[j-1], ss[j]
		}
	}
}

// Check if string is valid UTF-8 and return rune count
func runeCount(s string) int {
	return utf8.RuneCountInString(s)
}

// Convert JV to its JSON string representation  
func jvToJSON(v *JV) string {
	return formatJV(v, -1, "", false, false, false, false, nil)
}

// Format for display (pretty)
func jvToPretty(v *JV, indentN int, sortKeys bool, colorize bool, tab bool, numFlags map[*JV]NumFlags) string {
	indentStr := ""
	return formatJV(v, indentN, indentStr, colorize, sortKeys, false, tab, numFlags)
}
