func (p *JSONParser) parseString() (*JV, error) {
	p.advance() // consume '"'
	var sb strings.Builder
	for {
		if p.pos >= len(p.input) {
			return nil, &JSONParseError{"Unterminated string", p.line, p.col}
		}
		ch := p.input[p.pos]
		if ch == '"' {
			p.advance()
			return JVFromString(sb.String()), nil
		}
		if ch == '\\' {
			p.advance()
			if p.pos >= len(p.input) {
				return nil, &JSONParseError{"Unterminated escape", p.line, p.col}
			}
			esc := p.input[p.pos]
			p.advance()
			switch esc {
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case '/':
				sb.WriteByte('/')
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case 'n':
				sb.WriteByte('\n')
			case 'r':
				sb.WriteByte('\r')
			case 't':
				sb.WriteByte('\t')
			case 'u':
				// Parse 4 hex digits
				if p.pos+4 > len(p.input) {
					return nil, &JSONParseError{"Invalid unicode escape", p.line, p.col}
				}
				hex := p.input[p.pos : p.pos+4]
				code, err := strconv.ParseInt(hex, 16, 32)
				if err != nil {
					return nil, &JSONParseError{"Invalid unicode escape", p.line, p.col}
				}
				p.pos += 4
				p.col += 4
				r := rune(code)
				// Handle surrogate pairs
				if r >= 0xD800 && r <= 0xDBFF {
					// High surrogate, expect low surrogate
					if p.pos+6 <= len(p.input) && p.input[p.pos] == '\\' && p.input[p.pos+1] == 'u' {
						lowHex := p.input[p.pos+2 : p.pos+6]
						low, err2 := strconv.ParseInt(lowHex, 16, 32)
						if err2 == nil && low >= 0xDC00 && low <= 0xDFFF {
							// Combine surrogate pair
							r = rune(0x10000 + (r-0xD800)*0x400 + (rune(low) - 0xDC00))
							p.pos += 6
							p.col += 6
						}
					}
				}
				sb.WriteRune(r)
			default:
				return nil, &JSONParseError{fmt.Sprintf("Invalid escape '\\%c'", esc), p.line, p.col}
			}
		} else if ch < 0x20 {
			return nil, &JSONParseError{"Control character in string", p.line, p.col}
		} else {
			// Read a full UTF-8 rune
			r, size := utf8.DecodeRuneInString(p.input[p.pos:])
			if r == utf8.RuneError && size == 1 {
				// Invalid UTF-8, just pass through the byte
				sb.WriteByte(ch)
				p.advance()
			} else {
				sb.WriteRune(r)
				p.pos += size
				p.col++
			}
		}
	}
}

func (p *JSONParser) parseNumber() (*JV, error) {
	start := p.pos
	hasDot := false
	hasExp := false

	if p.input[p.pos] == '-' {
		p.advance()
	}
	if p.pos >= len(p.input) {
		return nil, &JSONParseError{"Invalid number", p.line, p.col}
	}

	if p.input[p.pos] == '0' {
		p.advance()
	} else if p.input[p.pos] >= '1' && p.input[p.pos] <= '9' {
		for p.pos < len(p.input) && p.input[p.pos] >= '0' && p.input[p.pos] <= '9' {
			p.advance()
		}
	} else {
		return nil, &JSONParseError{fmt.Sprintf("Invalid numeric literal at EOF at line %d, column %d", p.line, p.col), p.line, p.col}
	}

	if p.pos < len(p.input) && p.input[p.pos] == '.' {
		hasDot = true
		p.advance()
		if p.pos >= len(p.input) || p.input[p.pos] < '0' || p.input[p.pos] > '9' {
			return nil, &JSONParseError{"Invalid number: decimal point needs digits", p.line, p.col}
		}
		for p.pos < len(p.input) && p.input[p.pos] >= '0' && p.input[p.pos] <= '9' {
			p.advance()
		}
	}

	if p.pos < len(p.input) && (p.input[p.pos] == 'e' || p.input[p.pos] == 'E') {
		hasExp = true
		p.advance()
		if p.pos < len(p.input) && (p.input[p.pos] == '+' || p.input[p.pos] == '-') {
			p.advance()
		}
		if p.pos >= len(p.input) || p.input[p.pos] < '0' || p.input[p.pos] > '9' {
			return nil, &JSONParseError{"Invalid number: exponent needs digits", p.line, p.col}
		}
		for p.pos < len(p.input) && p.input[p.pos] >= '0' && p.input[p.pos] <= '9' {
			p.advance()
		}
	}

	numStr := p.input[start:p.pos]
	f, err := strconv.ParseFloat(numStr, 64)
	if err != nil {
		return nil, &JSONParseError{fmt.Sprintf("Invalid number: %s", numStr), p.line, p.col}
	}

	// Check for overflow
	if math.IsInf(f, 0) {
		return nil, &JSONParseError{"Number too large", p.line, p.col}
	}

	v := JVFromFloat(f)

	// Track literal number flags
	if hasDot || hasExp {
		var flags NumFlags
		if hasDot {
			flags |= NumFlagHasDot
		}
		if hasExp {
			flags |= NumFlagHasExp
		}
		p.numFlags[v] = flags
	}

