}

func (p *JSONParser) parseArray() (*JV, error) {
	p.advance() // consume '['
	p.skipWhitespace()

	if p.pos < len(p.input) && p.input[p.pos] == ']' {
		p.advance()
		return JVEmptyArray(), nil
	}

	arr := []*JV{}
	for {
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		arr = append(arr, v)

		p.skipWhitespace()
		if p.pos >= len(p.input) {
			return nil, &JSONParseError{"Unterminated array", p.line, p.col}
		}
		ch := p.input[p.pos]
		if ch == ']' {
			p.advance()
			return &JV{kind: JVKindArray, arrVal: arr}, nil
		}
		if ch != ',' {
			return nil, &JSONParseError{fmt.Sprintf("Expected ',' or ']' in array but got '%c'", ch), p.line, p.col}
		}
		p.advance()
	}
}

func (p *JSONParser) parseObject() (*JV, error) {
	p.advance() // consume '{'
	p.skipWhitespace()

	if p.pos < len(p.input) && p.input[p.pos] == '}' {
		p.advance()
		return JVEmptyObject(), nil
	}

	keys := []string{}
	vals := map[string]*JV{}

	for {
		p.skipWhitespace()
		if p.pos >= len(p.input) {
			return nil, &JSONParseError{"Unterminated object", p.line, p.col}
		}
		if p.input[p.pos] != '"' {
			return nil, &JSONParseError{fmt.Sprintf("Expected string key in object, got '%c'", p.input[p.pos]), p.line, p.col}
		}
		keyVal, err := p.parseString()
		if err != nil {
			return nil, err
		}
		key := keyVal.strVal

		p.skipWhitespace()
		if p.pos >= len(p.input) || p.input[p.pos] != ':' {
			return nil, &JSONParseError{"Expected ':' in object", p.line, p.col}
		}
		p.advance()

		val, err := p.parseValue()
		if err != nil {
			return nil, err
		}

		if _, exists := vals[key]; !exists {
			keys = append(keys, key)
		}
		vals[key] = val

		p.skipWhitespace()
		if p.pos >= len(p.input) {
			return nil, &JSONParseError{"Unterminated object", p.line, p.col}
		}
		ch := p.input[p.pos]
		if ch == '}' {
			p.advance()
			return &JV{kind: JVKindObject, objKeys: keys, objVals: vals}, nil
		}
		if ch != ',' {
			return nil, &JSONParseError{fmt.Sprintf("Expected ',' or '}' in object but got '%c'", ch), p.line, p.col}
		}
		p.advance()
	}
}

// ParseJSONValue parses a single JSON value from a string
func ParseJSONValue(s string) (*JV, map[*JV]NumFlags, error) {
	p := NewJSONParser(s)
	v, err := p.parseValue()
	if err != nil {
		return nil, nil, err
	}
	p.skipWhitespace()
	if p.pos < len(p.input) {
		return nil, nil, &JSONParseError{"Extra content after JSON value", p.line, p.col}
	}
	return v, p.numFlags, nil
}

// StreamingJSONParser parses multiple JSON values from a stream
type StreamingJSONParser struct {
	buf      string
	pos      int
	line     int
	col      int
	numFlags map[*JV]NumFlags
}

func NewStreamingJSONParser() *StreamingJSONParser {
	return &StreamingJSONParser{
		line:     1,
		numFlags: make(map[*JV]NumFlags),
	}
}

func (sp *StreamingJSONParser) Feed(data string) {
	sp.buf = sp.buf[sp.pos:] + data
	sp.pos = 0
}

func (sp *StreamingJSONParser) FeedEOF() {}

// ParseNext attempts to parse the next JSON value from the buffer
// Returns (value, true, nil) if successful
// Returns (nil, false, nil) if need more data
// Returns (nil, false, err) if parse error
func (sp *StreamingJSONParser) ParseNext() (*JV, bool, error) {
	// Skip whitespace
	for sp.pos < len(sp.buf) {
		ch := sp.buf[sp.pos]
		if ch == ' ' || ch == '\t' || ch == '\r' || ch == '\n' {
			if ch == '\n' {
				sp.line++
				sp.col = 0
			} else {
				sp.col++
			}
			sp.pos++
		} else {
			break
		}
	}
	if sp.pos >= len(sp.buf) {
		return nil, false, nil
	}

	// Use a regular parser on the remaining buffer
	p := &JSONParser{
		input:    sp.buf[sp.pos:],
		pos:      0,
		line:     sp.line,
		col:      sp.col,
		numFlags: sp.numFlags,
	}

	v, err := p.parseValue()
	if err != nil {
		// Advance past error
		oldPos := sp.pos
		sp.pos += p.pos
		if sp.pos == oldPos {
			sp.pos++
		}
		return nil, false, err
	}

	// Update state
	sp.pos += p.pos
	sp.line = p.line
	sp.col = p.col

	return v, true, nil
}

func (sp *StreamingJSONParser) GetNumFlags() map[*JV]NumFlags {
	return sp.numFlags
}

func (sp *StreamingJSONParser) CurrentLine() int {
	return sp.line
}
