package main

import (
	"fmt"
	"strconv"
	"strings"
)

// Token types for the jq language
type TokenType int

const (
	// Literals
	TOK_EOF TokenType = iota
	TOK_NULL
	TOK_TRUE
	TOK_FALSE
	TOK_NUMBER
	TOK_STRING
	TOK_IDENT
	TOK_FORMAT // @base64, @html, etc.

	// Operators
	TOK_DOT
	TOK_DOTDOT
	TOK_COMMA
	TOK_COLON
	TOK_SEMICOLON
	TOK_PIPE
	TOK_QUESTION
	TOK_BANG  // !
	TOK_PLUS
	TOK_MINUS
	TOK_STAR
	TOK_SLASH
	TOK_PERCENT
	TOK_EQ    // ==
	TOK_NEQ   // !=
	TOK_LT
	TOK_LE
	TOK_GT
	TOK_GE
	TOK_AND
	TOK_OR
	TOK_NOT   // not (keyword)
	TOK_ASSIGN      // =
	TOK_UPDATE      // |=
	TOK_PLUS_ASSIGN // +=
	TOK_MINUS_ASSIGN // -=
	TOK_STAR_ASSIGN // *=
	TOK_SLASH_ASSIGN // /=
	TOK_PERCENT_ASSIGN // %=
	TOK_ALT_ASSIGN  // //=
	TOK_ALT         // //

	// Delimiters
	TOK_LPAREN
	TOK_RPAREN
	TOK_LBRACKET
	TOK_RBRACKET
	TOK_LBRACE
	TOK_RBRACE

	// Keywords
	TOK_IF
	TOK_THEN
	TOK_ELSE
	TOK_ELIF
	TOK_END
	TOK_AS
	TOK_DEF
	TOK_REDUCE
	TOK_FOREACH
	TOK_LABEL
	TOK_BREAK
	TOK_TRY
	TOK_CATCH
	TOK_IMPORT
	TOK_INCLUDE
	TOK_MODULE

	// Special
	TOK_DOLLAR_IDENT // $name
	TOK_RECURSE      // ..
	TOK_OPTIONAL_OBJ // .foo?
	TOK_INTERP_START // \(
	TOK_INTERP_END   // )
	TOK_STRING_PART  // partial string in interpolation
)

type Token struct {
	typ     TokenType
	value   string
	numVal  float64
	line    int
	col     int
	numHasDot bool
	numHasExp bool
}

type Lexer struct {
	input    string
	pos      int
	line     int
	col      int
	tokens   []Token
	tokenPos int
	// String interpolation state
	interpStack []int // depth stack
}

func NewLexer(input string) *Lexer {
	l := &Lexer{
		input: input,
		line:  1,
		col:   0,
	}
	l.tokenize()
	return l
}

func (l *Lexer) peek() byte {
	if l.pos >= len(l.input) {
		return 0
	}
	return l.input[l.pos]
}

func (l *Lexer) peekAt(offset int) byte {
	if l.pos+offset >= len(l.input) {
		return 0
	}
	return l.input[l.pos+offset]
}

func (l *Lexer) advance() byte {
	if l.pos >= len(l.input) {
		return 0
	}
	ch := l.input[l.pos]
	l.pos++
	if ch == '\n' {
		l.line++
		l.col = 0
	} else {
		l.col++
	}
	return ch
}

func (l *Lexer) skipWhitespaceAndComments() {
	for l.pos < len(l.input) {
		ch := l.input[l.pos]
		if ch == ' ' || ch == '\t' || ch == '\r' || ch == '\n' {
			l.advance()
		} else if ch == '#' {
			// Comment until end of line
			for l.pos < len(l.input) && l.input[l.pos] != '\n' {
				l.advance()
			}
		} else {
			break
		}
	}
}

func (l *Lexer) tokenize() {
	l.tokens = []Token{}

	for {
		l.skipWhitespaceAndComments()
		if l.pos >= len(l.input) {
			l.tokens = append(l.tokens, Token{typ: TOK_EOF, line: l.line, col: l.col})
			break
		}

		startLine := l.line
		startCol := l.col
		ch := l.input[l.pos]

		switch {
		case ch == '.':
			if l.peekAt(1) == '.' {
				l.advance()
				l.advance()
				l.tokens = append(l.tokens, Token{typ: TOK_DOTDOT, line: startLine, col: startCol})
			} else {
				l.advance()
				l.tokens = append(l.tokens, Token{typ: TOK_DOT, line: startLine, col: startCol})
			}
		case ch == ',':
			l.advance()
			l.tokens = append(l.tokens, Token{typ: TOK_COMMA, line: startLine, col: startCol})
		case ch == ':':
			l.advance()
			l.tokens = append(l.tokens, Token{typ: TOK_COLON, line: startLine, col: startCol})
		case ch == ';':
			l.advance()
			l.tokens = append(l.tokens, Token{typ: TOK_SEMICOLON, line: startLine, col: startCol})
		case ch == '|':
			l.advance()
			if l.pos < len(l.input) && l.input[l.pos] == '=' {
				l.advance()
				l.tokens = append(l.tokens, Token{typ: TOK_UPDATE, line: startLine, col: startCol})
			} else {
				l.tokens = append(l.tokens, Token{typ: TOK_PIPE, line: startLine, col: startCol})
			}
		case ch == '?':
			l.advance()
			if l.pos < len(l.input) && l.input[l.pos] == '/' {
				if l.pos+1 < len(l.input) && l.input[l.pos+1] == '/' {
					// ?// operator (alternative for errors)
					l.advance()
					l.advance()
					l.tokens = append(l.tokens, Token{typ: TOK_ALT, value: "?//", line: startLine, col: startCol})
				} else {
					l.tokens = append(l.tokens, Token{typ: TOK_QUESTION, line: startLine, col: startCol})
				}
			} else {
				l.tokens = append(l.tokens, Token{typ: TOK_QUESTION, line: startLine, col: startCol})
			}
		case ch == '+':
			l.advance()
			if l.pos < len(l.input) && l.input[l.pos] == '=' {
				l.advance()
				l.tokens = append(l.tokens, Token{typ: TOK_PLUS_ASSIGN, line: startLine, col: startCol})
			} else {
