}

func (l *Lexer) readIdent() string {
	start := l.pos
	for l.pos < len(l.input) {
		ch := l.input[l.pos]
		if isIdentChar(ch) {
			l.pos++
			l.col++
		} else {
			break
		}
	}
	return l.input[start:l.pos]
}

func isIdentStart(ch byte) bool {
	return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch == '_'
}

func isIdentChar(ch byte) bool {
	return isIdentStart(ch) || (ch >= '0' && ch <= '9')
}

func (l *Lexer) lexNumber() (Token, error) {
	start := l.pos
	hasDot := false
	hasExp := false

	for l.pos < len(l.input) && l.input[l.pos] >= '0' && l.input[l.pos] <= '9' {
		l.pos++
		l.col++
	}
	if l.pos < len(l.input) && l.input[l.pos] == '.' {
		// Check if it's a method call like .5 (won't happen for number lexing)
		// or 1.5 (decimal number)
		if l.pos+1 < len(l.input) && l.input[l.pos+1] >= '0' && l.input[l.pos+1] <= '9' {
			hasDot = true
			l.pos++
			l.col++
			for l.pos < len(l.input) && l.input[l.pos] >= '0' && l.input[l.pos] <= '9' {
				l.pos++
				l.col++
			}
		}
	}
	if l.pos < len(l.input) && (l.input[l.pos] == 'e' || l.input[l.pos] == 'E') {
		hasExp = true
		l.pos++
		l.col++
		if l.pos < len(l.input) && (l.input[l.pos] == '+' || l.input[l.pos] == '-') {
			l.pos++
			l.col++
		}
		for l.pos < len(l.input) && l.input[l.pos] >= '0' && l.input[l.pos] <= '9' {
			l.pos++
			l.col++
		}
	}

	numStr := l.input[start:l.pos]
	f, err := strconv.ParseFloat(numStr, 64)
	if err != nil {
		return Token{}, fmt.Errorf("invalid number: %s", numStr)
	}
	return Token{typ: TOK_NUMBER, numVal: f, value: numStr, numHasDot: hasDot, numHasExp: hasExp}, nil
}

// lexString handles string literals including interpolation
// Returns a slice of tokens: TOK_STRING for simple strings,
// or TOK_STRING_PART, TOK_INTERP_START, ..., TOK_INTERP_END, TOK_STRING_PART for interpolated
func (l *Lexer) lexString() ([]Token, error) {
	startLine := l.line
	startCol := l.col
	l.advance() // consume '"'

	// Check if this is a format string like @base64 "..."
	return l.lexStringContent(startLine, startCol)
}

func (l *Lexer) lexStringContent(startLine, startCol int) ([]Token, error) {
	var tokens []Token
	var currentPart strings.Builder
	partLine := startLine
	partCol := startCol

	for {
		if l.pos >= len(l.input) {
			return nil, fmt.Errorf("unterminated string at line %d", l.line)
		}
		ch := l.input[l.pos]

		if ch == '"' {
			l.advance()
			// End of string
			tokens = append(tokens, Token{typ: TOK_STRING, value: currentPart.String(), line: partLine, col: partCol})
			return tokens, nil
		}

		if ch == '\\' {
			l.advance()
			if l.pos >= len(l.input) {
				return nil, fmt.Errorf("unterminated escape")
			}
			esc := l.input[l.pos]
			l.advance()
			switch esc {
			case '"':
				currentPart.WriteByte('"')
			case '\\':
				currentPart.WriteByte('\\')
			case '/':
				currentPart.WriteByte('/')
			case 'b':
				currentPart.WriteByte('\b')
			case 'f':
				currentPart.WriteByte('\f')
			case 'n':
				currentPart.WriteByte('\n')
			case 'r':
				currentPart.WriteByte('\r')
			case 't':
				currentPart.WriteByte('\t')
			case 'u':
				if l.pos+4 > len(l.input) {
					return nil, fmt.Errorf("invalid unicode escape")
				}
				hex := l.input[l.pos : l.pos+4]
				code, err := strconv.ParseInt(hex, 16, 32)
				if err != nil {
					return nil, fmt.Errorf("invalid unicode escape")
				}
				l.pos += 4
				l.col += 4
				r := rune(code)
				if r >= 0xD800 && r <= 0xDBFF {
					if l.pos+6 <= len(l.input) && l.input[l.pos] == '\\' && l.input[l.pos+1] == 'u' {
						lowHex := l.input[l.pos+2 : l.pos+6]
						low, err2 := strconv.ParseInt(lowHex, 16, 32)
						if err2 == nil && low >= 0xDC00 && low <= 0xDFFF {
							r = rune(0x10000 + (r-0xD800)*0x400 + (rune(low) - 0xDC00))
							l.pos += 6
							l.col += 6
						}
					}
				}
				currentPart.WriteRune(r)
			case '(':
				// String interpolation \(expr)
				// Save current string part as STRING_PART
				tokens = append(tokens, Token{typ: TOK_STRING_PART, value: currentPart.String(), line: partLine, col: partCol})
				currentPart.Reset()
				// Add INTERP_START token
				tokens = append(tokens, Token{typ: TOK_INTERP_START, line: l.line, col: l.col})
				// Now we need to lex the expression inside until matching )
				// This is done by recursively tokenizing, tracking paren depth
				depth := 1
				interpStart := l.pos
				for l.pos < len(l.input) && depth > 0 {
					c := l.input[l.pos]
					if c == '(' {
						depth++
						l.pos++
						l.col++
					} else if c == ')' {
						depth--
						if depth > 0 {
							l.pos++
							l.col++
						} else {
							break
						}
					} else if c == '"' {
						// Nested string
						l.pos++
						l.col++
						// Skip until end of string (handle escapes)
						for l.pos < len(l.input) {
							c2 := l.input[l.pos]
							if c2 == '"' {
								l.pos++
								l.col++
								break
							}
							if c2 == '\\' {
								l.pos++
								l.col++
								if l.pos < len(l.input) {
									l.pos++
									l.col++
								}
							} else {
								l.pos++
								l.col++
							}
						}
					} else if c == '\n' {
						l.line++
						l.col = 0
						l.pos++
					} else {
						l.pos++
						l.col++
					}
				}
				_ = interpStart
				// We consumed the interp expression chars, need to re-tokenize
				// Actually: let me redo this. The string interpolation in jq's lexer
				// needs to properly handle nested strings and expressions.
				// This simple approach won't work for nested interpolations.
				// Let me use a different approach - return a special marker and handle in parser.

				// For now, we'll handle this at a higher level
				// The current position is at the closing ')'
				if l.pos < len(l.input) && l.input[l.pos] == ')' {
					l.advance()
				}
				tokens = append(tokens, Token{typ: TOK_INTERP_END, line: l.line, col: l.col})
				partLine = l.line
				partCol = l.col
			default:
				currentPart.WriteByte('\\')
				currentPart.WriteByte(esc)
			}
		} else {
			l.advance()
			currentPart.WriteByte(ch)
		}
	}
}

func (l *Lexer) Next() Token {
	if l.tokenPos >= len(l.tokens) {
		return Token{typ: TOK_EOF}
	}
	tok := l.tokens[l.tokenPos]
	l.tokenPos++
	return tok
}

func (l *Lexer) Peek() Token {
	if l.tokenPos >= len(l.tokens) {
		return Token{typ: TOK_EOF}
	}
	return l.tokens[l.tokenPos]
}

func (l *Lexer) PeekAt(offset int) Token {
	idx := l.tokenPos + offset
	if idx >= len(l.tokens) {
		return Token{typ: TOK_EOF}
	}
	return l.tokens[idx]
}

func (l *Lexer) Backup() {
	if l.tokenPos > 0 {
		l.tokenPos--
	}
}
