			} else {
				l.tokens = append(l.tokens, Token{typ: TOK_STAR, line: startLine, col: startCol})
			}
		case ch == '/':
			l.advance()
			if l.pos < len(l.input) && l.input[l.pos] == '/' {
				l.advance()
				if l.pos < len(l.input) && l.input[l.pos] == '=' {
					l.advance()
					l.tokens = append(l.tokens, Token{typ: TOK_ALT_ASSIGN, line: startLine, col: startCol})
				} else {
					l.tokens = append(l.tokens, Token{typ: TOK_ALT, line: startLine, col: startCol})
				}
			} else if l.pos < len(l.input) && l.input[l.pos] == '=' {
				l.advance()
				l.tokens = append(l.tokens, Token{typ: TOK_SLASH_ASSIGN, line: startLine, col: startCol})
			} else {
				l.tokens = append(l.tokens, Token{typ: TOK_SLASH, line: startLine, col: startCol})
			}
		case ch == '%':
			l.advance()
			if l.pos < len(l.input) && l.input[l.pos] == '=' {
				l.advance()
				l.tokens = append(l.tokens, Token{typ: TOK_PERCENT_ASSIGN, line: startLine, col: startCol})
			} else {
				l.tokens = append(l.tokens, Token{typ: TOK_PERCENT, line: startLine, col: startCol})
			}
		case ch == '=':
			l.advance()
			if l.pos < len(l.input) && l.input[l.pos] == '=' {
				l.advance()
				l.tokens = append(l.tokens, Token{typ: TOK_EQ, line: startLine, col: startCol})
			} else {
				l.tokens = append(l.tokens, Token{typ: TOK_ASSIGN, line: startLine, col: startCol})
			}
		case ch == '!':
			l.advance()
			if l.pos < len(l.input) && l.input[l.pos] == '=' {
				l.advance()
				l.tokens = append(l.tokens, Token{typ: TOK_NEQ, line: startLine, col: startCol})
			} else {
				l.tokens = append(l.tokens, Token{typ: TOK_BANG, line: startLine, col: startCol})
			}
		case ch == '<':
			l.advance()
			if l.pos < len(l.input) && l.input[l.pos] == '=' {
				l.advance()
				l.tokens = append(l.tokens, Token{typ: TOK_LE, line: startLine, col: startCol})
			} else {
				l.tokens = append(l.tokens, Token{typ: TOK_LT, line: startLine, col: startCol})
			}
		case ch == '>':
			l.advance()
			if l.pos < len(l.input) && l.input[l.pos] == '=' {
				l.advance()
				l.tokens = append(l.tokens, Token{typ: TOK_GE, line: startLine, col: startCol})
			} else {
				l.tokens = append(l.tokens, Token{typ: TOK_GT, line: startLine, col: startCol})
			}
