				l.tokens = append(l.tokens, Token{typ: TOK_PLUS_ASSIGN, line: startLine, col: startCol})
			} else {
				l.tokens = append(l.tokens, Token{typ: TOK_PLUS, line: startLine, col: startCol})
			}
		case ch == '-':
			l.advance()
			if l.pos < len(l.input) && l.input[l.pos] == '=' {
				l.advance()
				l.tokens = append(l.tokens, Token{typ: TOK_MINUS_ASSIGN, line: startLine, col: startCol})
