package main

// AST node types for jq
type NodeType int

const (
	// Literals
	NodeNull NodeType = iota
	NodeFalse
	NodeTrue
	NodeNumber
	NodeString
	NodeFormat      // @base64, etc. standalone
	NodeFormatStr   // @base64 "..." with interpolation

	// Identity and iteration
	NodeIdentity    // .
	NodeRecurse     // ..
	NodeIterate     // .[]
	NodeIterateOpt  // .[]?

	// Field access
	NodeField       // .foo
	NodeFieldOpt    // .foo?
	NodeIndex       // .[expr]
	NodeIndexOpt    // .[expr]?
	NodeSlice       // .[a:b]

	// Pipe and comma
	NodePipe        // a | b
	NodeComma       // a, b

	// Operators
	NodeAdd
	NodeSub
	NodeMul
	NodeDiv
	NodeMod
	NodeEq
	NodeNeq
	NodeLt
	NodeLe
	NodeGt
	NodeGe
	NodeAnd
	NodeOr
	NodeNot
	NodeAlt         // a // b
	NodeTryAlt      // a ?// b

	// Assignment operators
	NodeAssign      // a = b
	NodeUpdate      // a |= b
	NodeAddAssign   // a += b
	NodeSubAssign   // a -= b
	NodeMulAssign   // a *= b
	NodeDivAssign   // a /= b
	NodeModAssign   // a %= b
	NodeAltAssign   // a //= b

	// Collections
	NodeArray       // [expr]
	NodeObject      // {pairs}

	// Control flow
	NodeIf          // if-then-else
	NodeTry         // try-catch
	NodeLabel       // label $name | expr
	NodeBreak       // break $name

	// Binding
	NodeAs          // expr as $x | body  or  expr as pattern | body
	NodeDef         // def name(args): body
	NodeCall        // name(args)
	NodeCallN       // name/arity

	// Special
	NodePath        // path(expr)
	NodeReduce      // reduce
	NodeForeach     // foreach
	NodeRecurseOp   // recurse(f) or recurse(f; cond)

	// Variable
	NodeVar         // $name
	NodeLocRef      // $__loc__

	// String interpolation
	NodeInterp      // string with interpolation

	// Optional
	NodeOptional    // expr?

	// Env
	NodeEnv         // $ENV

	// Error suppression
	NodeTryCatch    // internal try-catch

	// Patterns for as
	NodePatternObj  // {.key: $var}
	NodePatternArr  // [$var1, $var2]
)

// AST Node
type Node struct {
	typ      NodeType
	// Various data fields
	strVal   string       // string literal, field name, format name
	numVal   float64      // number literal
	numHasDot bool
	numHasExp bool
	children []*Node      // child nodes
	args     [][]*Node    // multiple argument lists (for function calls)
	bindings []NodeBinding // for as patterns
	defs     []NodeDef    // function definitions
	line     int
	col      int
}

type NodeBinding struct {
	pattern *Node
	body    *Node
}

type NodeDef struct {
	name   string
	params []string // parameter names (could be functions or variables)
	body   *Node
	line   int
	col    int
}

// Object construction pair
type ObjPair struct {
	key   *Node  // key expression
	value *Node  // value expression (nil means use .key shorthand)
	isComputed bool // key is expression (not identifier)
}

type NodeObj struct {
	pairs []ObjPair
}

// String interpolation parts
type InterpPart struct {
	isStr bool
	str   string
	expr  *Node
}

func newNode(typ NodeType, line, col int) *Node {
	return &Node{typ: typ, line: line, col: col}
}

func litNull(line, col int) *Node { return &Node{typ: NodeNull, line: line, col: col} }
func litTrue(line, col int) *Node { return &Node{typ: NodeTrue, line: line, col: col} }
func litFalse(line, col int) *Node { return &Node{typ: NodeFalse, line: line, col: col} }
func litNumber(f float64, hasDot, hasExp bool, line, col int) *Node {
	return &Node{typ: NodeNumber, numVal: f, numHasDot: hasDot, numHasExp: hasExp, line: line, col: col}
}
func litString(s string, line, col int) *Node {
	return &Node{typ: NodeString, strVal: s, line: line, col: col}
}

func binop(typ NodeType, left, right *Node, line, col int) *Node {
	return &Node{typ: typ, children: []*Node{left, right}, line: line, col: col}
}

func unop(typ NodeType, child *Node, line, col int) *Node {
	return &Node{typ: typ, children: []*Node{child}, line: line, col: col}
}
GOEOF
