// parseUnaryExpr handles unary minus
func (p *Parser) parseUnaryExpr() (*Node, error) {
	if p.peek().typ == TOK_MINUS {
		tok := p.next()
		// Unary minus - apply to next expression
		child, err := p.parseUnaryExpr()
		if err != nil {
			return nil, err
		}
		// Optimize: negate literal numbers
		if child.typ == NodeNumber {
			child.numVal = -child.numVal
			return child, nil
		}
		// Otherwise create subtraction from 0
		return binop(NodeSub, litNumber(0, false, false, tok.line, tok.col), child, tok.line, tok.col), nil
	}
	return p.parsePostfixExpr()
}

// parsePostfixExpr handles postfix operators (?, .field, .[idx])
func (p *Parser) parsePostfixExpr() (*Node, error) {
	expr, err := p.parsePrimaryExpr()
	if err != nil {
		return nil, err
	}

	// Apply postfix operators
	for {
		tok := p.peek()
		switch tok.typ {
		case TOK_DOT:
			// .field or .field?
			p.next()
			// Check for optional
			fieldTok := p.peek()
			if fieldTok.typ == TOK_IDENT {
				p.next()
				optional := false
				if p.peek().typ == TOK_QUESTION {
					optional = true
					p.next()
				}
				nodeType := NodeField
				if optional {
					nodeType = NodeFieldOpt
				}
				node := &Node{typ: nodeType, strVal: fieldTok.value, children: []*Node{expr}, line: tok.line, col: tok.col}
				expr = node
			} else if fieldTok.typ == TOK_LBRACKET {
				// .[
				p.next()
				node, err := p.parseIndexOrSlice(expr, tok.line, tok.col)
				if err != nil {
					return nil, err
				}
				expr = node
			} else {
				// Standalone . after expression? That's identity piped
				// Actually this shouldn't happen in postfix - it means we consumed a . that's identity
				p.lexer.Backup()
				return expr, nil
			}
		case TOK_LBRACKET:
			// expr[...]
			p.next()
			node, err := p.parseIndexOrSlice(expr, tok.line, tok.col)
			if err != nil {
				return nil, err
			}
			expr = node
		case TOK_QUESTION:
			p.next()
			// Check if it's ?// 
			// Actually tok is already TOK_QUESTION here
			expr = unop(NodeOptional, expr, tok.line, tok.col)
		default:
			return expr, nil
		}
	}
}

func (p *Parser) parseIndexOrSlice(base *Node, line, col int) (*Node, error) {
	// We've consumed '[', now parse the index or slice
	if p.peek().typ == TOK_RBRACKET {
		// .[] - iterate
		p.next()
		optional := false
		if p.peek().typ == TOK_QUESTION {
			optional = true
			p.next()
		}
		var nodeType NodeType
		if optional {
			nodeType = NodeIterateOpt
		} else {
			nodeType = NodeIterate
		}
		if base == nil {
			return &Node{typ: nodeType, line: line, col: col}, nil
		}
		return &Node{typ: NodePipe, children: []*Node{
			base,
			&Node{typ: nodeType, line: line, col: col},
		}, line: line, col: col}, nil
	}

	// Check for slice start .[n:]
	if p.peek().typ == TOK_COLON {
		p.next()
		// .[: n] or .[:]
		var end *Node
		if p.peek().typ != TOK_RBRACKET {
			var err error
			end, err = p.parseCommaExpr()
			if err != nil {
				return nil, err
			}
		}
		if _, err := p.expect(TOK_RBRACKET); err != nil {
			return nil, err
		}
		optional := false
		if p.peek().typ == TOK_QUESTION {
			optional = true
			p.next()
		}
		_ = optional
		return makeSlice(base, nil, end, line, col), nil
	}

	// Parse first expression
	idx, err := p.parseCommaExpr()
	if err != nil {
		return nil, err
	}

	if p.peek().typ == TOK_COLON {
		// Slice
		p.next()
		var end *Node
		if p.peek().typ != TOK_RBRACKET {
			end, err = p.parseCommaExpr()
			if err != nil {
				return nil, err
			}
		}
		if _, err := p.expect(TOK_RBRACKET); err != nil {
			return nil, err
		}
		optional := false
		if p.peek().typ == TOK_QUESTION {
			optional = true
			p.next()
		}
		_ = optional
		return makeSlice(base, idx, end, line, col), nil
	}

	// Regular index
	if _, err := p.expect(TOK_RBRACKET); err != nil {
		return nil, err
	}
	optional := false
	if p.peek().typ == TOK_QUESTION {
		optional = true
		p.next()
	}

	nodeType := NodeIndex
	if optional {
		nodeType = NodeIndexOpt
	}

	if base == nil {
		return &Node{typ: nodeType, children: []*Node{idx}, line: line, col: col}, nil
	}
	return &Node{typ: NodePipe, children: []*Node{
		base,
		&Node{typ: nodeType, children: []*Node{idx}, line: line, col: col},
	}, line: line, col: col}, nil
}

func makeSlice(base, start, end *Node, line, col int) *Node {
	children := []*Node{start, end}
	if base == nil {
		return &Node{typ: NodeSlice, children: children, line: line, col: col}
	}
	return &Node{typ: NodePipe, children: []*Node{
		base,
		&Node{typ: NodeSlice, children: children, line: line, col: col},
	}, line: line, col: col}
}

// parsePrimaryExpr handles primary expressions
func (p *Parser) parsePrimaryExpr() (*Node, error) {
	tok := p.peek()

	switch tok.typ {
	case TOK_NULL:
		p.next()
		return litNull(tok.line, tok.col), nil
	case TOK_TRUE:
		p.next()
		return litTrue(tok.line, tok.col), nil
	case TOK_FALSE:
		p.next()
		return litFalse(tok.line, tok.col), nil
	case TOK_NUMBER:
		p.next()
		return litNumber(tok.numVal, tok.numHasDot, tok.numHasExp, tok.line, tok.col), nil
	case TOK_STRING:
		p.next()
		return litString(tok.value, tok.line, tok.col), nil
	case TOK_STRING_PART:
		return p.parseInterpolatedString(nil, "")
	case TOK_FORMAT:
		return p.parseFormatExpr()
	case TOK_DOT:
		return p.parseDotExpr()
	case TOK_DOTDOT:
		p.next()
		return &Node{typ: NodeRecurse, line: tok.line, col: tok.col}, nil
	case TOK_DOLLAR_IDENT:
		p.next()
		if tok.value == "_ENV" {
			return &Node{typ: NodeEnv, line: tok.line, col: tok.col}, nil
		}
		if tok.value == "_loc_" || tok.value == "__loc__" {
			return &Node{typ: NodeLocRef, line: tok.line, col: tok.col}, nil
		}
		return &Node{typ: NodeVar, strVal: tok.value, line: tok.line, col: tok.col}, nil
	case TOK_LBRACKET:
		return p.parseArrayExpr()
	case TOK_LBRACE:
		return p.parseObjectExpr()
	case TOK_LPAREN:
		p.next()
		expr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if _, err := p.expect(TOK_RPAREN); err != nil {
			return nil, err
		}
		return expr, nil
	case TOK_IF:
		return p.parseIfExpr()
	case TOK_REDUCE:
		return p.parseReduceExpr()
	case TOK_FOREACH:
		return p.parseForeachExpr()
	case TOK_TRY:
		return p.parseTryExpr()
	case TOK_BREAK:
		p.next()
		varTok := p.next()
		if varTok.typ != TOK_DOLLAR_IDENT {
			return nil, fmt.Errorf("expected $name after break at line %d", tok.line)
		}
		return &Node{typ: NodeBreak, strVal: varTok.value, line: tok.line, col: tok.col}, nil
	case TOK_IDENT:
		return p.parseIdentExpr()
	default:
		return nil, fmt.Errorf("syntax error, unexpected %s at line %d, column %d", 
			tokenDesc(tok), tok.line, tok.col)
	}
}

func (p *Parser) parseFormatExpr() (*Node, error) {
	tok := p.next() // consume @format
	formatName := tok.value

	// Check if followed by string
	if p.peek().typ == TOK_STRING || p.peek().typ == TOK_STRING_PART {
		// @format "string"
		strExpr, err := p.parseStringOrInterp()
		if err != nil {
			return nil, err
		}
		// Wrap in format application
		node := &Node{typ: NodeFormatStr, strVal: formatName, children: []*Node{strExpr}, line: tok.line, col: tok.col}
		return node, nil
	}

	// Standalone @format 
	return &Node{typ: NodeFormat, strVal: formatName, line: tok.line, col: tok.col}, nil
}

func (p *Parser) parseStringOrInterp() (*Node, error) {
	if p.peek().typ == TOK_STRING {
		tok := p.next()
		return litString(tok.value, tok.line, tok.col), nil
	}
	return p.parseInterpolatedString(nil, "")
}

func (p *Parser) parseInterpolatedString(formatNode *Node, formatName string) (*Node, error) {
	// This handles strings with \(...) interpolation
	// The lexer already tokenized them into STRING_PART, INTERP_START, ..., INTERP_END, STRING_PART
	// But our lexer is simpler - let me handle it differently

	// Actually my lexer is wrong for interpolation. Let me use a different approach:
	// Re-parse the string with full interpolation support.

	// For now, handle basic interpolation by looking at the token stream
	if p.peek().typ == TOK_STRING_PART {
		tok := p.next() // string_part
		parts := []InterpPart{{isStr: true, str: tok.value}}

		for p.peek().typ == TOK_INTERP_START {
			p.next() // consume INTERP_START
			exprStr := p.peek().value // The expression text
			_ = exprStr
			// Parse the expression
			expr, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if p.peek().typ == TOK_INTERP_END {
				p.next()
			}
			parts = append(parts, InterpPart{isStr: false, expr: expr})

			if p.peek().typ == TOK_STRING_PART || p.peek().typ == TOK_STRING {
				strTok := p.next()
				parts = append(parts, InterpPart{isStr: true, str: strTok.value})
			}
		}

		return buildInterpNode(parts, formatName, tok.line, tok.col), nil
	}

	return nil, fmt.Errorf("expected string")
}

func buildInterpNode(parts []InterpPart, formatName string, line, col int) *Node {
	node := &Node{typ: NodeInterp, strVal: formatName, line: line, col: col}
	for _, part := range parts {
		if part.isStr {
			node.children = append(node.children, litString(part.str, line, col))
		} else {
			node.children = append(node.children, &Node{typ: NodeNull, line: line, col: col}) // placeholder
			node.children[len(node.children)-1] = part.expr
		}
	}
	// Store part info
	for i, part := range parts {
		if part.isStr {
			_ = i
		}
	}
	// Encode parts as bindings
	node.bindings = make([]NodeBinding, len(parts))
	for i, part := range parts {
		if part.isStr {
			node.bindings[i] = NodeBinding{pattern: litString(part.str, line, col)}
		} else {
			node.bindings[i] = NodeBinding{pattern: nil, body: part.expr}
		}
	}
	return node
}

func (p *Parser) parseDotExpr() (*Node, error) {
	tok := p.next() // consume '.'

	// Check what follows
	next := p.peek()
	switch next.typ {
	case TOK_IDENT:
		// .field
		p.next()
		optional := false
		if p.peek().typ == TOK_QUESTION {
			optional = true
			p.next()
		}
		nodeType := NodeField
		if optional {
			nodeType = NodeFieldOpt
		}
		return &Node{typ: nodeType, strVal: next.value, line: tok.line, col: tok.col}, nil
	case TOK_LBRACKET:
		// .[...]
		p.next()
		return p.parseIndexOrSlice(nil, tok.line, tok.col)
	default:
		// Identity
		return &Node{typ: NodeIdentity, line: tok.line, col: tok.col}, nil
	}
}

func (p *Parser) parseArrayExpr() (*Node, error) {
	tok := p.next() // consume '['

	if p.peek().typ == TOK_RBRACKET {
		p.next()
		return &Node{typ: NodeArray, line: tok.line, col: tok.col}, nil
	}

	expr, err := p.parseExpr()
	if err != nil {
		return nil, err
	}

	if _, err := p.expect(TOK_RBRACKET); err != nil {
		return nil, err
	}

	return &Node{typ: NodeArray, children: []*Node{expr}, line: tok.line, col: tok.col}, nil
}

func (p *Parser) parseObjectExpr() (*Node, error) {
	tok := p.next() // consume '{'

	if p.peek().typ == TOK_RBRACE {
		p.next()
		return &Node{typ: NodeObject, line: tok.line, col: tok.col}, nil
	}

	var pairs []*Node // pairs stored as children: [key, value, key, value, ...]
	var pairTypes []bool // true = computed key

	for {
		// Parse key
		keyTok := p.peek()
		var keyNode *Node
		computed := false

		if keyTok.typ == TOK_LPAREN {
			// (expr): computed key
			p.next()
			computed = true
			k, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if _, err := p.expect(TOK_RPAREN); err != nil {
				return nil, err
			}
			keyNode = k
		} else if keyTok.typ == TOK_IDENT {
			p.next()
			keyNode = litString(keyTok.value, keyTok.line, keyTok.col)
		} else if keyTok.typ == TOK_STRING {
			p.next()
			keyNode = litString(keyTok.value, keyTok.line, keyTok.col)
		} else if keyTok.typ == TOK_DOLLAR_IDENT {
			p.next()
			keyNode = litString(keyTok.value, keyTok.line, keyTok.col)
		} else if keyTok.typ == TOK_NUMBER {
			p.next()
			keyNode = litNumber(keyTok.numVal, keyTok.numHasDot, keyTok.numHasExp, keyTok.line, keyTok.col)
		} else {
			return nil, fmt.Errorf("expected object key at line %d, column %d", keyTok.line, keyTok.col)
		}

		pairTypes = append(pairTypes, computed)

		if !computed && p.peek().typ != TOK_COLON {
			// Shorthand: {foo} means {foo: .foo}
			pairs = append(pairs, keyNode)
			pairs = append(pairs, nil) // nil means shorthand
		} else {
			if _, err := p.expect(TOK_COLON); err != nil {
				return nil, err
			}
			valExpr, err := p.parsePipeExpr()
			if err != nil {
				return nil, err
			}
			pairs = append(pairs, keyNode)
			pairs = append(pairs, valExpr)
		}

		if p.peek().typ == TOK_COMMA {
			p.next()
			if p.peek().typ == TOK_RBRACE {
				break
			}
			continue
		}
		break
	}

	if _, err := p.expect(TOK_RBRACE); err != nil {
		return nil, err
	}

	node := &Node{typ: NodeObject, children: pairs, line: tok.line, col: tok.col}
	// Encode pairTypes in bindings
	node.bindings = make([]NodeBinding, len(pairTypes))
	for i, computed := range pairTypes {
		if computed {
			node.bindings[i] = NodeBinding{pattern: &Node{typ: NodeTrue}}
		}
	}
	return node, nil
}

func (p *Parser) parseIfExpr() (*Node, error) {
	tok := p.next() // consume 'if'

	cond, err := p.parseExpr()
	if err != nil {
		return nil, err
	}

	if _, err := p.expect(TOK_THEN); err != nil {
		return nil, fmt.Errorf("expected 'then' at line %d", tok.line)
	}

	thenExpr, err := p.parseExpr()
	if err != nil {
		return nil, err
	}

	// Check for elif or else
	node := &Node{typ: NodeIf, children: []*Node{cond, thenExpr}, line: tok.line, col: tok.col}

	for p.peek().typ == TOK_ELIF {
		p.next()
		elifCond, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if _, err := p.expect(TOK_THEN); err != nil {
			return nil, err
		}
		elifThen, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		node.children = append(node.children, elifCond, elifThen)
	}

	if p.peek().typ == TOK_ELSE {
		p.next()
		elseExpr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		node.children = append(node.children, elseExpr)
	}

	if _, err := p.expect(TOK_END); err != nil {
		return nil, fmt.Errorf("expected 'end' at line %d", tok.line)
	}

	return node, nil
}

func (p *Parser) parseReduceExpr() (*Node, error) {
	tok := p.next() // consume 'reduce'

	gen, err := p.parsePostfixExpr()
	if err != nil {
		return nil, err
	}

	if _, err := p.expect(TOK_AS); err != nil {
		return nil, err
	}

	pattern, err := p.parsePattern()
	if err != nil {
		return nil, err
	}

	if _, err := p.expect(TOK_LPAREN); err != nil {
		return nil, err
	}

	init, err := p.parseExpr()
	if err != nil {
		return nil, err
	}

	if _, err := p.expect(TOK_SEMICOLON); err != nil {
		return nil, err
	}

	body, err := p.parseExpr()
	if err != nil {
		return nil, err
	}

	if _, err := p.expect(TOK_RPAREN); err != nil {
		return nil, err
	}

	return &Node{
		typ:      NodeReduce,
		children: []*Node{gen, init, body},
		bindings: []NodeBinding{{pattern: pattern}},
		line:     tok.line, col: tok.col,
	}, nil
}

func (p *Parser) parseForeachExpr() (*Node, error) {
	tok := p.next() // consume 'foreach'

	gen, err := p.parsePostfixExpr()
	if err != nil {
		return nil, err
	}

	if _, err := p.expect(TOK_AS); err != nil {
		return nil, err
	}

	pattern, err := p.parsePattern()
	if err != nil {
		return nil, err
	}

	if _, err := p.expect(TOK_LPAREN); err != nil {
		return nil, err
	}

	init, err := p.parseExpr()
	if err != nil {
		return nil, err
	}

	if _, err := p.expect(TOK_SEMICOLON); err != nil {
		return nil, err
	}

	update, err := p.parseExpr()
	if err != nil {
		return nil, err
	}

	var extract *Node
	if p.peek().typ == TOK_SEMICOLON {
		p.next()
		extract, err = p.parseExpr()
		if err != nil {
			return nil, err
		}
	}

	if _, err := p.expect(TOK_RPAREN); err != nil {
		return nil, err
	}

	children := []*Node{gen, init, update}
	if extract != nil {
		children = append(children, extract)
	}

	return &Node{
		typ:      NodeForeach,
		children: children,
		bindings: []NodeBinding{{pattern: pattern}},
		line:     tok.line, col: tok.col,
	}, nil
}

func (p *Parser) parseTryExpr() (*Node, error) {
	tok := p.next() // consume 'try'

	body, err := p.parsePostfixExpr()
	if err != nil {
		return nil, err
	}

	var catchExpr *Node
	if p.peek().typ == TOK_CATCH {
		p.next()
		catchExpr, err = p.parsePostfixExpr()
		if err != nil {
			return nil, err
		}
	}

	children := []*Node{body}
	if catchExpr != nil {
		children = append(children, catchExpr)
	}

	return &Node{typ: NodeTry, children: children, line: tok.line, col: tok.col}, nil
}

func (p *Parser) parsePattern() (*Node, error) {
	tok := p.peek()
	if tok.typ == TOK_DOLLAR_IDENT {
		p.next()
		return &Node{typ: NodeVar, strVal: tok.value, line: tok.line, col: tok.col}, nil
	}
	if tok.typ == TOK_LBRACE {
		return p.parseObjectPattern()
	}
	if tok.typ == TOK_LBRACKET {
		return p.parseArrayPattern()
	}
	return nil, fmt.Errorf("expected pattern at line %d", tok.line)
}

func (p *Parser) parseObjectPattern() (*Node, error) {
	tok := p.next() // consume '{'

	var children []*Node
	for p.peek().typ != TOK_RBRACE {
		keyTok := p.peek()
		var key string
		if keyTok.typ == TOK_IDENT {
			p.next()
			key = keyTok.value
		} else if keyTok.typ == TOK_STRING {
			p.next()
			key = keyTok.value
		} else {
			return nil, fmt.Errorf("expected key in object pattern at line %d", keyTok.line)
		}

		if p.peek().typ == TOK_COLON {
			p.next()
			varPat, err := p.parsePattern()
			if err != nil {
				return nil, err
			}
			children = append(children, litString(key, keyTok.line, keyTok.col), varPat)
		} else {
			// Shorthand {foo} binds $foo to .foo
			children = append(children, litString(key, keyTok.line, keyTok.col), nil)
		}

		if p.peek().typ == TOK_COMMA {
			p.next()
		} else {
			break
		}
	}

	if _, err := p.expect(TOK_RBRACE); err != nil {
		return nil, err
	}

	return &Node{typ: NodePatternObj, children: children, line: tok.line, col: tok.col}, nil
}

func (p *Parser) parseArrayPattern() (*Node, error) {
	tok := p.next() // consume '['

	var children []*Node
	for p.peek().typ != TOK_RBRACKET {
		pat, err := p.parsePattern()
		if err != nil {
			return nil, err
		}
		children = append(children, pat)
		if p.peek().typ == TOK_COMMA {
			p.next()
		} else {
			break
		}
	}

	if _, err := p.expect(TOK_RBRACKET); err != nil {
		return nil, err
	}

	return &Node{typ: NodePatternArr, children: children, line: tok.line, col: tok.col}, nil
}

func (p *Parser) parseIdentExpr() (*Node, error) {
	tok := p.next() // consume identifier
	name := tok.value

	// Check for function call
	if p.peek().typ == TOK_LPAREN {
		return p.parseFuncCall(name, tok.line, tok.col)
	}

	// Check for 'as' binding
	if p.peek().typ == TOK_AS {
		// This is expr as pattern | body
		// But we're parsing the identifier, so it's: name as pattern
		// Actually 'as' is lower precedence, handled by parsePipeExpr
		// The identifier is just a function call with no args
		return &Node{typ: NodeCall, strVal: name, line: tok.line, col: tok.col}, nil
	}

	// Check for path(expr) which is a special expression
	if name == "path" && p.peek().typ == TOK_LPAREN {
		p.next() // consume '('
		pathExpr, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if _, err := p.expect(TOK_RPAREN); err != nil {
			return nil, err
		}
		return &Node{typ: NodePath, children: []*Node{pathExpr}, line: tok.line, col: tok.col}, nil
	}

	// Regular function call with no args (or builtin)
	return &Node{typ: NodeCall, strVal: name, line: tok.line, col: tok.col}, nil
}

func (p *Parser) parseFuncCall(name string, line, col int) (*Node, error) {
	p.next() // consume '('

	if p.peek().typ == TOK_RPAREN {
		p.next()
		return &Node{typ: NodeCall, strVal: name, line: line, col: col}, nil
	}

	var args []*Node
	for {
		arg, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		args = append(args, arg)
		if p.peek().typ == TOK_SEMICOLON {
			p.next()
		} else {
			break
		}
	}

	if _, err := p.expect(TOK_RPAREN); err != nil {
		return nil, err
	}

	return &Node{typ: NodeCall, strVal: name, children: args, line: line, col: col}, nil
}

// parseAsBinding handles "expr as $x | body" or "expr as $x | body | ..."
// This is called after parsing the LHS expression when we see 'as'
func (p *Parser) parseAsBinding(left *Node) (*Node, error) {
	tok := p.next() // consume 'as'

	pattern, err := p.parsePattern()
	if err != nil {
		return nil, err
	}

	// Expect '|'
	if _, err := p.expect(TOK_PIPE); err != nil {
		return nil, err
	}

	body, err := p.parsePipeExpr()
	if err != nil {
		return nil, err
	}

	return &Node{
		typ:      NodeAs,
		children: []*Node{left, body},
		bindings: []NodeBinding{{pattern: pattern}},
		line:     tok.line, col: tok.col,
	}, nil
