// Parser for jq language
type Parser struct {
	lexer    *Lexer
	filename string
	errors   []string
	defs     []NodeDef // global function definitions
}

type ParseCompileError struct {
	msg  string
	line int
	col  int
	expr string
}

func (e *ParseCompileError) Error() string {
	return e.msg
}

func NewParser(input, filename string) *Parser {
	return &Parser{
		lexer:    NewLexer(input),
		filename: filename,
	}
}

func (p *Parser) error(msg string, tok Token) error {
	return &ParseCompileError{
		msg:  msg,
		line: tok.line,
		col:  tok.col,
	}
}

func (p *Parser) peek() Token {
	return p.lexer.Peek()
}

func (p *Parser) next() Token {
	return p.lexer.Next()
}

func (p *Parser) expect(typ TokenType) (Token, error) {
	tok := p.next()
	if tok.typ != typ {
		return tok, fmt.Errorf("expected %v, got %v at line %d, column %d", typ, tok.typ, tok.line, tok.col)
	}
	return tok, nil
}

// Parse the complete program
func ParseProgram(input, filename string) (*Node, []NodeDef, error) {
	p := NewParser(input, filename)

	// First pass: collect all defs
	defs := []NodeDef{}

	// Parse the main expression (which may include defs at the top)
	expr, err := p.parseTopLevel()
	if err != nil {
		return nil, nil, err
	}

	tok := p.peek()
	if tok.typ != TOK_EOF {
		return nil, nil, fmt.Errorf("syntax error, unexpected %s at line %d, column %d", tokenDesc(tok), tok.line, tok.col)
	}

	// Collect defs from expr
	collectDefs(expr, &defs)

	return expr, defs, nil
}

func tokenDesc(tok Token) string {
	switch tok.typ {
	case TOK_EOF:
		return "EOF"
	case TOK_IDENT:
		return "IDENT"
	case TOK_PIPE:
		return "PIPE"
	case TOK_COMMA:
		return "COMMA"
	case TOK_DOT:
		return "DOT"
	case TOK_RBRACE:
		return "}"
	case TOK_RBRACKET:
		return "]"
	case TOK_RPAREN:
		return ")"
	case TOK_SEMICOLON:
		return ";"
	default:
		if tok.value != "" {
			return tok.value
		}
		return fmt.Sprintf("token(%d)", tok.typ)
	}
}

func (p *Parser) parseTopLevel() (*Node, error) {
	return p.parseExpr()
}

func (p *Parser) parseExpr() (*Node, error) {
	// Parse def or main expression
	var defs []NodeDef
	for p.peek().typ == TOK_DEF {
		def, err := p.parseDef()
		if err != nil {
			return nil, err
		}
		defs = append(defs, def)
		if p.peek().typ == TOK_SEMICOLON {
			p.next()
		}
	}

	// Handle import/include/module (ignore for now, just skip)
	for p.peek().typ == TOK_IMPORT || p.peek().typ == TOK_INCLUDE || p.peek().typ == TOK_MODULE {
		if err := p.parseImport(); err != nil {
			return nil, err
		}
	}
	// More defs after imports
	for p.peek().typ == TOK_DEF {
		def, err := p.parseDef()
		if err != nil {
			return nil, err
		}
		defs = append(defs, def)
		if p.peek().typ == TOK_SEMICOLON {
			p.next()
		}
	}

	expr, err := p.parseCommaExpr()
	if err != nil {
		return nil, err
	}

	// Wrap with defs if any
	if len(defs) > 0 {
		node := &Node{typ: NodeDef, defs: defs, children: []*Node{expr}}
		return node, nil
	}

	return expr, nil
}

func (p *Parser) parseImport() error {
	tok := p.next() // consume import/include/module keyword
	_ = tok
	// Skip until semicolon
	depth := 0
	for {
		t := p.next()
		if t.typ == TOK_EOF {
			break
		}
		if t.typ == TOK_LPAREN || t.typ == TOK_LBRACKET || t.typ == TOK_LBRACE {
			depth++
		} else if t.typ == TOK_RPAREN || t.typ == TOK_RBRACKET || t.typ == TOK_RBRACE {
			depth--
		} else if t.typ == TOK_SEMICOLON && depth == 0 {
			break
		}
	}
	return nil
}

func (p *Parser) parseDef() (NodeDef, error) {
	tok := p.next() // consume 'def'
	line, col := tok.line, tok.col

	nameTok := p.next()
	if nameTok.typ != TOK_IDENT {
		return NodeDef{}, fmt.Errorf("expected function name after 'def' at line %d", nameTok.line)
	}
	name := nameTok.value

	var params []string
	if p.peek().typ == TOK_LPAREN {
		p.next() // consume '('
		for p.peek().typ != TOK_RPAREN {
			paramTok := p.next()
			if paramTok.typ == TOK_DOLLAR_IDENT {
				params = append(params, "$"+paramTok.value)
			} else if paramTok.typ == TOK_IDENT {
				params = append(params, paramTok.value)
			} else {
				return NodeDef{}, fmt.Errorf("expected parameter name at line %d", paramTok.line)
			}
			if p.peek().typ == TOK_SEMICOLON {
				p.next()
			} else {
				break
			}
		}
		if _, err := p.expect(TOK_RPAREN); err != nil {
			return NodeDef{}, err
		}
	}

	if _, err := p.expect(TOK_COLON); err != nil {
		return NodeDef{}, fmt.Errorf("expected ':' after def name at line %d", line)
	}

	body, err := p.parseExpr()
	if err != nil {
		return NodeDef{}, err
	}

	return NodeDef{name: name, params: params, body: body, line: line, col: col}, nil
}

// parseCommaExpr handles comma-separated expressions (lowest precedence)
func (p *Parser) parseCommaExpr() (*Node, error) {
	left, err := p.parsePipeExpr()
	if err != nil {
		return nil, err
	}

	for p.peek().typ == TOK_COMMA {
		tok := p.next()
		right, err := p.parsePipeExpr()
		if err != nil {
			return nil, err
		}
		left = binop(NodeComma, left, right, tok.line, tok.col)
	}

	return left, nil
}

// parsePipeExpr handles pipe operator
func (p *Parser) parsePipeExpr() (*Node, error) {
	// Handle label-break
	if p.peek().typ == TOK_LABEL {
		return p.parseLabelExpr()
	}

	left, err := p.parseAssignExpr()
	if err != nil {
		return nil, err
