func (p *Parser) parseLabelExpr() (*Node, error) {
	tok := p.next() // consume 'label'
	varTok := p.next()
	if varTok.typ != TOK_DOLLAR_IDENT {
		return nil, fmt.Errorf("expected $name after label at line %d", tok.line)
