		right, err := p.parseAddExpr()
		if err != nil {
			return nil, err
		}
		return binop(NodeGe, left, right, tok.line, tok.col), nil
	}

	return left, nil
}

// parseAddExpr handles +, -
func (p *Parser) parseAddExpr() (*Node, error) {
	left, err := p.parseMulExpr()
	if err != nil {
		return nil, err
	}

	for {
		tok := p.peek()
		if tok.typ == TOK_PLUS {
			p.next()
			right, err := p.parseMulExpr()
			if err != nil {
				return nil, err
			}
			left = binop(NodeAdd, left, right, tok.line, tok.col)
		} else if tok.typ == TOK_MINUS {
			p.next()
			right, err := p.parseMulExpr()
			if err != nil {
				return nil, err
			}
			left = binop(NodeSub, left, right, tok.line, tok.col)
		} else {
			break
		}
	}

	return left, nil
}

// parseMulExpr handles *, /, %
func (p *Parser) parseMulExpr() (*Node, error) {
	left, err := p.parseUnaryExpr()
	if err != nil {
		return nil, err
	}

	for {
		tok := p.peek()
		if tok.typ == TOK_STAR {
			p.next()
			right, err := p.parseUnaryExpr()
			if err != nil {
				return nil, err
			}
			left = binop(NodeMul, left, right, tok.line, tok.col)
		} else if tok.typ == TOK_SLASH {
			p.next()
			right, err := p.parseUnaryExpr()
			if err != nil {
				return nil, err
			}
			left = binop(NodeDiv, left, right, tok.line, tok.col)
		} else if tok.typ == TOK_PERCENT {
			p.next()
			right, err := p.parseUnaryExpr()
			if err != nil {
				return nil, err
			}
			left = binop(NodeMod, left, right, tok.line, tok.col)
		} else {
			break
		}
