	case TOK_DOT:
		return "DOT"
	case TOK_RBRACE:
		return "}"
	case TOK_RBRACKET:
		return "]"
	case TOK_RPAREN:
		return ")"
	case TOK_SEMICOLON:
		return ";"
	default:
