// Deep equality
func JVEqual(a, b *JV) bool {
	if a.kind != b.kind {
		return false
	}
	switch a.kind {
	case JVKindNull, JVKindFalse, JVKindTrue:
		return true
	case JVKindNumber:
		if math.IsNaN(a.numVal) && math.IsNaN(b.numVal) {
			return true
		}
		return a.numVal == b.numVal
	case JVKindString:
		return a.strVal == b.strVal
	case JVKindArray:
		if len(a.arrVal) != len(b.arrVal) {
			return false
		}
		for i := range a.arrVal {
			if !JVEqual(a.arrVal[i], b.arrVal[i]) {
				return false
			}
		}
		return true
	case JVKindObject:
		if a.ObjLen() != b.ObjLen() {
			return false
		}
		for _, k := range a.ObjKeys() {
			bv, ok := b.ObjGet(k)
			if !ok {
				return false
			}
			if !JVEqual(a.objData.vals[k], bv) {
				return false
			}
		}
		return true
	}
	return false
}

// Total ordering for jq comparison
func JVCmp(a, b *JV) int {
	oa, ob := typeOrd(a), typeOrd(b)
	if oa != ob {
		if oa < ob {
			return -1
		}
		return 1
	}
	switch a.kind {
	case JVKindNull, JVKindFalse, JVKindTrue:
		return 0
	case JVKindNumber:
