			return -1
		}
		if a.strVal > b.strVal {
			return 1
		}
		return 0
	case JVKindArray:
		la, lb := len(a.arrVal), len(b.arrVal)
		m := la
		if lb < m {
			m = lb
		}
		for i := 0; i < m; i++ {
			if c := JVCmp(a.arrVal[i], b.arrVal[i]); c != 0 {
