// Number formatting
func formatNum(f float64) string {
	if math.IsNaN(f) {
		return "null"
	}
	if math.IsInf(f, 1) {
		return "1.7976931348623157e+308"
	}
	if math.IsInf(f, -1) {
		return "-1.7976931348623157e+308"
	}
	// Use shortest representation
	s := strconv.FormatFloat(f, 'g', -1, 64)
	return fixupNumber(s)
}

func formatNumLit(f float64) string {
	if math.IsNaN(f) {
		return "null"
	}
	if math.IsInf(f, 1) {
		return "1.7976931348623157e+308"
	}
	if math.IsInf(f, -1) {
		return "-1.7976931348623157e+308"
	}
	// Use 17 significant digits for literal numbers with decimal
	s := strconv.FormatFloat(f, 'g', 17, 64)
	return fixupNumber(s)
}

func fixupNumber(s string) string {
	// Convert Go e notation to uppercase E and normalize exponent
	if i := strings.IndexByte(s, 'e'); i >= 0 {
		mant := s[:i]
		exp := s[i+1:]
		sign := "+"
		if len(exp) > 0 && exp[0] == '-' {
			sign = "-"
			exp = exp[1:]
		} else if len(exp) > 0 && exp[0] == '+' {
			exp = exp[1:]
		}
		// Remove leading zeros
		for len(exp) > 1 && exp[0] == '0' {
			exp = exp[1:]
		}
		return mant + "E" + sign + exp
	}
	return s
}

// JV to JSON string
func jvToJSONStr(v *JV) string {
	var sb strings.Builder
	writeJVJSON(&sb, v)
	return sb.String()
}

func writeJVJSON(sb *strings.Builder, v *JV) {
	switch v.kind {
	case JVKindNull:
		sb.WriteString("null")
	case JVKindFalse:
		sb.WriteString("false")
	case JVKindTrue:
		sb.WriteString("true")
	case JVKindNumber:
		if v.numLit {
			sb.WriteString(formatNumLit(v.numVal))
		} else {
			sb.WriteString(formatNum(v.numVal))
		}
	case JVKindString:
		writeJSONStr(sb, v.strVal, false)
	case JVKindArray:
		sb.WriteByte('[')
		for i, item := range v.arrVal {
			if i > 0 {
				sb.WriteByte(',')
			}
			writeJVJSON(sb, item)
		}
		sb.WriteByte(']')
	case JVKindObject:
		sb.WriteByte('{')
		first := true
		if v.objData != nil {
			for _, k := range v.objData.keys {
				if !first {
					sb.WriteByte(',')
				}
				first = false
				writeJSONStr(sb, k, false)
				sb.WriteByte(':')
				writeJVJSON(sb, v.objData.vals[k])
			}
		}
		sb.WriteByte('}')
	}
}

func writeJSONStr(sb *strings.Builder, s string, asciiOnly bool) {
	sb.WriteByte('"')
	for _, r := range s {
		if asciiOnly && r > 127 {
			if r > 0xFFFF {
				r -= 0x10000
				high := 0xD800 + (r>>10)&0x3FF
				low := 0xDC00 + r&0x3FF
				fmt.Fprintf(sb, "\\u%04x\\u%04x", high, low)
			} else {
				fmt.Fprintf(sb, "\\u%04x", r)
			}
			continue
		}
		switch r {
		case '"':
			sb.WriteString(`\"`)
		case '\\':
			sb.WriteString(`\\`)
		case '\b':
			sb.WriteString(`\b`)
		case '\f':
			sb.WriteString(`\f`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		default:
			if r < 0x20 {
				fmt.Fprintf(sb, "\\u%04x", r)
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteByte('"')
}

