			return -1
		}
		if la > lb {
			return 1
		}
		return 0
	case JVKindObject:
		akeys := append([]string(nil), a.ObjKeys()...)
		bkeys := append([]string(nil), b.ObjKeys()...)
		sort.Strings(akeys)
		sort.Strings(bkeys)
		la, lb := len(akeys), len(bkeys)
		m := la
		if lb < m {
			m = lb
		}
		for i := 0; i < m; i++ {
			if akeys[i] < bkeys[i] {
				return -1
			}
			if akeys[i] > bkeys[i] {
				return 1
			}
			av, _ := a.ObjGet(akeys[i])
			bv, _ := b.ObjGet(bkeys[i])
			if c := JVCmp(av, bv); c != 0 {
				return c
			}
		}
		if la < lb {
			return -1
		}
		if la > lb {
			return 1
		}
		return 0
	}
	return 0
}

func typeOrd(v *JV) int {
	switch v.kind {
	case JVKindNull:
		return 0
	case JVKindFalse:
		return 1
	case JVKindTrue:
		return 2
	case JVKindNumber:
		return 3
	case JVKindString:
		return 4
	case JVKindArray:
		return 5
	case JVKindObject:
		return 6
	}
	return -1
}

// JVContains implements jq 'contains'
func JVContains(a, b *JV) bool {
	switch b.kind {
	case JVKindNull:
		return true
	case JVKindFalse, JVKindTrue:
		return a.kind == b.kind
	case JVKindNumber:
		return a.kind == JVKindNumber && a.numVal == b.numVal
	case JVKindString:
		return a.kind == JVKindString && strings.Contains(a.strVal, b.strVal)
	case JVKindArray:
		if a.kind != JVKindArray {
			return false
		}
		for _, bi := range b.arrVal {
			found := false
			for _, ai := range a.arrVal {
				if JVContains(ai, bi) {
					found = true
					break
				}
			}
			if !found {
				return false
			}
		}
		return true
	case JVKindObject:
		if a.kind != JVKindObject {
			return false
		}
		for _, k := range b.ObjKeys() {
			av, ok := a.ObjGet(k)
			if !ok {
				return false
			}
			bv, _ := b.ObjGet(k)
			if !JVContains(av, bv) {
				return false
			}
		}
		return true
	}
	return false
}

// Number formatting
func formatNum(f float64) string {
	if math.IsNaN(f) {
		return "null"
	}
	if math.IsInf(f, 1) {
		return "1.7976931348623157e+308"
	}
	if math.IsInf(f, -1) {
		return "-1.7976931348623157e+308"
	}
	// Use shortest representation
	s := strconv.FormatFloat(f, 'g', -1, 64)
	return fixupNumber(s)
}

func formatNumLit(f float64) string {
	if math.IsNaN(f) {
		return "null"
	}
	if math.IsInf(f, 1) {
		return "1.7976931348623157e+308"
	}
	if math.IsInf(f, -1) {
		return "-1.7976931348623157e+308"
	}
	// Use 17 significant digits for literal numbers with decimal
	s := strconv.FormatFloat(f, 'g', 17, 64)
	return fixupNumber(s)
}

func fixupNumber(s string) string {
	// Convert Go e notation to uppercase E and normalize exponent
	if i := strings.IndexByte(s, 'e'); i >= 0 {
		mant := s[:i]
		exp := s[i+1:]
		sign := "+"
		if len(exp) > 0 && exp[0] == '-' {
			sign = "-"
			exp = exp[1:]
		} else if len(exp) > 0 && exp[0] == '+' {
			exp = exp[1:]
		}
		// Remove leading zeros
		for len(exp) > 1 && exp[0] == '0' {
			exp = exp[1:]
		}
		return mant + "E" + sign + exp
	}
	return s
}

// JV to JSON string
func jvToJSONStr(v *JV) string {
	var sb strings.Builder
	writeJVJSON(&sb, v)
	return sb.String()
}

func writeJVJSON(sb *strings.Builder, v *JV) {
	switch v.kind {
	case JVKindNull:
		sb.WriteString("null")
	case JVKindFalse:
		sb.WriteString("false")
	case JVKindTrue:
		sb.WriteString("true")
	case JVKindNumber:
		if v.numLit {
			sb.WriteString(formatNumLit(v.numVal))
		} else {
			sb.WriteString(formatNum(v.numVal))
		}
	case JVKindString:
		writeJSONStr(sb, v.strVal, false)
	case JVKindArray:
		sb.WriteByte('[')
		for i, item := range v.arrVal {
			if i > 0 {
				sb.WriteByte(',')
			}
			writeJVJSON(sb, item)
		}
		sb.WriteByte(']')
	case JVKindObject:
		sb.WriteByte('{')
		first := true
		if v.objData != nil {
			for _, k := range v.objData.keys {
				if !first {
					sb.WriteByte(',')
				}
				first = false
				writeJSONStr(sb, k, false)
				sb.WriteByte(':')
				writeJVJSON(sb, v.objData.vals[k])
			}
		}
		sb.WriteByte('}')
	}
}

func writeJSONStr(sb *strings.Builder, s string, asciiOnly bool) {
	sb.WriteByte('"')
	for _, r := range s {
		if asciiOnly && r > 127 {
			if r > 0xFFFF {
				r -= 0x10000
				high := 0xD800 + (r>>10)&0x3FF
				low := 0xDC00 + r&0x3FF
				fmt.Fprintf(sb, "\\u%04x\\u%04x", high, low)
			} else {
				fmt.Fprintf(sb, "\\u%04x", r)
			}
			continue
		}
		switch r {
		case '"':
			sb.WriteString(`\"`)
		case '\\':
			sb.WriteString(`\\`)
		case '\b':
			sb.WriteString(`\b`)
		case '\f':
			sb.WriteString(`\f`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		default:
			if r < 0x20 {
				fmt.Fprintf(sb, "\\u%04x", r)
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteByte('"')
}

func utf8ByteLen(s string) int { return len(s) }
func runeLen(s string) int     { return utf8.RuneCountInString(s) }
