package main

import (
	"fmt"
	"sort"
	"strings"
)

const (
	colorReset  = "\033[0m"
	colorNull   = "\033[0;90m"
	colorBool   = "\033[0;39m"
	colorNum    = "\033[0;39m"
	colorStr    = "\033[0;32m"
	colorKey    = "\033[1;34m"
	colorPunct  = "\033[1;39m"
)

type Printer struct {
	sb        strings.Builder
	indent    int    // -1 = compact
	tab       bool
	colorize  bool
	sortKeys  bool
	asciiOnly bool
}

func NewPrinter(indent int, tab, colorize, sortKeys, asciiOnly bool) *Printer {
	return &Printer{indent: indent, tab: tab, colorize: colorize, sortKeys: sortKeys, asciiOnly: asciiOnly}
}

func (p *Printer) Print(v *JV) string {
	p.sb.Reset()
	p.write(v, 0)
	return p.sb.String()
}

func (p *Printer) color(c string) {
	if p.colorize {
		p.sb.WriteString(c)
	}
}

func (p *Printer) writeIndent(depth int) {
	if p.tab {
		for i := 0; i < depth; i++ {
			p.sb.WriteByte('\t')
		}
	} else if p.indent > 0 {
		for i := 0; i < depth*p.indent; i++ {
			p.sb.WriteByte(' ')
		}
	}
}

func (p *Printer) write(v *JV, depth int) {
	switch v.kind {
	case JVKindNull:
		p.color(colorNull)
		p.sb.WriteString("null")
		p.color(colorReset)
	case JVKindFalse:
		p.color(colorBool)
		p.sb.WriteString("false")
		p.color(colorReset)
	case JVKindTrue:
		p.color(colorBool)
		p.sb.WriteString("true")
		p.color(colorReset)
	case JVKindNumber:
		p.color(colorNum)
		if v.numLit {
			p.sb.WriteString(formatNumLit(v.numVal))
		} else {
			p.sb.WriteString(formatNum(v.numVal))
		}
		p.color(colorReset)
	case JVKindString:
		p.color(colorStr)
		writeJSONStr(&p.sb, v.strVal, p.asciiOnly)
		p.color(colorReset)
	case JVKindArray:
		p.writeArray(v, depth)
	case JVKindObject:
		p.writeObject(v, depth)
	}
}

func (p *Printer) writeArray(v *JV, depth int) {
	p.color(colorPunct)
	p.sb.WriteByte('[')
	p.color(colorReset)

	items := v.arrVal
	if len(items) == 0 {
		p.color(colorPunct)
		p.sb.WriteByte(']')
		p.color(colorReset)
		return
	}

	if p.indent < 0 && !p.tab {
		// compact
		for i, item := range items {
			if i > 0 {
				p.sb.WriteByte(',')
			}
			p.write(item, depth+1)
		}
	} else {
		p.sb.WriteByte('\n')
		for i, item := range items {
			p.writeIndent(depth + 1)
			p.write(item, depth+1)
			if i < len(items)-1 {
				p.color(colorPunct)
				p.sb.WriteByte(',')
				p.color(colorReset)
			}
			p.sb.WriteByte('\n')
		}
		p.writeIndent(depth)
	}

	p.color(colorPunct)
	p.sb.WriteByte(']')
	p.color(colorReset)
}

func (p *Printer) writeObject(v *JV, depth int) {
	p.color(colorPunct)
	p.sb.WriteByte('{')
	p.color(colorReset)

	if v.objData == nil || len(v.objData.keys) == 0 {
		p.color(colorPunct)
		p.sb.WriteByte('}')
		p.color(colorReset)
		return
	}

	keys := v.objData.keys
	if p.sortKeys {
		keys = append([]string(nil), keys...)
		sort.Strings(keys)
	}

	if p.indent < 0 && !p.tab {
		// compact
		for i, k := range keys {
			if i > 0 {
				p.sb.WriteByte(',')
			}
			p.color(colorKey)
			writeJSONStr(&p.sb, k, p.asciiOnly)
			p.color(colorReset)
			p.color(colorPunct)
			p.sb.WriteByte(':')
			p.color(colorReset)
			p.write(v.objData.vals[k], depth+1)
		}
	} else {
		p.sb.WriteByte('\n')
		for i, k := range keys {
			p.writeIndent(depth + 1)
			p.color(colorKey)
			writeJSONStr(&p.sb, k, p.asciiOnly)
			p.color(colorReset)
			p.color(colorPunct)
			p.sb.WriteByte(':')
			p.color(colorReset)
			p.sb.WriteByte(' ')
			p.write(v.objData.vals[k], depth+1)
			if i < len(keys)-1 {
				p.color(colorPunct)
				p.sb.WriteByte(',')
				p.color(colorReset)
			}
			p.sb.WriteByte('\n')
		}
		p.writeIndent(depth)
	}

	p.color(colorPunct)
	p.sb.WriteByte('}')
	p.color(colorReset)
}

// For printing to stderr (compact, no color)
func printCompact(v *JV) string {
	pr := NewPrinter(-1, false, false, false, false)
	return pr.Print(v)
}

// Numbers
func _ () { fmt.Println("") }
