				return nil, &JSONError{fmt.Sprintf("Invalid escape '\\%c'", esc), p.line, p.col}
			}
		} else if c < 0x20 {
			return nil, &JSONError{"Control character in string", p.line, p.col}
		} else {
			// UTF-8
			r, size := utf8.DecodeRuneInString(p.s[p.pos:])
			if r == utf8.RuneError && size == 1 {
				buf = append(buf, c)
				p.adv()
			} else {
				buf = append(buf, p.s[p.pos:p.pos+size]...)
				p.pos += size
			}
		}
	}
}

func (p *JSONParser) parseNum() (*JV, error) {
	start := p.pos
	hasDot := false
	hasExp := false

	if p.pos < len(p.s) && p.s[p.pos] == '-' {
		p.adv()
	}
	if p.pos >= len(p.s) {
		return nil, &JSONError{fmt.Sprintf("Invalid numeric literal at EOF at line %d, column %d", p.line, p.col), p.line, p.col}
	}
	if p.s[p.pos] == '0' {
		p.adv()
	} else if p.s[p.pos] >= '1' && p.s[p.pos] <= '9' {
		for p.pos < len(p.s) && p.s[p.pos] >= '0' && p.s[p.pos] <= '9' {
			p.adv()
		}
	} else {
		return nil, &JSONError{fmt.Sprintf("Invalid numeric literal at EOF at line %d, column %d", p.line, p.col), p.line, p.col}
	}

	if p.pos < len(p.s) && p.s[p.pos] == '.' {
		hasDot = true
		p.adv()
		if p.pos >= len(p.s) || p.s[p.pos] < '0' || p.s[p.pos] > '9' {
			return nil, &JSONError{"Invalid number (decimal needs digits)", p.line, p.col}
		}
		for p.pos < len(p.s) && p.s[p.pos] >= '0' && p.s[p.pos] <= '9' {
			p.adv()
		}
	}

	if p.pos < len(p.s) && (p.s[p.pos] == 'e' || p.s[p.pos] == 'E') {
		hasExp = true
		p.adv()
		if p.pos < len(p.s) && (p.s[p.pos] == '+' || p.s[p.pos] == '-') {
			p.adv()
		}
		if p.pos >= len(p.s) || p.s[p.pos] < '0' || p.s[p.pos] > '9' {
			return nil, &JSONError{"Invalid number (exponent needs digits)", p.line, p.col}
		}
		for p.pos < len(p.s) && p.s[p.pos] >= '0' && p.s[p.pos] <= '9' {
			p.adv()
		}
	}

	numStr := p.s[start:p.pos]
	f, err := strconv.ParseFloat(numStr, 64)
	if err != nil {
		return nil, &JSONError{fmt.Sprintf("Invalid number: %s", numStr), p.line, p.col}
	}

	if hasDot || hasExp {
		return JVNumLit(f), nil
	}
	return JVNum(f), nil
}

func (p *JSONParser) parseArr() (*JV, error) {
	p.adv() // '['
	p.ws()
	if p.pos < len(p.s) && p.s[p.pos] == ']' {
		p.adv()
		return JVEmptyArr(), nil
	}
	var items []*JV
	for {
		v, err := p.parseVal()
		if err != nil {
			return nil, err
		}
		items = append(items, v)
		p.ws()
		if p.pos >= len(p.s) {
			return nil, &JSONError{"Unterminated array", p.line, p.col}
		}
		c := p.s[p.pos]
		if c == ']' {
			p.adv()
			return &JV{kind: JVKindArray, arrVal: items}, nil
		}
		if c != ',' {
			return nil, &JSONError{fmt.Sprintf("Expected ',' or ']', got '%c'", c), p.line, p.col}
		}
		p.adv()
	}
}

func (p *JSONParser) parseObj() (*JV, error) {
	p.adv() // '{'
	p.ws()
	if p.pos < len(p.s) && p.s[p.pos] == '}' {
		p.adv()
		return JVEmptyObj(), nil
	}
	od := &objData{vals: map[string]*JV{}}
	for {
		p.ws()
		if p.pos >= len(p.s) || p.s[p.pos] != '"' {
			if p.pos < len(p.s) {
				return nil, &JSONError{fmt.Sprintf("Expected string key, got '%c'", p.s[p.pos]), p.line, p.col}
			}
			return nil, &JSONError{"Unterminated object", p.line, p.col}
		}
		kv, err := p.parseStr()
		if err != nil {
			return nil, err
		}
		key := kv.strVal
		p.ws()
		if p.pos >= len(p.s) || p.s[p.pos] != ':' {
			return nil, &JSONError{"Expected ':', got something else", p.line, p.col}
		}
		p.adv()
		val, err := p.parseVal()
		if err != nil {
			return nil, err
		}
		if _, exists := od.vals[key]; !exists {
			od.keys = append(od.keys, key)
		}
		od.vals[key] = val
		p.ws()
		if p.pos >= len(p.s) {
			return nil, &JSONError{"Unterminated object", p.line, p.col}
		}
		c := p.s[p.pos]
		if c == '}' {
			p.adv()
			return &JV{kind: JVKindObject, objData: od}, nil
		}
		if c != ',' {
			return nil, &JSONError{fmt.Sprintf("Expected ',' or '}', got '%c'", c), p.line, p.col}
		}
		p.adv()
	}
}
GOEOF
