package main

import (
	"strconv"
	"strings"
)

type TType int

const (
	T_EOF TType = iota
	T_NULL
	T_TRUE
	T_FALSE
	T_NUM
	T_STR     // simple string token
	T_STRPART // string part in interpolation
	T_INTERPSTART
	T_INTERPEND
	T_FMT    // @name
	T_IDENT
	T_DOLLAR // $name
	T_DOT
	T_DOTDOT
	T_COMMA
	T_COLON
	T_SEMI
	T_PIPE
	T_QUEST
	T_PLUS
	T_MINUS
	T_STAR
	T_SLASH
	T_PCT
	T_EQ
	T_NEQ
	T_LT
	T_LE
	T_GT
	T_GE
	T_AND
	T_OR
	T_NOT
	T_ASSIGN
	T_PIPEEQ   // |=
	T_PLUSEQ
	T_MINUSEQ
	T_STAREQ
	T_SLASHEQ
	T_PCTEQ
	T_ALTEQ    // //=
	T_ALT      // //
	T_TRYALT   // ?//
	T_LPAREN
	T_RPAREN
	T_LBRACK
	T_RBRACK
	T_LBRACE
	T_RBRACE
	T_IF
	T_THEN
	T_ELSE
	T_ELIF
	T_END
	T_AS
	T_DEF
	T_REDUCE
	T_FOREACH
	T_LABEL
	T_BREAK
	T_TRY
	T_CATCH
	T_IMPORT
	T_INCLUDE
	T_MODULE
)

type Tok struct {
	typ       TType
	sval      string
	nval      float64
	numHasDot bool
	numHasExp bool
	line      int
	col       int
}

// Tokenize a jq expression
func Tokenize(src string) []Tok {
	l := &lex{s: src, line: 1}
	l.run()
	return l.toks
}

type lex struct {
	s    string
	pos  int
	line int
	col  int
	toks []Tok
}

func (l *lex) cur() byte {
	if l.pos >= len(l.s) {
		return 0
	}
	return l.s[l.pos]
}

func (l *lex) peek1() byte {
	if l.pos+1 >= len(l.s) {
		return 0
	}
	return l.s[l.pos+1]
}

func (l *lex) adv() byte {
	if l.pos >= len(l.s) {
		return 0
	}
	c := l.s[l.pos]
	l.pos++
	if c == '\n' {
		l.line++
		l.col = 0
	} else {
		l.col++
	}
	return c
}

func (l *lex) ws() {
	for l.pos < len(l.s) {
		c := l.s[l.pos]
		if c == ' ' || c == '\t' || c == '\r' || c == '\n' {
			l.adv()
		} else if c == '#' {
			for l.pos < len(l.s) && l.s[l.pos] != '\n' {
				l.adv()
			}
		} else {
			break
		}
	}
}

func (l *lex) emit(t TType, sval string, line, col int) {
	l.toks = append(l.toks, Tok{typ: t, sval: sval, line: line, col: col})
}

func (l *lex) emitN(t TType, n float64, hasDot, hasExp bool, line, col int) {
	l.toks = append(l.toks, Tok{typ: t, nval: n, numHasDot: hasDot, numHasExp: hasExp, sval: "", line: line, col: col})
}

func (l *lex) run() {
	for {
		l.ws()
		if l.pos >= len(l.s) {
			l.emit(T_EOF, "", l.line, l.col)
			return
		}
		ln, col := l.line, l.col
		c := l.s[l.pos]

		switch c {
		case '.':
			l.adv()
			if l.cur() == '.' {
				l.adv()
				l.emit(T_DOTDOT, "", ln, col)
			} else {
				l.emit(T_DOT, "", ln, col)
			}
		case ',':
			l.adv()
			l.emit(T_COMMA, "", ln, col)
		case ':':
			l.adv()
			l.emit(T_COLON, "", ln, col)
		case ';':
			l.adv()
			l.emit(T_SEMI, "", ln, col)
		case '(':
			l.adv()
			l.emit(T_LPAREN, "", ln, col)
		case ')':
			l.adv()
			l.emit(T_RPAREN, "", ln, col)
		case '[':
			l.adv()
			l.emit(T_LBRACK, "", ln, col)
		case ']':
			l.adv()
			l.emit(T_RBRACK, "", ln, col)
		case '{':
			l.adv()
			l.emit(T_LBRACE, "", ln, col)
		case '}':
			l.adv()
			l.emit(T_RBRACE, "", ln, col)
		case '+':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_PLUSEQ, "", ln, col)
			} else {
				l.emit(T_PLUS, "", ln, col)
			}
		case '-':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_MINUSEQ, "", ln, col)
			} else {
				l.emit(T_MINUS, "", ln, col)
			}
		case '*':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_STAREQ, "", ln, col)
			} else {
				l.emit(T_STAR, "", ln, col)
			}
		case '/':
			l.adv()
			if l.cur() == '/' {
				l.adv()
				if l.cur() == '=' {
					l.adv()
					l.emit(T_ALTEQ, "", ln, col)
				} else {
					l.emit(T_ALT, "", ln, col)
				}
			} else if l.cur() == '=' {
				l.adv()
				l.emit(T_SLASHEQ, "", ln, col)
			} else {
				l.emit(T_SLASH, "", ln, col)
			}
		case '%':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_PCTEQ, "", ln, col)
			} else {
				l.emit(T_PCT, "", ln, col)
			}
		case '|':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_PIPEEQ, "", ln, col)
			} else {
				l.emit(T_PIPE, "", ln, col)
			}
		case '=':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_EQ, "", ln, col)
			} else {
				l.emit(T_ASSIGN, "", ln, col)
			}
		case '!':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_NEQ, "", ln, col)
			} else {
				// not an operator in jq by itself
				l.emit(T_NEQ, "!", ln, col) // hack
			}
		case '<':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_LE, "", ln, col)
			} else {
				l.emit(T_LT, "", ln, col)
			}
		case '>':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_GE, "", ln, col)
			} else {
				l.emit(T_GT, "", ln, col)
			}
		case '?':
			l.adv()
			if l.cur() == '/' && l.peek1() == '/' {
				l.adv()
				l.adv()
				l.emit(T_TRYALT, "", ln, col)
			} else {
				l.emit(T_QUEST, "", ln, col)
			}
		case '$':
			l.adv()
			if isIDStart(l.cur()) {
				name := l.readIdent()
				l.emit(T_DOLLAR, name, ln, col)
			}
		case '@':
			l.adv()
			if isIDStart(l.cur()) {
				name := l.readIdent()
				l.emit(T_FMT, name, ln, col)
			}
		case '"':
			l.lexString(ln, col)
		default:
			if isIDStart(c) {
				name := l.readIdent()
				t := identType(name)
				l.emit(t, name, ln, col)
			} else if c >= '0' && c <= '9' {
				l.lexNum(ln, col)
			} else {
				l.adv() // skip unknown
			}
		}
	}
}

func (l *lex) readIdent() string {
	start := l.pos
	for l.pos < len(l.s) && isIDChar(l.s[l.pos]) {
		l.pos++
	}
	return l.s[start:l.pos]
}

func (l *lex) lexNum(ln, col int) {
	start := l.pos
	hasDot := false
	hasExp := false

	for l.pos < len(l.s) && l.s[l.pos] >= '0' && l.s[l.pos] <= '9' {
		l.pos++
	}
	if l.pos < len(l.s) && l.s[l.pos] == '.' && l.pos+1 < len(l.s) && l.s[l.pos+1] >= '0' && l.s[l.pos+1] <= '9' {
		hasDot = true
		l.pos++
		for l.pos < len(l.s) && l.s[l.pos] >= '0' && l.s[l.pos] <= '9' {
			l.pos++
		}
	}
	if l.pos < len(l.s) && (l.s[l.pos] == 'e' || l.s[l.pos] == 'E') {
		hasExp = true
		l.pos++
		if l.pos < len(l.s) && (l.s[l.pos] == '+' || l.s[l.pos] == '-') {
			l.pos++
		}
		for l.pos < len(l.s) && l.s[l.pos] >= '0' && l.s[l.pos] <= '9' {
			l.pos++
		}
	}

	numStr := l.s[start:l.pos]
	f, _ := strconv.ParseFloat(numStr, 64)
	l.emitN(T_NUM, f, hasDot, hasExp, ln, col)
}

// lexString handles string literals with interpolation
// It emits:
//   T_STR for simple strings
//   T_STRPART, T_INTERPSTART, [tokens], T_INTERPEND, T_STRPART for interpolated
// For interpolated strings with nested strings, we handle that recursively
func (l *lex) lexString(ln, col int) {
	l.adv() // consume '"'
	l.lexStringContent(ln, col)
}

func (l *lex) lexStringContent(ln, col int) {
	var parts []Tok
	var cur strings.Builder
	isInterp := false

	for {
		if l.pos >= len(l.s) {
			break
		}
		c := l.s[l.pos]
		if c == '"' {
			l.adv()
			if !isInterp {
				l.emit(T_STR, cur.String(), ln, col)
			} else {
				parts = append(parts, Tok{typ: T_STRPART, sval: cur.String(), line: ln, col: col})
				l.toks = append(l.toks, parts...)
			}
			return
		}
		if c == '\\' {
			l.adv()
			if l.pos >= len(l.s) {
				break
			}
			esc := l.s[l.pos]
			l.adv()
			if esc == '(' {
				// String interpolation
				isInterp = true
				parts = append(parts, Tok{typ: T_STRPART, sval: cur.String(), line: ln, col: col})
				cur.Reset()
				parts = append(parts, Tok{typ: T_INTERPSTART, line: l.line, col: l.col})
				// Tokenize the interpolation expression
				// We need to find matching ')' accounting for depth
				startPos := l.pos
				depth := 1
				for l.pos < len(l.s) && depth > 0 {
					ch := l.s[l.pos]
					if ch == '(' {
						depth++
						l.adv()
					} else if ch == ')' {
						depth--
						if depth == 0 {
							break
						}
						l.adv()
					} else if ch == '"' {
						// Skip string
						l.adv()
						l.lexStringContentFlat()
					} else if ch == '#' {
						for l.pos < len(l.s) && l.s[l.pos] != '\n' {
							l.adv()
						}
					} else {
						l.adv()
					}
				}
				endPos := l.pos
				// Tokenize the interpolation content
				sub := l.s[startPos:endPos]
				subLex := &lex{s: sub, line: ln, col: col + (startPos - 0)}
				subLex.run()
				// Add sub-tokens (excluding T_EOF)
				for _, st := range subLex.toks {
					if st.typ != T_EOF {
						l.toks = append(l.toks, st)
					}
				}
				// Actually we need to add to parts array, not directly to toks
				// But this approach is wrong - let me fix
				// The issue is that parts is being built and toks have already had stuff appended
				// Let me redo this
				_ = sub
				_ = subLex
				l.pos = endPos
				if l.pos < len(l.s) && l.s[l.pos] == ')' {
					l.adv()
				}
				parts = append(parts, Tok{typ: T_INTERPEND, line: l.line, col: l.col})
				continue
			}
			// Regular escape
			switch esc {
			case '"':
				cur.WriteByte('"')
			case '\\':
				cur.WriteByte('\\')
			case '/':
				cur.WriteByte('/')
			case 'b':
				cur.WriteByte('\b')
			case 'f':
				cur.WriteByte('\f')
			case 'n':
				cur.WriteByte('\n')
			case 'r':
				cur.WriteByte('\r')
			case 't':
				cur.WriteByte('\t')
			case 'u':
				if l.pos+4 <= len(l.s) {
					code, err := strconv.ParseInt(l.s[l.pos:l.pos+4], 16, 32)
					if err == nil {
						r := rune(code)
						if r >= 0xD800 && r <= 0xDBFF && l.pos+10 <= len(l.s) &&
							l.s[l.pos+4] == '\\' && l.s[l.pos+5] == 'u' {
							low, err2 := strconv.ParseInt(l.s[l.pos+6:l.pos+10], 16, 32)
							if err2 == nil && low >= 0xDC00 && low <= 0xDFFF {
								r = rune(0x10000 + (r-0xD800)*0x400 + (rune(low) - 0xDC00))
								l.pos += 10
								cur.WriteRune(r)
								continue
							}
						}
						l.pos += 4
						cur.WriteRune(r)
					}
				}
			default:
				cur.WriteByte('\\')
				cur.WriteByte(esc)
			}
		} else {
			l.adv()
			cur.WriteByte(c)
		}
	}
	// Fallthrough - emit what we have
	if !isInterp {
		l.emit(T_STR, cur.String(), ln, col)
	} else {
		parts = append(parts, Tok{typ: T_STRPART, sval: cur.String(), line: ln, col: col})
		l.toks = append(l.toks, parts...)
	}
}

func (l *lex) lexStringContentFlat() {
	// Skip a string (for counting depth in interpolations)
	for l.pos < len(l.s) {
		c := l.s[l.pos]
		if c == '"' {
			l.adv()
			return
		}
		if c == '\\' {
			l.adv()
			if l.pos < len(l.s) {
				l.adv()
			}
		} else {
			l.adv()
		}
	}
}

func isIDStart(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'
}
func isIDChar(c byte) bool {
	return isIDStart(c) || (c >= '0' && c <= '9')
}

func identType(name string) TType {
	switch name {
	case "null":
		return T_NULL
	case "true":
		return T_TRUE
	case "false":
		return T_FALSE
	case "if":
		return T_IF
	case "then":
		return T_THEN
	case "else":
		return T_ELSE
	case "elif":
		return T_ELIF
	case "end":
		return T_END
	case "as":
		return T_AS
	case "def":
		return T_DEF
	case "reduce":
		return T_REDUCE
	case "foreach":
		return T_FOREACH
	case "label":
		return T_LABEL
	case "break":
		return T_BREAK
	case "try":
		return T_TRY
	case "catch":
		return T_CATCH
	case "and":
		return T_AND
	case "or":
		return T_OR
	case "not":
		return T_NOT
	case "import":
		return T_IMPORT
	case "include":
		return T_INCLUDE
	case "module":
		return T_MODULE
	default:
		return T_IDENT
	}
}
