			}
		case '*':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_STAREQ, "", ln, col)
			} else {
				l.emit(T_STAR, "", ln, col)
			}
		case '/':
			l.adv()
			if l.cur() == '/' {
				l.adv()
				if l.cur() == '=' {
					l.adv()
					l.emit(T_ALTEQ, "", ln, col)
				} else {
					l.emit(T_ALT, "", ln, col)
				}
			} else if l.cur() == '=' {
				l.adv()
				l.emit(T_SLASHEQ, "", ln, col)
			} else {
				l.emit(T_SLASH, "", ln, col)
			}
		case '%':
			l.adv()
			if l.cur() == '=' {
