				l.adv()
				l.emit(T_PIPEEQ, "", ln, col)
			} else {
				l.emit(T_PIPE, "", ln, col)
			}
		case '=':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_EQ, "", ln, col)
			} else {
