			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_GE, "", ln, col)
			} else {
				l.emit(T_GT, "", ln, col)
			}
		case '?':
			l.adv()
			if l.cur() == '/' && l.peek1() == '/' {
				l.adv()
				l.adv()
				l.emit(T_TRYALT, "", ln, col)
			} else {
				l.emit(T_QUEST, "", ln, col)
			}
