				sub := l.s[startPos:endPos]
				subLex := &lex{s: sub, line: ln, col: col + (startPos - 0)}
				subLex.run()
				// Add sub-tokens (excluding T_EOF)
				for _, st := range subLex.toks {
					if st.typ != T_EOF {
