					l.adv()
				}
				parts = append(parts, Tok{typ: T_INTERPEND, line: l.line, col: l.col})
				continue
			}
			// Regular escape
			switch esc {
			case '"':
				cur.WriteByte('"')
			case '\\':
				cur.WriteByte('\\')
			case '/':
				cur.WriteByte('/')
			case 'b':
				cur.WriteByte('\b')
			case 'f':
				cur.WriteByte('\f')
			case 'n':
				cur.WriteByte('\n')
			case 'r':
				cur.WriteByte('\r')
			case 't':
				cur.WriteByte('\t')
			case 'u':
				if l.pos+4 <= len(l.s) {
					code, err := strconv.ParseInt(l.s[l.pos:l.pos+4], 16, 32)
					if err == nil {
						r := rune(code)
						if r >= 0xD800 && r <= 0xDBFF && l.pos+10 <= len(l.s) &&
							l.s[l.pos+4] == '\\' && l.s[l.pos+5] == 'u' {
							low, err2 := strconv.ParseInt(l.s[l.pos+6:l.pos+10], 16, 32)
							if err2 == nil && low >= 0xDC00 && low <= 0xDFFF {
								r = rune(0x10000 + (r-0xD800)*0x400 + (rune(low) - 0xDC00))
								l.pos += 10
								cur.WriteRune(r)
								continue
							}
						}
						l.pos += 4
						cur.WriteRune(r)
					}
				}
			default:
				cur.WriteByte('\\')
				cur.WriteByte(esc)
			}
		} else {
			l.adv()
			cur.WriteByte(c)
		}
	}
	// Fallthrough - emit what we have
	if !isInterp {
		l.emit(T_STR, cur.String(), ln, col)
	} else {
		parts = append(parts, Tok{typ: T_STRPART, sval: cur.String(), line: ln, col: col})
		l.toks = append(l.toks, parts...)
	}
