			l.adv()
			if l.pos >= len(l.s) {
				break
			}
			esc := l.s[l.pos]
			l.adv()
			switch esc {
			case '"':
				cur.WriteByte('"')
			case '\\':
				cur.WriteByte('\\')
			case '/':
				cur.WriteByte('/')
			case 'b':
				cur.WriteByte('\b')
			case 'f':
				cur.WriteByte('\f')
			case 'n':
				cur.WriteByte('\n')
			case 'r':
				cur.WriteByte('\r')
			case 't':
				cur.WriteByte('\t')
			case 'u':
				if l.pos+4 <= len(l.s) {
					code, err := strconv.ParseInt(l.s[l.pos:l.pos+4], 16, 32)
					if err == nil {
						r := rune(code)
						if r >= 0xD800 && r <= 0xDBFF && l.pos+10 <= len(l.s) &&
							l.s[l.pos+4] == '\\' && l.s[l.pos+5] == 'u' {
							low, err2 := strconv.ParseInt(l.s[l.pos+6:l.pos+10], 16, 32)
