	T_PIPEEQ
	T_PLUSEQ
	T_MINUSEQ
	T_STAREQ
	T_SLASHEQ
	T_PCTEQ
	T_ALTEQ
	T_ALT
	T_TRYALT
	T_LPAREN
	T_RPAREN
	T_LBRACK
	T_RBRACK
	T_LBRACE
	T_RBRACE
	T_IF
