)

type Tok struct {
	typ       TType
	sval      string
	nval      float64
	numHasDot bool
	numHasExp bool
	line      int
	col       int
}

func Tokenize(src string) ([]Tok, error) {
	l := &lexer{s: src, line: 1}
	err := l.run()
	return l.toks, err
}

type lexer struct {
	s    string
	pos  int
	line int
	col  int
	toks []Tok
	// String interpolation depth tracking
	// Each level of string interpolation adds to this stack
}

func (l *lexer) cur() byte {
	if l.pos >= len(l.s) {
		return 0
	}
	return l.s[l.pos]
}

func (l *lexer) look(n int) byte {
	if l.pos+n >= len(l.s) {
		return 0
	}
	return l.s[l.pos+n]
}

func (l *lexer) adv() byte {
	if l.pos >= len(l.s) {
		return 0
	}
	c := l.s[l.pos]
	l.pos++
	if c == '\n' {
		l.line++
		l.col = 0
	} else {
		l.col++
	}
	return c
}

func (l *lexer) ws() {
	for l.pos < len(l.s) {
		c := l.s[l.pos]
		if c == ' ' || c == '\t' || c == '\r' || c == '\n' {
			l.adv()
		} else if c == '#' {
			for l.pos < len(l.s) && l.s[l.pos] != '\n' {
				l.pos++
			}
		} else {
			break
		}
	}
}

func (l *lexer) emit(t TType, s string, ln, col int) {
	l.toks = append(l.toks, Tok{typ: t, sval: s, line: ln, col: col})
}

func (l *lexer) emitN(t TType, n float64, hd, he bool, ln, col int) {
	l.toks = append(l.toks, Tok{typ: t, nval: n, numHasDot: hd, numHasExp: he, line: ln, col: col})
}

func (l *lexer) run() error {
	for {
		l.ws()
		if l.pos >= len(l.s) {
			l.emit(T_EOF, "", l.line, l.col)
			return nil
		}
		ln, col := l.line, l.col
		c := l.s[l.pos]

		switch c {
		case '.':
			l.adv()
			if l.cur() == '.' {
				l.adv()
				l.emit(T_DOTDOT, "", ln, col)
			} else {
				l.emit(T_DOT, "", ln, col)
			}
		case ',':
			l.adv()
			l.emit(T_COMMA, "", ln, col)
		case ':':
			l.adv()
			l.emit(T_COLON, "", ln, col)
		case ';':
			l.adv()
			l.emit(T_SEMI, "", ln, col)
		case '(':
			l.adv()
			l.emit(T_LPAREN, "", ln, col)
		case ')':
			l.adv()
			l.emit(T_RPAREN, "", ln, col)
		case '[':
			l.adv()
			l.emit(T_LBRACK, "", ln, col)
		case ']':
			l.adv()
			l.emit(T_RBRACK, "", ln, col)
		case '{':
			l.adv()
			l.emit(T_LBRACE, "", ln, col)
		case '}':
			l.adv()
			l.emit(T_RBRACE, "", ln, col)
		case '+':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_PLUSEQ, "", ln, col)
			} else {
				l.emit(T_PLUS, "", ln, col)
			}
		case '-':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_MINUSEQ, "", ln, col)
			} else {
				l.emit(T_MINUS, "", ln, col)
			}
		case '*':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_STAREQ, "", ln, col)
			} else {
				l.emit(T_STAR, "", ln, col)
			}
		case '/':
			l.adv()
			if l.cur() == '/' {
				l.adv()
				if l.cur() == '=' {
					l.adv()
					l.emit(T_ALTEQ, "", ln, col)
				} else {
					l.emit(T_ALT, "", ln, col)
				}
			} else if l.cur() == '=' {
				l.adv()
				l.emit(T_SLASHEQ, "", ln, col)
			} else {
				l.emit(T_SLASH, "", ln, col)
			}
		case '%':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_PCTEQ, "", ln, col)
			} else {
				l.emit(T_PCT, "", ln, col)
			}
		case '|':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_PIPEEQ, "", ln, col)
			} else {
				l.emit(T_PIPE, "", ln, col)
			}
		case '=':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_EQ, "", ln, col)
			} else {
				l.emit(T_ASSIGN, "", ln, col)
			}
		case '!':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_NEQ, "", ln, col)
			}
		case '<':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_LE, "", ln, col)
			} else {
				l.emit(T_LT, "", ln, col)
			}
		case '>':
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_GE, "", ln, col)
			} else {
				l.emit(T_GT, "", ln, col)
			}
		case '?':
			l.adv()
			if l.cur() == '/' && l.look(1) == '/' {
				l.adv()
				l.adv()
				l.emit(T_TRYALT, "", ln, col)
			} else {
				l.emit(T_QUEST, "", ln, col)
			}
		case '$':
			l.adv()
			if isIDStart(l.cur()) {
				name := l.readIdent()
				l.emit(T_DOLLAR, name, ln, col)
			} else {
				// lone $ - skip
			}
		case '@':
			l.adv()
			if isIDStart(l.cur()) {
				name := l.readIdent()
				l.emit(T_FMT, name, ln, col)
			}
		case '"':
			if err := l.lexString(ln, col); err != nil {
				return err
			}
		default:
			if isIDStart(c) {
				name := l.readIdent()
				l.emit(identTType(name), name, ln, col)
			} else if c >= '0' && c <= '9' {
				l.lexNum(ln, col)
			} else {
				l.adv()
			}
		}
	}
}

func (l *lexer) readIdent() string {
	start := l.pos
	for l.pos < len(l.s) && isIDChar(l.s[l.pos]) {
		l.pos++
	}
	return l.s[start:l.pos]
}

func (l *lexer) lexNum(ln, col int) {
	start := l.pos
	hasDot, hasExp := false, false
	for l.pos < len(l.s) && l.s[l.pos] >= '0' && l.s[l.pos] <= '9' {
		l.pos++
	}
	if l.pos < len(l.s) && l.s[l.pos] == '.' && l.pos+1 < len(l.s) && l.s[l.pos+1] >= '0' && l.s[l.pos+1] <= '9' {
		hasDot = true
		l.pos++
		for l.pos < len(l.s) && l.s[l.pos] >= '0' && l.s[l.pos] <= '9' {
			l.pos++
		}
	}
	if l.pos < len(l.s) && (l.s[l.pos] == 'e' || l.s[l.pos] == 'E') {
		hasExp = true
		l.pos++
		if l.pos < len(l.s) && (l.s[l.pos] == '+' || l.s[l.pos] == '-') {
			l.pos++
		}
		for l.pos < len(l.s) && l.s[l.pos] >= '0' && l.s[l.pos] <= '9' {
			l.pos++
		}
	}
	f, _ := strconv.ParseFloat(l.s[start:l.pos], 64)
	l.emitN(T_NUM, f, hasDot, hasExp, ln, col)
}

// lexString tokenizes a string literal, possibly with \(...) interpolation
// Produces: T_STR for simple strings
// Or: T_STRPART, T_INTSTART, [tokens...], T_INTEND, T_STRPART, ... for interpolated
func (l *lexer) lexString(ln, col int) error {
	l.adv() // consume opening '"'

	var cur strings.Builder
	hasInterp := false

	for {
		if l.pos >= len(l.s) {
			// Error: unterminated
			if !hasInterp {
				l.emit(T_STR, cur.String(), ln, col)
			} else {
				l.emit(T_STRPART, cur.String(), ln, col)
			}
			return nil
		}

		c := l.s[l.pos]

		if c == '"' {
			l.adv()
			if !hasInterp {
				l.emit(T_STR, cur.String(), ln, col)
			} else {
				l.emit(T_STRPART, cur.String(), ln, col)
			}
			return nil
		}

		if c == '\\' && l.pos+1 < len(l.s) && l.s[l.pos+1] == '(' {
			// String interpolation
			hasInterp = true
			// Emit current string part
			l.emit(T_STRPART, cur.String(), ln, col)
			cur.Reset()
			l.adv() // skip '\'
			l.adv() // skip '('
			l.emit(T_INTSTART, "", l.line, l.col)

			// Now tokenize until matching ')'
			// We need to track nested strings and parens
			depth := 1
			for l.pos < len(l.s) && depth > 0 {
				l.ws()
				if l.pos >= len(l.s) {
					break
				}
				ch := l.s[l.pos]
				chln, chcol := l.line, l.col

				if ch == '(' {
					l.adv()
					l.emit(T_LPAREN, "", chln, chcol)
					depth++
				} else if ch == ')' {
					depth--
					if depth == 0 {
						break
					}
					l.adv()
					l.emit(T_RPAREN, "", chln, chcol)
				} else if ch == '"' {
					// Nested string
					if err := l.lexString(chln, chcol); err != nil {
						return err
					}
				} else {
					// Regular tokenize
					l.tokenizeOne()
				}
			}

			if l.pos < len(l.s) && l.s[l.pos] == ')' {
				l.adv()
			}
			l.emit(T_INTEND, "", l.line, l.col)
			continue
		}

		if c == '\\' {
			l.adv()
			if l.pos >= len(l.s) {
				break
			}
			esc := l.s[l.pos]
			l.adv()
			switch esc {
			case '"':
				cur.WriteByte('"')
			case '\\':
				cur.WriteByte('\\')
			case '/':
				cur.WriteByte('/')
			case 'b':
				cur.WriteByte('\b')
			case 'f':
				cur.WriteByte('\f')
			case 'n':
				cur.WriteByte('\n')
			case 'r':
				cur.WriteByte('\r')
			case 't':
				cur.WriteByte('\t')
			case 'u':
				if l.pos+4 <= len(l.s) {
					code, err := strconv.ParseInt(l.s[l.pos:l.pos+4], 16, 32)
					if err == nil {
						r := rune(code)
						if r >= 0xD800 && r <= 0xDBFF && l.pos+10 <= len(l.s) &&
							l.s[l.pos+4] == '\\' && l.s[l.pos+5] == 'u' {
							low, err2 := strconv.ParseInt(l.s[l.pos+6:l.pos+10], 16, 32)
							if err2 == nil && low >= 0xDC00 && low <= 0xDFFF {
								r = rune(0x10000 + (r-0xD800)*0x400 + (rune(low) - 0xDC00))
								l.pos += 10
								cur.WriteRune(r)
								continue
							}
						}
						l.pos += 4
						cur.WriteRune(r)
					}
				}
			default:
				cur.WriteByte('\\')
				cur.WriteByte(esc)
			}
		} else {
			// Read UTF-8 rune
			r, size := utf8.DecodeRuneInString(l.s[l.pos:])
			if r == utf8.RuneError && size == 1 {
				cur.WriteByte(c)
				l.adv()
			} else {
				cur.WriteString(l.s[l.pos : l.pos+size])
				l.pos += size
			}
		}
	}
	if !hasInterp {
		l.emit(T_STR, cur.String(), ln, col)
	} else {
		l.emit(T_STRPART, cur.String(), ln, col)
	}
	return nil
}

// tokenizeOne tokenizes a single token (used inside interpolations)
func (l *lexer) tokenizeOne() {
	if l.pos >= len(l.s) {
		return
	}
	ln, col := l.line, l.col
	c := l.s[l.pos]

	switch c {
	case ',':
		l.adv()
		l.emit(T_COMMA, "", ln, col)
	case ':':
		l.adv()
		l.emit(T_COLON, "", ln, col)
	case ';':
		l.adv()
		l.emit(T_SEMI, "", ln, col)
	case '[':
		l.adv()
		l.emit(T_LBRACK, "", ln, col)
	case ']':
		l.adv()
		l.emit(T_RBRACK, "", ln, col)
	case '{':
		l.adv()
		l.emit(T_LBRACE, "", ln, col)
	case '}':
		l.adv()
		l.emit(T_RBRACE, "", ln, col)
	case '+':
		l.adv()
		if l.cur() == '=' {
			l.adv()
			l.emit(T_PLUSEQ, "", ln, col)
		} else {
			l.emit(T_PLUS, "", ln, col)
		}
	case '-':
		l.adv()
		if l.cur() == '=' {
			l.adv()
			l.emit(T_MINUSEQ, "", ln, col)
		} else {
			l.emit(T_MINUS, "", ln, col)
		}
	case '*':
		l.adv()
		if l.cur() == '=' {
			l.adv()
			l.emit(T_STAREQ, "", ln, col)
		} else {
			l.emit(T_STAR, "", ln, col)
		}
	case '/':
		l.adv()
		if l.cur() == '/' {
			l.adv()
			if l.cur() == '=' {
				l.adv()
				l.emit(T_ALTEQ, "", ln, col)
			} else {
				l.emit(T_ALT, "", ln, col)
			}
		} else if l.cur() == '=' {
			l.adv()
			l.emit(T_SLASHEQ, "", ln, col)
		} else {
			l.emit(T_SLASH, "", ln, col)
		}
	case '%':
		l.adv()
		if l.cur() == '=' {
			l.adv()
			l.emit(T_PCTEQ, "", ln, col)
		} else {
			l.emit(T_PCT, "", ln, col)
		}
	case '|':
		l.adv()
		if l.cur() == '=' {
			l.adv()
			l.emit(T_PIPEEQ, "", ln, col)
		} else {
			l.emit(T_PIPE, "", ln, col)
		}
	case '=':
		l.adv()
		if l.cur() == '=' {
			l.adv()
			l.emit(T_EQ, "", ln, col)
		} else {
			l.emit(T_ASSIGN, "", ln, col)
		}
	case '!':
		l.adv()
		if l.cur() == '=' {
			l.adv()
			l.emit(T_NEQ, "", ln, col)
		}
	case '<':
		l.adv()
		if l.cur() == '=' {
			l.adv()
			l.emit(T_LE, "", ln, col)
		} else {
			l.emit(T_LT, "", ln, col)
		}
	case '>':
		l.adv()
		if l.cur() == '=' {
			l.adv()
			l.emit(T_GE, "", ln, col)
		} else {
			l.emit(T_GT, "", ln, col)
		}
	case '?':
		l.adv()
		if l.cur() == '/' && l.look(1) == '/' {
			l.adv()
			l.adv()
			l.emit(T_TRYALT, "", ln, col)
		} else {
			l.emit(T_QUEST, "", ln, col)
		}
	case '.':
		l.adv()
		if l.cur() == '.' {
			l.adv()
			l.emit(T_DOTDOT, "", ln, col)
		} else {
			l.emit(T_DOT, "", ln, col)
		}
	case '$':
		l.adv()
		if isIDStart(l.cur()) {
			name := l.readIdent()
			l.emit(T_DOLLAR, name, ln, col)
		}
	case '@':
		l.adv()
		if isIDStart(l.cur()) {
			name := l.readIdent()
			l.emit(T_FMT, name, ln, col)
		}
	default:
		if isIDStart(c) {
			name := l.readIdent()
			l.emit(identTType(name), name, ln, col)
		} else if c >= '0' && c <= '9' {
			l.lexNum(ln, col)
		} else {
			l.adv()
		}
	}
}

func isIDStart(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'
}
func isIDChar(c byte) bool {
	return isIDStart(c) || (c >= '0' && c <= '9')
}

func identTType(name string) TType {
	switch name {
	case "null":
		return T_NULL
	case "true":
		return T_TRUE
	case "false":
		return T_FALSE
	case "if":
		return T_IF
	case "then":
		return T_THEN
	case "else":
		return T_ELSE
	case "elif":
		return T_ELIF
	case "end":
		return T_END
	case "as":
		return T_AS
	case "def":
		return T_DEF
	case "reduce":
		return T_REDUCE
	case "foreach":
		return T_FOREACH
	case "label":
		return T_LABEL
	case "break":
		return T_BREAK
	case "try":
		return T_TRY
	case "catch":
		return T_CATCH
	case "and":
		return T_AND
	case "or":
		return T_OR
	case "not":
		return T_NOT
	case "import":
		return T_IMPORT
	case "include":
		return T_INCLUDE
	case "module":
		return T_MODULE
	default:
		return T_IDENT
	}
}
