// Parse a jq expression from source
func Parse(src string) (*Node, error) {
	toks, err := Tokenize(src)
	if err != nil {
		return nil, fmt.Errorf("parse error: %v", err)
	}
	p := &parser{toks: toks, src: src}
	node, err := p.parseTop()
	if err != nil {
		return nil, err
	}
	if p.peek().typ != T_EOF {
		t := p.peek()
		return nil, fmt.Errorf("syntax error, unexpected %s at line %d, column %d",
			tokDesc(t), t.line, t.col)
	}
	return node, nil
}

type parser struct {
	toks []Tok
	pos  int
	src  string
}

func (p *parser) peek() Tok {
	if p.pos >= len(p.toks) {
		return Tok{typ: T_EOF}
	}
	return p.toks[p.pos]
}

func (p *parser) peekN(n int) Tok {
	i := p.pos + n
	if i >= len(p.toks) {
		return Tok{typ: T_EOF}
	}
	return p.toks[i]
}

func (p *parser) next() Tok {
	t := p.peek()
	if p.pos < len(p.toks) {
		p.pos++
	}
	return t
}

func (p *parser) back() {
	if p.pos > 0 {
		p.pos--
	}
}

func (p *parser) expect(t TType) (Tok, error) {
	tok := p.next()
	if tok.typ != t {
		return tok, fmt.Errorf("syntax error, unexpected %s (expected %s) at line %d, column %d",
			tokDesc(tok), tDesc(t), tok.line, tok.col)
	}
	return tok, nil
}

func tokDesc(t Tok) string {
	switch t.typ {
	case T_EOF:
		return "EOF"
	case T_IDENT:
		return fmt.Sprintf("IDENT '%s'", t.sval)
	case T_DOLLAR:
		return fmt.Sprintf("$%s", t.sval)
	case T_STR:
		return "string"
	case T_NUM:
		return "number"
	case T_PIPE:
		return "|"
	case T_COMMA:
		return ","
	case T_SEMI:
		return ";"
	case T_RPAREN:
		return ")"
	case T_RBRACK:
		return "]"
	case T_RBRACE:
		return "}"
	case T_AS:
		return "as"
	case T_IF:
		return "if"
	case T_THEN:
		return "then"
	case T_ELSE:
		return "else"
	case T_END:
		return "end"
	case T_DEF:
		return "def"
	default:
		if t.sval != "" {
			return t.sval
		}
		return fmt.Sprintf("token(%d)", t.typ)
	}
}

func tDesc(t TType) string {
	switch t {
	case T_EOF:
		return "EOF"
	case T_PIPE:
		return "|"
	case T_COMMA:
		return ","
	case T_SEMI:
		return ";"
	case T_RPAREN:
		return ")"
	case T_RBRACK:
		return "]"
	case T_RBRACE:
		return "}"
	case T_COLON:
		return ":"
	default:
		return fmt.Sprintf("token(%d)", t)
	}
}

// parseTop parses the top-level expression including leading defs/imports
func (p *parser) parseTop() (*Node, error) {
	return p.parseExp()
}

// parseExp = def* expr | import* def* expr
func (p *parser) parseExp() (*Node, error) {
	var defs []*FuncDef

	// Skip import/include/module directives
	for p.peek().typ == T_IMPORT || p.peek().typ == T_INCLUDE || p.peek().typ == T_MODULE {
		if err := p.skipDirective(); err != nil {
			return nil, err
		}
	}

	// Collect def blocks
	for p.peek().typ == T_DEF {
		def, err := p.parseDef()
		if err != nil {
			return nil, err
		}
		defs = append(defs, def)
		if p.peek().typ == T_SEMI {
			p.next()
		}
	}

	// More imports
	for p.peek().typ == T_IMPORT || p.peek().typ == T_INCLUDE || p.peek().typ == T_MODULE {
		if err := p.skipDirective(); err != nil {
			return nil, err
		}
	}

	// More defs
	for p.peek().typ == T_DEF {
		def, err := p.parseDef()
		if err != nil {
			return nil, err
		}
		defs = append(defs, def)
		if p.peek().typ == T_SEMI {
			p.next()
		}
	}

	body, err := p.parseComma()
	if err != nil {
		return nil, err
	}

	if len(defs) > 0 {
		n := &Node{typ: NDef, defs: defs, children: []*Node{body}, line: body.line, col: body.col}
		return n, nil
	}
	return body, nil
}

func (p *parser) skipDirective() error {
	p.next() // consume keyword
	depth := 0
	for {
		t := p.next()
		if t.typ == T_EOF {
			return nil
		}
		if t.typ == T_LPAREN || t.typ == T_LBRACK || t.typ == T_LBRACE {
			depth++
		} else if t.typ == T_RPAREN || t.typ == T_RBRACK || t.typ == T_RBRACE {
			depth--
		} else if t.typ == T_SEMI && depth == 0 {
			return nil
		}
	}
}

func (p *parser) parseDef() (*FuncDef, error) {
	tok, err := p.expect(T_DEF)
	if err != nil {
		return nil, err
	}

	nameTok := p.next()
	if nameTok.typ != T_IDENT {
		return nil, fmt.Errorf("expected function name after 'def' at line %d", tok.line)
	}
	name := nameTok.sval

	var params []string
	if p.peek().typ == T_LPAREN {
		p.next()
		for p.peek().typ != T_RPAREN && p.peek().typ != T_EOF {
			pt := p.next()
			if pt.typ == T_DOLLAR {
				params = append(params, "$"+pt.sval)
			} else if pt.typ == T_IDENT {
				params = append(params, pt.sval)
			} else {
				return nil, fmt.Errorf("expected param name at line %d", pt.line)
			}
			if p.peek().typ == T_SEMI {
				p.next()
			} else {
				break
			}
		}
		if _, err := p.expect(T_RPAREN); err != nil {
			return nil, err
		}
	}

	if _, err := p.expect(T_COLON); err != nil {
		return nil, fmt.Errorf("expected ':' after def name at line %d, column %d", tok.line, tok.col)
	}

	body, err := p.parseExp()
	if err != nil {
		return nil, err
	}

	return &FuncDef{name: name, params: params, body: body, line: tok.line}, nil
}

// parseComma handles comma (output generator)
func (p *parser) parseComma() (*Node, error) {
	left, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	for p.peek().typ == T_COMMA {
		tok := p.next()
		right, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		left = mknode(NComma, tok.line, tok.col, left, right)
	}
	return left, nil
}

// parsePipe handles pipe and 'as' binding
func (p *parser) parsePipe() (*Node, error) {
	// Check for label
	if p.peek().typ == T_LABEL {
		return p.parseLabel()
	}

	left, err := p.parseAssign()
	if err != nil {
		return nil, err
	}

	// Check for 'as' pattern binding
	if p.peek().typ == T_AS {
		tok := p.next() // consume 'as'
		pat, err := p.parsePattern()
		if err != nil {
			return nil, err
		}
		if _, err := p.expect(T_PIPE); err != nil {
			return nil, fmt.Errorf("expected '|' after pattern at line %d", tok.line)
		}
		body, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		n := &Node{typ: NAs, pattern: pat, children: []*Node{left, body}, line: tok.line, col: tok.col}
		return n, nil
	}

	for p.peek().typ == T_PIPE {
		tok := p.next()
		// After pipe, we might have a def
		if p.peek().typ == T_DEF {
			right, err := p.parseExp()
			if err != nil {
				return nil, err
			}
			left = mknode(NPipe, tok.line, tok.col, left, right)
			return left, nil
		}
		right, err := p.parseAssign()
		if err != nil {
			return nil, err
		}
		// Check for 'as' after right
		if p.peek().typ == T_AS {
			astok := p.next()
			pat, err := p.parsePattern()
			if err != nil {
				return nil, err
			}
			if _, err := p.expect(T_PIPE); err != nil {
				return nil, err
			}
			body, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			right = &Node{typ: NAs, pattern: pat, children: []*Node{right, body}, line: astok.line, col: astok.col}
		}
		left = mknode(NPipe, tok.line, tok.col, left, right)
	}

	return left, nil
}

func (p *parser) parseLabel() (*Node, error) {
	tok := p.next() // 'label'
	varTok := p.next()
	if varTok.typ != T_DOLLAR {
		return nil, fmt.Errorf("expected $name after label at line %d", tok.line)
	}
	if _, err := p.expect(T_PIPE); err != nil {
		return nil, err
	}
	body, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	return &Node{typ: NLabel, sval: varTok.sval, children: []*Node{body}, line: tok.line, col: tok.col}, nil
}

// parseAssign handles assignment operators (right-associative)
func (p *parser) parseAssign() (*Node, error) {
	left, err := p.parseAlt()
	if err != nil {
		return nil, err
	}

	tok := p.peek()
	var nt NType
	switch tok.typ {
	case T_ASSIGN:
		nt = NAssign
	case T_PIPEEQ:
		nt = NUpdate
	case T_PLUSEQ:
		nt = NAddEq
	case T_MINUSEQ:
		nt = NSubEq
	case T_STAREQ:
		nt = NMulEq
	case T_SLASHEQ:
		nt = NDivEq
	case T_PCTEQ:
		nt = NModEq
	case T_ALTEQ:
		nt = NAltEq
	default:
		return left, nil
	}

	p.next()
	right, err := p.parseAssign()
	if err != nil {
		return nil, err
	}
	return mknode(nt, tok.line, tok.col, left, right), nil
}

// parseAlt handles //
func (p *parser) parseAlt() (*Node, error) {
	left, err := p.parseOr()
	if err != nil {
		return nil, err
	}
	for {
		tok := p.peek()
		if tok.typ == T_ALT {
			p.next()
			right, err := p.parseOr()
			if err != nil {
				return nil, err
			}
			left = mknode(NAlt, tok.line, tok.col, left, right)
		} else if tok.typ == T_TRYALT {
			p.next()
			right, err := p.parseOr()
			if err != nil {
				return nil, err
			}
			left = mknode(NTryAlt, tok.line, tok.col, left, right)
		} else {
			break
		}
	}
	return left, nil
}

func (p *parser) parseOr() (*Node, error) {
	left, err := p.parseAnd()
	if err != nil {
		return nil, err
	}
	for p.peek().typ == T_OR {
		tok := p.next()
		right, err := p.parseAnd()
		if err != nil {
			return nil, err
		}
		left = mknode(NOr, tok.line, tok.col, left, right)
	}
	return left, nil
}

func (p *parser) parseAnd() (*Node, error) {
	left, err := p.parseNot()
	if err != nil {
		return nil, err
	}
	for p.peek().typ == T_AND {
		tok := p.next()
		right, err := p.parseNot()
		if err != nil {
			return nil, err
		}
		left = mknode(NAnd, tok.line, tok.col, left, right)
	}
	return left, nil
}

func (p *parser) parseNot() (*Node, error) {
	if p.peek().typ == T_NOT {
		tok := p.next()
		child, err := p.parseNot()
		if err != nil {
			return nil, err
		}
		return mknode(NNot, tok.line, tok.col, child), nil
	}
	return p.parseCmp()
}

func (p *parser) parseCmp() (*Node, error) {
	left, err := p.parseAdd()
	if err != nil {
		return nil, err
	}
	tok := p.peek()
	var nt NType
	switch tok.typ {
	case T_EQ:
		nt = NEq
	case T_NEQ:
		nt = NNeq
	case T_LT:
		nt = NLt
	case T_LE:
		nt = NLe
	case T_GT:
		nt = NGt
	case T_GE:
		nt = NGe
	default:
		return left, nil
	}
	p.next()
	right, err := p.parseAdd()
	if err != nil {
		return nil, err
	}
	return mknode(nt, tok.line, tok.col, left, right), nil
}

func (p *parser) parseAdd() (*Node, error) {
	left, err := p.parseMul()
	if err != nil {
		return nil, err
	}
	for {
		tok := p.peek()
		if tok.typ == T_PLUS {
			p.next()
			right, err := p.parseMul()
			if err != nil {
				return nil, err
			}
			left = mknode(NAdd, tok.line, tok.col, left, right)
		} else if tok.typ == T_MINUS {
			p.next()
			right, err := p.parseMul()
			if err != nil {
				return nil, err
			}
			left = mknode(NSub, tok.line, tok.col, left, right)
		} else {
			break
		}
	}
	return left, nil
}

func (p *parser) parseMul() (*Node, error) {
	left, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for {
		tok := p.peek()
		if tok.typ == T_STAR {
			p.next()
			right, err := p.parseUnary()
			if err != nil {
				return nil, err
			}
			left = mknode(NMul, tok.line, tok.col, left, right)
		} else if tok.typ == T_SLASH {
			p.next()
			right, err := p.parseUnary()
			if err != nil {
				return nil, err
			}
			left = mknode(NDiv, tok.line, tok.col, left, right)
		} else if tok.typ == T_PCT {
			p.next()
			right, err := p.parseUnary()
			if err != nil {
				return nil, err
			}
			left = mknode(NMod, tok.line, tok.col, left, right)
		} else {
			break
		}
	}
	return left, nil
}

func (p *parser) parseUnary() (*Node, error) {
	if p.peek().typ == T_MINUS {
		tok := p.next()
		child, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		if child.typ == NNum {
			child.nval = -child.nval
			return child, nil
		}
		zero := &Node{typ: NNum, nval: 0, line: tok.line, col: tok.col}
		return mknode(NSub, tok.line, tok.col, zero, child), nil
	}
	return p.parsePostfix()
}

// parsePostfix handles postfix operators and chained access
func (p *parser) parsePostfix() (*Node, error) {
	expr, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}

	for {
		tok := p.peek()
		switch tok.typ {
		case T_DOT:
			p.next()
			// .field, .["field"], or just dot
			next := p.peek()
			if next.typ == T_IDENT {
				p.next()
				nt := NField
				if p.peek().typ == T_QUEST {
					p.next()
					nt = NFieldOpt
				}
				n := &Node{typ: nt, sval: next.sval, children: []*Node{expr}, line: tok.line, col: tok.col}
				expr = n
			} else if next.typ == T_LBRACK {
				p.next()
				n, err := p.parseIdxOrSlice(expr, tok.line, tok.col)
				if err != nil {
					return nil, err
				}
				expr = n
			} else {
				// standalone dot - identity
				p.back()
				return expr, nil
			}
		case T_LBRACK:
			// direct index: expr[...]
			p.next()
			n, err := p.parseIdxOrSlice(expr, tok.line, tok.col)
			if err != nil {
				return nil, err
			}
			expr = n
		case T_QUEST:
			p.next()
			expr = &Node{typ: NOptional, children: []*Node{expr}, line: tok.line, col: tok.col}
		default:
			return expr, nil
		}
	}
}

func (p *parser) parseIdxOrSlice(base *Node, line, col int) (*Node, error) {
	// Already consumed '['
	if p.peek().typ == T_RBRACK {
		p.next()
		nt := NIter
		if p.peek().typ == T_QUEST {
			p.next()
			nt = NIterOpt
		}
		if base == nil {
			return &Node{typ: nt, line: line, col: col}, nil
		}
		return mknode(NPipe, line, col, base, &Node{typ: nt, line: line, col: col}), nil
	}

	if p.peek().typ == T_COLON {
		// [: end]
		p.next()
		var end *Node
		if p.peek().typ != T_RBRACK {
			var err error
			end, err = p.parseComma()
			if err != nil {
				return nil, err
			}
		}
		if _, err := p.expect(T_RBRACK); err != nil {
			return nil, err
		}
		nt := NSlice
		if p.peek().typ == T_QUEST {
			p.next()
			nt = NSliceOpt
		}
		sliceNode := &Node{typ: nt, children: []*Node{nil, end}, line: line, col: col}
		if base == nil {
			return sliceNode, nil
		}
		return mknode(NPipe, line, col, base, sliceNode), nil
	}

	first, err := p.parseComma()
	if err != nil {
		return nil, err
	}

	if p.peek().typ == T_COLON {
		p.next()
		var end *Node
		if p.peek().typ != T_RBRACK {
			end, err = p.parseComma()
			if err != nil {
				return nil, err
			}
		}
		if _, err := p.expect(T_RBRACK); err != nil {
			return nil, err
		}
		nt := NSlice
		if p.peek().typ == T_QUEST {
			p.next()
			nt = NSliceOpt
		}
		sliceNode := &Node{typ: nt, children: []*Node{first, end}, line: line, col: col}
		if base == nil {
			return sliceNode, nil
		}
		return mknode(NPipe, line, col, base, sliceNode), nil
	}

	if _, err := p.expect(T_RBRACK); err != nil {
		return nil, err
	}
	nt := NIdx
	if p.peek().typ == T_QUEST {
		p.next()
		nt = NIdxOpt
	}
	idxNode := &Node{typ: nt, children: []*Node{first}, line: line, col: col}
	if base == nil {
		return idxNode, nil
	}
	return mknode(NPipe, line, col, base, idxNode), nil
}

// parsePrimary handles primary expressions
func (p *parser) parsePrimary() (*Node, error) {
	tok := p.peek()
	switch tok.typ {
	case T_NULL:
		p.next()
		return &Node{typ: NNull, line: tok.line, col: tok.col}, nil
	case T_TRUE:
		p.next()
		return &Node{typ: NTrue, line: tok.line, col: tok.col}, nil
	case T_FALSE:
		p.next()
		return &Node{typ: NFalse, line: tok.line, col: tok.col}, nil
	case T_NUM:
		p.next()
		return &Node{typ: NNum, nval: tok.nval, numLit: tok.numHasDot || tok.numHasExp, line: tok.line, col: tok.col}, nil
	case T_STR:
		p.next()
		return &Node{typ: NStr, sval: tok.sval, line: tok.line, col: tok.col}, nil
	case T_STRPART:
		return p.parseInterpStr("", tok.line, tok.col)
	case T_FMT:
		return p.parseFmtExpr()
	case T_DOT:
		return p.parseDotExpr()
	case T_DOTDOT:
		p.next()
		return &Node{typ: NRecurse, line: tok.line, col: tok.col}, nil
	case T_DOLLAR:
		p.next()
		if tok.sval == "_ENV" || tok.sval == "ENV" {
			return &Node{typ: NEnv, line: tok.line, col: tok.col}, nil
		}
		if tok.sval == "__loc__" {
			return &Node{typ: NLoc, line: tok.line, col: tok.col}, nil
		}
		return &Node{typ: NVar, sval: tok.sval, line: tok.line, col: tok.col}, nil
	case T_LBRACK:
		return p.parseArrayExpr()
	case T_LBRACE:
		return p.parseObjExpr()
	case T_LPAREN:
		p.next()
		expr, err := p.parseExp()
		if err != nil {
			return nil, err
		}
		if _, err := p.expect(T_RPAREN); err != nil {
			return nil, err
		}
		return expr, nil
	case T_IF:
		return p.parseIf()
	case T_REDUCE:
		return p.parseReduce()
	case T_FOREACH:
		return p.parseForeach()
	case T_TRY:
		return p.parseTry()
	case T_BREAK:
		p.next()
		varTok := p.next()
		if varTok.typ != T_DOLLAR {
			return nil, fmt.Errorf("expected $name after break at line %d", tok.line)
		}
		return &Node{typ: NBreak, sval: varTok.sval, line: tok.line, col: tok.col}, nil
	case T_IDENT:
		return p.parseIdentExpr()
	default:
		return nil, fmt.Errorf("syntax error, unexpected %s at line %d, column %d",
			tokDesc(tok), tok.line, tok.col)
	}
}

func (p *parser) parseDotExpr() (*Node, error) {
	tok := p.next() // consume '.'
	next := p.peek()
	if next.typ == T_IDENT {
		p.next()
		nt := NField
		if p.peek().typ == T_QUEST {
			p.next()
			nt = NFieldOpt
		}
		return &Node{typ: nt, sval: next.sval, line: tok.line, col: tok.col}, nil
	}
	if next.typ == T_LBRACK {
		p.next()
		return p.parseIdxOrSlice(nil, tok.line, tok.col)
	}
	// Identity
	return &Node{typ: NIdent, line: tok.line, col: tok.col}, nil
}

func (p *parser) parseFmtExpr() (*Node, error) {
	tok := p.next() // @name
	fmtName := tok.sval

	// Check if followed by string
	if p.peek().typ == T_STR {
		strTok := p.next()
		strNode := &Node{typ: NStr, sval: strTok.sval, line: strTok.line, col: strTok.col}
		return &Node{typ: NFmtStr, sval: fmtName, children: []*Node{strNode}, line: tok.line, col: tok.col}, nil
	}
	if p.peek().typ == T_STRPART {
		strNode, err := p.parseInterpStr("", tok.line, tok.col)
		if err != nil {
			return nil, err
		}
		return &Node{typ: NFmtStr, sval: fmtName, children: []*Node{strNode}, line: tok.line, col: tok.col}, nil
	}

	return &Node{typ: NFmt, sval: fmtName, line: tok.line, col: tok.col}, nil
}

// parseInterpStr builds an NInterp node from STRPART/INTSTART tokens
func (p *parser) parseInterpStr(fmtName string, line, col int) (*Node, error) {
	n := &Node{typ: NInterp, sval: fmtName, line: line, col: col}

	for {
		tok := p.peek()
		if tok.typ == T_STRPART {
			p.next()
			n.children = append(n.children, &Node{typ: NStr, sval: tok.sval, line: tok.line, col: tok.col})
			n.computed = append(n.computed, false)
		} else if tok.typ == T_STR {
			p.next()
			n.children = append(n.children, &Node{typ: NStr, sval: tok.sval, line: tok.line, col: tok.col})
			n.computed = append(n.computed, false)
			return n, nil
		} else if tok.typ == T_INTSTART {
			p.next()
			expr, err := p.parseExp()
			if err != nil {
				return nil, err
			}
			if p.peek().typ == T_INTEND {
				p.next()
			}
			n.children = append(n.children, expr)
			n.computed = append(n.computed, true)
		} else {
			return n, nil
		}
	}
}

func (p *parser) parseArrayExpr() (*Node, error) {
	tok := p.next() // '['
	if p.peek().typ == T_RBRACK {
		p.next()
		return &Node{typ: NArray, line: tok.line, col: tok.col}, nil
	}
	expr, err := p.parseExp()
	if err != nil {
		return nil, err
	}
	if _, err := p.expect(T_RBRACK); err != nil {
		return nil, err
	}
	return &Node{typ: NArray, children: []*Node{expr}, line: tok.line, col: tok.col}, nil
}

func (p *parser) parseObjExpr() (*Node, error) {
	tok := p.next() // '{'
	if p.peek().typ == T_RBRACE {
		p.next()
		return &Node{typ: NObj, line: tok.line, col: tok.col}, nil
	}

	n := &Node{typ: NObj, line: tok.line, col: tok.col}

	for {
		keyTok := p.peek()
		var key *Node
		computed := false

		switch keyTok.typ {
		case T_LPAREN:
			p.next()
			computed = true
			var err error
			key, err = p.parseExp()
			if err != nil {
				return nil, err
			}
			if _, err := p.expect(T_RPAREN); err != nil {
				return nil, err
			}
		case T_IDENT:
			p.next()
			key = &Node{typ: NStr, sval: keyTok.sval, line: keyTok.line, col: keyTok.col}
		case T_STR:
			p.next()
			key = &Node{typ: NStr, sval: keyTok.sval, line: keyTok.line, col: keyTok.col}
		case T_STRPART:
			var err error
			key, err = p.parseInterpStr("", keyTok.line, keyTok.col)
			if err != nil {
				return nil, err
			}
			computed = true
		case T_DOLLAR:
			p.next()
			key = &Node{typ: NStr, sval: keyTok.sval, line: keyTok.line, col: keyTok.col}
		case T_NUM:
			p.next()
			key = &Node{typ: NStr, sval: strconv.FormatFloat(keyTok.nval, 'g', -1, 64), line: keyTok.line, col: keyTok.col}
		default:
			return nil, fmt.Errorf("expected object key at line %d, column %d", keyTok.line, keyTok.col)
		}

		n.computed = append(n.computed, computed)

		if !computed && p.peek().typ != T_COLON {
			// Shorthand: {foo} = {foo: .foo}
			n.children = append(n.children, key, nil)
		} else {
			if _, err := p.expect(T_COLON); err != nil {
				return nil, err
			}
			val, err := p.parsePipe()
			if err != nil {
				return nil, err
			}
			n.children = append(n.children, key, val)
		}

		if p.peek().typ == T_COMMA {
			p.next()
			if p.peek().typ == T_RBRACE {
				break
			}
			continue
		}
		break
	}

	if _, err := p.expect(T_RBRACE); err != nil {
		return nil, err
	}
	return n, nil
}

func (p *parser) parseIf() (*Node, error) {
	tok := p.next() // 'if'
	cond, err := p.parseExp()
	if err != nil {
		return nil, err
	}
	if _, err := p.expect(T_THEN); err != nil {
		return nil, fmt.Errorf("expected 'then' at line %d", tok.line)
	}
	thenExpr, err := p.parseExp()
	if err != nil {
		return nil, err
	}

	n := &Node{typ: NIf, children: []*Node{cond, thenExpr}, line: tok.line, col: tok.col}

	for p.peek().typ == T_ELIF {
		p.next()
		elifCond, err := p.parseExp()
		if err != nil {
			return nil, err
		}
		if _, err := p.expect(T_THEN); err != nil {
			return nil, err
		}
		elifThen, err := p.parseExp()
		if err != nil {
			return nil, err
		}
		n.children = append(n.children, elifCond, elifThen)
	}

	if p.peek().typ == T_ELSE {
		p.next()
		elseExpr, err := p.parseExp()
		if err != nil {
			return nil, err
		}
		n.children = append(n.children, elseExpr)
	}

	if _, err := p.expect(T_END); err != nil {
		return nil, fmt.Errorf("expected 'end' for if started at line %d", tok.line)
	}
	return n, nil
}

func (p *parser) parseReduce() (*Node, error) {
	tok := p.next() // 'reduce'
	gen, err := p.parsePostfix()
	if err != nil {
		return nil, err
	}
	if _, err := p.expect(T_AS); err != nil {
		return nil, err
	}
	pat, err := p.parsePattern()
	if err != nil {
		return nil, err
	}
	if _, err := p.expect(T_LPAREN); err != nil {
		return nil, err
	}
	init, err := p.parseExp()
	if err != nil {
		return nil, err
	}
	if _, err := p.expect(T_SEMI); err != nil {
		return nil, err
	}
	body, err := p.parseExp()
	if err != nil {
		return nil, err
	}
	if _, err := p.expect(T_RPAREN); err != nil {
		return nil, err
	}
	return &Node{typ: NReduce, pattern: pat, children: []*Node{gen, init, body}, line: tok.line, col: tok.col}, nil
}

func (p *parser) parseForeach() (*Node, error) {
	tok := p.next() // 'foreach'
	gen, err := p.parsePostfix()
	if err != nil {
		return nil, err
	}
	if _, err := p.expect(T_AS); err != nil {
		return nil, err
	}
	pat, err := p.parsePattern()
	if err != nil {
		return nil, err
	}
	if _, err := p.expect(T_LPAREN); err != nil {
		return nil, err
	}
	init, err := p.parseExp()
	if err != nil {
		return nil, err
	}
	if _, err := p.expect(T_SEMI); err != nil {
		return nil, err
	}
	update, err := p.parseExp()
	if err != nil {
		return nil, err
	}
	var extract *Node
	if p.peek().typ == T_SEMI {
		p.next()
		extract, err = p.parseExp()
		if err != nil {
			return nil, err
		}
	}
	if _, err := p.expect(T_RPAREN); err != nil {
		return nil, err
	}
	children := []*Node{gen, init, update}
	if extract != nil {
		children = append(children, extract)
	}
	return &Node{typ: NForeach, pattern: pat, children: children, line: tok.line, col: tok.col}, nil
}

func (p *parser) parseTry() (*Node, error) {
	tok := p.next() // 'try'
	body, err := p.parsePostfix()
	if err != nil {
		return nil, err
	}
	n := &Node{typ: NTry, children: []*Node{body}, line: tok.line, col: tok.col}
	if p.peek().typ == T_CATCH {
		p.next()
		handler, err := p.parsePostfix()
		if err != nil {
			return nil, err
		}
		n.children = append(n.children, handler)
	}
	return n, nil
}

func (p *parser) parsePattern() (*Node, error) {
	tok := p.peek()
	if tok.typ == T_DOLLAR {
		p.next()
		return &Node{typ: NVar, sval: tok.sval, line: tok.line, col: tok.col}, nil
	}
	if tok.typ == T_LBRACE {
		return p.parseObjPattern()
	}
	if tok.typ == T_LBRACK {
		return p.parseArrPattern()
	}
	return nil, fmt.Errorf("expected pattern ($name, {...}, [...]) at line %d, column %d", tok.line, tok.col)
}

func (p *parser) parseObjPattern() (*Node, error) {
	tok := p.next() // '{'
	n := &Node{typ: NObj, line: tok.line, col: tok.col}
	n.computed = append(n.computed, false) // marker: this is a pattern

	// Mark this as a pattern by using a special flag
	// Actually let's use a different NType for patterns
	n.typ = NObj // reuse NObj for object patterns, but mark it
	// We'll use n.sval = "pattern" to distinguish
	n.sval = "pattern"

	for p.peek().typ != T_RBRACE && p.peek().typ != T_EOF {
		kt := p.peek()
		var key string
		if kt.typ == T_IDENT {
			p.next()
			key = kt.sval
		} else if kt.typ == T_STR {
			p.next()
			key = kt.sval
		} else {
			return nil, fmt.Errorf("expected key in object pattern at line %d", kt.line)
		}
		keyNode := &Node{typ: NStr, sval: key, line: kt.line, col: kt.col}

		if p.peek().typ == T_COLON {
			p.next()
			valPat, err := p.parsePattern()
			if err != nil {
				return nil, err
			}
			n.children = append(n.children, keyNode, valPat)
		} else {
			n.children = append(n.children, keyNode, nil)
		}

		if p.peek().typ == T_COMMA {
			p.next()
		} else {
			break
		}
	}
	if _, err := p.expect(T_RBRACE); err != nil {
		return nil, err
	}
	return n, nil
}

func (p *parser) parseArrPattern() (*Node, error) {
	tok := p.next() // '['
	n := &Node{typ: NArray, sval: "pattern", line: tok.line, col: tok.col}
	for p.peek().typ != T_RBRACK && p.peek().typ != T_EOF {
		pat, err := p.parsePattern()
		if err != nil {
			return nil, err
		}
		n.children = append(n.children, pat)
		if p.peek().typ == T_COMMA {
			p.next()
		} else {
			break
		}
	}
	if _, err := p.expect(T_RBRACK); err != nil {
		return nil, err
	}
	return n, nil
}

func (p *parser) parseIdentExpr() (*Node, error) {
	tok := p.next()
	name := tok.sval

	if p.peek().typ == T_LPAREN {
		return p.parseFuncCall(name, tok.line, tok.col)
	}

	return &Node{typ: NCall, sval: name, line: tok.line, col: tok.col}, nil
}

func (p *parser) parseFuncCall(name string, line, col int) (*Node, error) {
	p.next() // '('
	if p.peek().typ == T_RPAREN {
		p.next()
		return &Node{typ: NCall, sval: name, line: line, col: col}, nil
	}

	n := &Node{typ: NCall, sval: name, line: line, col: col}
	for {
		arg, err := p.parseExp()
		if err != nil {
			return nil, err
		}
		n.children = append(n.children, arg)
		if p.peek().typ == T_SEMI {
			p.next()
		} else {
			break
		}
	}
	if _, err := p.expect(T_RPAREN); err != nil {
		return nil, err
	}
	return n, nil
}

// formatError formats a compilation error with context
func formatParseError(msg, src string, line, col int) string {
	lines := strings.Split(src, "\n")
	if line > 0 && line <= len(lines) {
		srcLine := lines[line-1]
		if col > len(srcLine) {
			col = len(srcLine)
		}
		marker := strings.Repeat(" ", col) + "^"
		return fmt.Sprintf("parse error: %s\n    %s\n    %s", msg, srcLine, marker)
	}
	return fmt.Sprintf("parse error: %s", msg)
}

