	NSubEq     // a -= b
	NMulEq     // a *= b
	NDivEq     // a /= b
	NModEq     // a %= b
	NAltEq     // a //= b
	NArray     // [expr]
	NObj       // {pairs}
	NIf        // if-then-else
	NTry       // try-catch
	NLabel     // label $x | expr
	NBreak     // break $x
	NAs        // expr as pat | body
	NDef       // def name(args): body ; rest
	NCall      // name(args)
	NPath      // path(expr)
