// Env holds the execution environment
type Env struct {
	parent   *Env
	vars     map[string]*JV
	funcs    map[string][]*FuncDef // name -> list of defs (by arity)
}

func newEnv(parent *Env) *Env {
	return &Env{parent: parent, vars: map[string]*JV{}, funcs: map[string][]*FuncDef{}}
}

func (e *Env) getVar(name string) (*JV, bool) {
	for env := e; env != nil; env = env.parent {
		if v, ok := env.vars[name]; ok {
			return v, true
		}
	}
	return nil, false
}

func (e *Env) setVar(name string, v *JV) {
	e.vars[name] = v
}

func (e *Env) getFunc(name string, arity int) *FuncDef {
	key := fmt.Sprintf("%s/%d", name, arity)
	for env := e; env != nil; env = env.parent {
		if defs, ok := env.funcs[key]; ok && len(defs) > 0 {
			return defs[len(defs)-1]
		}
	}
	return nil
}

