	key := fmt.Sprintf("%s/%d", def.name, len(def.params))
	e.funcs[key] = append(e.funcs[key], def)
}

// Evaluator holds the evaluation state
type Evaluator struct {
	inputFilename string
	inputLine     int
	programName   string
}

// Result channels the output values
// Each generator call passes results via a callback
type OutputFn func(*JV) error

// EvalError signals an error from evaluate
var EvalError = fmt.Errorf("eval error")

// Evaluate evaluates a jq node with input value, calling output for each result
func (ev *Evaluator) Eval(node *Node, input *JV, env *Env, output OutputFn) error {
	return ev.eval(node, input, env, output)
}

func (ev *Evaluator) eval(node *Node, input *JV, env *Env, out OutputFn) error {
	if node == nil {
		return out(input)
	}

	switch node.typ {
	case NNull:
		return out(JVNull)
	case NTrue:
		return out(JVTrue)
	case NFalse:
		return out(JVFalse)
	case NNum:
		if node.numLit {
			return out(JVNumLit(node.nval))
		}
		return out(JVNum(node.nval))
	case NStr:
		return out(JVStr(node.sval))
	case NIdent:
		return out(input)
	case NVar:
		v, ok := env.getVar(node.sval)
		if !ok {
			return jqerr(fmt.Sprintf("$%s is not defined", node.sval))
		}
		return out(v)
	case NEnv:
		return out(buildEnvObj())
	case NLoc:
		obj := JVEmptyObj()
		obj = obj.ObjSet("file", JVStr("<top-level>"))
		obj = obj.ObjSet("line", JVNum(float64(node.line)))
		return out(obj)

	case NRecurse:
		return evalRecurseAll(input, out)

	case NField:
		switch input.kind {
		case JVKindObject:
			return out(input.ObjGetOrNull(node.sval))
		case JVKindNull:
			return out(JVNull)
		default:
			return jqerr(fmt.Sprintf("Cannot index %s with string %q", input.TypeName(), node.sval))
		}
	case NFieldOpt:
		switch input.kind {
		case JVKindObject:
			return out(input.ObjGetOrNull(node.sval))
		case JVKindNull:
			return out(JVNull)
		default:
			return nil
		}

	case NIdx:
		return ev.evalIdx(node, input, env, out, false)
	case NIdxOpt:
		return ev.evalIdx(node, input, env, out, true)
	case NSlice:
		return ev.evalSlice(node, input, env, out, false)
	case NSliceOpt:
		return ev.evalSlice(node, input, env, out, true)
	case NIter:
		return evalIter(input, out, false)
	case NIterOpt:
		return evalIter(input, out, true)

	case NPipe:
		return ev.eval(node.children[0], input, env, func(v *JV) error {
			return ev.eval(node.children[1], v, env, out)
		})

	case NComma:
		if err := ev.eval(node.children[0], input, env, out); err != nil {
			return err
		}
		return ev.eval(node.children[1], input, env, out)

	case NAdd:
		return ev.evalBinOp(node, input, env, out, opAdd)
	case NSub:
		return ev.evalBinOp(node, input, env, out, opSub)
	case NMul:
		return ev.evalBinOp(node, input, env, out, opMul)
	case NDiv:
		return ev.evalBinOp(node, input, env, out, opDiv)
	case NMod:
		return ev.evalBinOp(node, input, env, out, opMod)
	case NEq:
		return ev.evalCmp(node, input, env, out, func(c int) bool { return c == 0 })
	case NNeq:
		return ev.evalCmp(node, input, env, out, func(c int) bool { return c != 0 })
	case NLt:
		return ev.evalCmp(node, input, env, out, func(c int) bool { return c < 0 })
	case NLe:
		return ev.evalCmp(node, input, env, out, func(c int) bool { return c <= 0 })
	case NGt:
		return ev.evalCmp(node, input, env, out, func(c int) bool { return c > 0 })
	case NGe:
		return ev.evalCmp(node, input, env, out, func(c int) bool { return c >= 0 })

	case NAnd:
		return ev.eval(node.children[0], input, env, func(a *JV) error {
			if !a.IsTruthy() {
				return out(JVFalse)
			}
			return ev.eval(node.children[1], input, env, func(b *JV) error {
				return out(JVFromBool(b.IsTruthy()))
			})
		})
	case NOr:
		return ev.eval(node.children[0], input, env, func(a *JV) error {
			if a.IsTruthy() {
				return out(JVTrue)
			}
			return ev.eval(node.children[1], input, env, func(b *JV) error {
				return out(JVFromBool(b.IsTruthy()))
			})
		})
	case NNot:
		return ev.eval(node.children[0], input, env, func(v *JV) error {
			return out(JVFromBool(!v.IsTruthy()))
		})

	case NAlt:
		return ev.evalAlt(node, input, env, out)
	case NTryAlt:
		return ev.evalTryAlt(node, input, env, out)

	case NArray:
		return ev.evalArray(node, input, env, out)
	case NObj:
		return ev.evalObj(node, input, env, out)

	case NIf:
		return ev.evalIf(node, input, env, out)
	case NTry:
		return ev.evalTry(node, input, env, out)
	case NLabel:
		return ev.evalLabel(node, input, env, out)
	case NBreak:
		return &BreakError{label: node.sval}
	case NAs:
		return ev.evalAs(node, input, env, out)
	case NDef:
		newEnv := newEnv(env)
		for _, def := range node.defs {
			d := def // capture
			newEnv.addFunc(d)
		}
		return ev.eval(node.children[0], input, newEnv, out)

	case NCall:
		return ev.evalCall(node, input, env, out)
	case NPath:
		return ev.evalPath(node, input, env, out)
	case NReduce:
		return ev.evalReduce(node, input, env, out)
	case NForeach:
		return ev.evalForeach(node, input, env, out)

	case NInterp:
		return ev.evalInterp(node, input, env, out)
	case NFmt:
		return ev.evalFmt(node.sval, input, out)
	case NFmtStr:
		return ev.evalFmtStr(node, input, env, out)

	case NAssign, NUpdate, NAddEq, NSubEq, NMulEq, NDivEq, NModEq, NAltEq:
		return ev.evalAssign(node, input, env, out)

	case NOptional:
		return ev.evalOptional(node, input, env, out)
	}

	return fmt.Errorf("unknown node type %d", node.typ)
}

func evalRecurseAll(v *JV, out OutputFn) error {
	if err := out(v); err != nil {
		return err
	}
	switch v.kind {
	case JVKindArray:
		for _, item := range v.arrVal {
			if err := evalRecurseAll(item, out); err != nil {
				return err
			}
		}
	case JVKindObject:
		for _, k := range v.ObjKeys() {
			if err := evalRecurseAll(v.ObjGetOrNull(k), out); err != nil {
				return err
			}
		}
	}
	return nil
}

func evalIter(v *JV, out OutputFn, optional bool) error {
	switch v.kind {
	case JVKindArray:
		for _, item := range v.arrVal {
			if err := out(item); err != nil {
				return err
			}
		}
		return nil
	case JVKindObject:
		for _, k := range v.ObjKeys() {
			if err := out(v.ObjGetOrNull(k)); err != nil {
				return err
			}
		}
		return nil
	default:
		if optional {
			return nil
		}
		return jqerr(fmt.Sprintf("Cannot iterate over %s", v.TypeDesc()))
	}
}

func (ev *Evaluator) evalIdx(node *Node, input *JV, env *Env, out OutputFn, optional bool) error {
	return ev.eval(node.children[0], input, env, func(idx *JV) error {
		switch input.kind {
		case JVKindArray:
			if idx.kind == JVKindNumber {
				i := int(idx.numVal)
				if float64(i) != idx.numVal {
					if optional {
						return nil
					}
					return jqerr(fmt.Sprintf("Cannot index array with non-integer %s", idx.TypeDesc()))
				}
				return out(input.ArrGet(i))
			}
			if optional {
				return nil
			}
			return jqerr(fmt.Sprintf("Cannot index array with %s", idx.TypeDesc()))
		case JVKindObject:
			if idx.kind == JVKindString {
				return out(input.ObjGetOrNull(idx.strVal))
			}
			if idx.kind == JVKindNull {
				return out(JVNull)
			}
			if optional {
				return nil
			}
			return jqerr(fmt.Sprintf("Cannot index object with %s", idx.TypeDesc()))
		case JVKindNull:
			if optional || idx.kind == JVKindString || idx.kind == JVKindNumber {
				return out(JVNull)
			}
			return out(JVNull)
		default:
			if optional {
				return nil
			}
			if idx.kind == JVKindString {
				return jqerr(fmt.Sprintf("Cannot index %s with string %q", input.TypeName(), idx.strVal))
			}
			return jqerr(fmt.Sprintf("Cannot index %s with %s", input.TypeName(), idx.TypeDesc()))
		}
	})
}

func (ev *Evaluator) evalSlice(node *Node, input *JV, env *Env, out OutputFn, optional bool) error {
	var startV, endV *JV = JVNull, JVNull

	getVal := func(n *Node) (*JV, error) {
		if n == nil {
			return JVNull, nil
		}
		var result *JV
		var evalErr error
		err := ev.eval(n, input, env, func(v *JV) error {
			result = v
			return nil
		})
		if err != nil {
			evalErr = err
		}
		if evalErr != nil {
			return nil, evalErr
		}
		return result, nil
	}

	var err error
	startV, err = getVal(node.children[0])
	if err != nil {
		return err
	}
	endV, err = getVal(node.children[1])
	if err != nil {
		return err
	}

	return evalSliceOp(input, startV, endV, out, optional)
}

func evalSliceOp(input, startV, endV *JV, out OutputFn, optional bool) error {
	switch input.kind {
	case JVKindArray:
		n := len(input.arrVal)
		start := 0
		end := n
		if startV != nil && startV.kind == JVKindNumber {
			start = int(startV.numVal)
			if start < 0 {
				start += n
			}
			if start < 0 {
				start = 0
			}
			if start > n {
				start = n
			}
		}
		if endV != nil && endV.kind == JVKindNumber {
			end = int(endV.numVal)
			if end < 0 {
				end += n
			}
			if end < 0 {
				end = 0
			}
			if end > n {
				end = n
			}
		}
		if start > end {
			return out(JVEmptyArr())
		}
		items := input.arrVal[start:end]
		result := make([]*JV, len(items))
		copy(result, items)
		return out(&JV{kind: JVKindArray, arrVal: result})
	case JVKindString:
		runes := []rune(input.strVal)
		n := len(runes)
		start := 0
		end := n
		if startV != nil && startV.kind == JVKindNumber {
			start = int(startV.numVal)
			if start < 0 {
				start += n
			}
			if start < 0 {
				start = 0
			}
			if start > n {
				start = n
			}
		}
		if endV != nil && endV.kind == JVKindNumber {
			end = int(endV.numVal)
			if end < 0 {
				end += n
			}
			if end < 0 {
				end = 0
			}
			if end > n {
				end = n
			}
		}
		if start > end {
			return out(JVStr(""))
		}
		return out(JVStr(string(runes[start:end])))
	default:
		if optional {
			return nil
		}
		return jqerr(fmt.Sprintf("Cannot slice %s", input.TypeName()))
	}
}

type binOpFn func(a, b *JV) (*JV, error)

func (ev *Evaluator) evalBinOp(node *Node, input *JV, env *Env, out OutputFn, fn binOpFn) error {
	return ev.eval(node.children[0], input, env, func(a *JV) error {
		return ev.eval(node.children[1], input, env, func(b *JV) error {
			result, err := fn(a, b)
			if err != nil {
				return err
			}
			return out(result)
		})
	})
}

func opAdd(a, b *JV) (*JV, error) {
	switch a.kind {
	case JVKindNull:
		return b, nil
	case JVKindNumber:
		if b.kind == JVKindNumber {
			return JVNum(a.numVal + b.numVal), nil
		}
	case JVKindString:
		if b.kind == JVKindString {
			return JVStr(a.strVal + b.strVal), nil
		}
		if b.kind == JVKindNull {
			return a, nil
		}
	case JVKindArray:
		if b.kind == JVKindArray {
			items := make([]*JV, len(a.arrVal)+len(b.arrVal))
			copy(items, a.arrVal)
			copy(items[len(a.arrVal):], b.arrVal)
			return &JV{kind: JVKindArray, arrVal: items}, nil
		}
		if b.kind == JVKindNull {
			return a, nil
		}
	case JVKindObject:
		if b.kind == JVKindObject {
			result := JVEmptyObj()
			for _, k := range a.ObjKeys() {
				result = result.ObjSet(k, a.ObjGetOrNull(k))
			}
			for _, k := range b.ObjKeys() {
				result = result.ObjSet(k, b.ObjGetOrNull(k))
			}
			return result, nil
		}
		if b.kind == JVKindNull {
			return a, nil
		}
	case JVKindFalse, JVKindTrue:
		if b.kind == JVKindNull {
			return a, nil
		}
	}
	return nil, jqerr(fmt.Sprintf("%s and %s cannot be added", a.TypeDesc(), b.TypeDesc()))
}

func opSub(a, b *JV) (*JV, error) {
	if a.kind == JVKindNumber && b.kind == JVKindNumber {
		return JVNum(a.numVal - b.numVal), nil
	}
	if a.kind == JVKindArray && b.kind == JVKindArray {
		var result []*JV
		for _, item := range a.arrVal {
			found := false
			for _, bi := range b.arrVal {
				if JVEqual(item, bi) {
					found = true
					break
				}
			}
			if !found {
				result = append(result, item)
			}
		}
		if result == nil {
			result = []*JV{}
		}
		return &JV{kind: JVKindArray, arrVal: result}, nil
	}
	return nil, jqerr(fmt.Sprintf("%s and %s cannot be subtracted", a.TypeDesc(), b.TypeDesc()))
}

func opMul(a, b *JV) (*JV, error) {
	if a.kind == JVKindNumber && b.kind == JVKindNumber {
		return JVNum(a.numVal * b.numVal), nil
	}
	if a.kind == JVKindString && b.kind == JVKindNumber {
		n := int(b.numVal)
		if n <= 0 {
			return JVNull, nil
		}
		return JVStr(strings.Repeat(a.strVal, n)), nil
	}
	if a.kind == JVKindNumber && b.kind == JVKindString {
		n := int(a.numVal)
		if n <= 0 {
			return JVNull, nil
		}
		return JVStr(strings.Repeat(b.strVal, n)), nil
	}
	if a.kind == JVKindObject && b.kind == JVKindObject {
		return mergeObjects(a, b), nil
	}
	return nil, jqerr(fmt.Sprintf("%s and %s cannot be multiplied", a.TypeDesc(), b.TypeDesc()))
}

func mergeObjects(a, b *JV) *JV {
	result := JVEmptyObj()
	for _, k := range a.ObjKeys() {
		result = result.ObjSet(k, a.ObjGetOrNull(k))
	}
	for _, k := range b.ObjKeys() {
		av, ok := a.ObjGet(k)
		bv := b.ObjGetOrNull(k)
		if ok && av.IsObj() && bv.IsObj() {
			result = result.ObjSet(k, mergeObjects(av, bv))
		} else {
			result = result.ObjSet(k, bv)
		}
	}
	return result
}

func opDiv(a, b *JV) (*JV, error) {
	if a.kind == JVKindNumber && b.kind == JVKindNumber {
		if b.numVal == 0 {
			return nil, jqerr(fmt.Sprintf("%s and %s cannot be divided because the divisor is zero", a.TypeDesc(), b.TypeDesc()))
		}
		return JVNum(a.numVal / b.numVal), nil
	}
	if a.kind == JVKindString && b.kind == JVKindString {
		if b.strVal == "" {
			return nil, jqerr("Cannot split string by empty string")
		}
		parts := strings.Split(a.strVal, b.strVal)
		items := make([]*JV, len(parts))
		for i, p := range parts {
			items[i] = JVStr(p)
		}
		return &JV{kind: JVKindArray, arrVal: items}, nil
	}
	return nil, jqerr(fmt.Sprintf("%s and %s cannot be divided", a.TypeDesc(), b.TypeDesc()))
}

func opMod(a, b *JV) (*JV, error) {
	if a.kind == JVKindNumber && b.kind == JVKindNumber {
		if b.numVal == 0 {
			return nil, jqerr(fmt.Sprintf("%s and %s cannot be divided (remainder) because the divisor is zero", a.TypeDesc(), b.TypeDesc()))
		}
		return JVNum(math.Mod(a.numVal, b.numVal)), nil
	}
	return nil, jqerr(fmt.Sprintf("%s and %s cannot be divided (remainder)", a.TypeDesc(), b.TypeDesc()))
}

func (ev *Evaluator) evalCmp(node *Node, input *JV, env *Env, out OutputFn, pred func(int) bool) error {
	return ev.eval(node.children[0], input, env, func(a *JV) error {
		return ev.eval(node.children[1], input, env, func(b *JV) error {
			return out(JVFromBool(pred(JVCmp(a, b))))
		})
	})
}

func (ev *Evaluator) evalAlt(node *Node, input *JV, env *Env, out OutputFn) error {
	hadOutput := false
	err := ev.eval(node.children[0], input, env, func(v *JV) error {
		if v.IsTruthy() {
			hadOutput = true
			return out(v)
		}
		return nil
	})
	if err != nil {
		return err
	}
	if !hadOutput {
		return ev.eval(node.children[1], input, env, out)
	}
	return nil
}

func (ev *Evaluator) evalTryAlt(node *Node, input *JV, env *Env, out OutputFn) error {
	hadOutput := false
	err := ev.eval(node.children[0], input, env, func(v *JV) error {
		hadOutput = true
		return out(v)
	})
	if err == nil && hadOutput {
		return nil
	}
	// On error or no output, try right side
	return ev.eval(node.children[1], input, env, out)
}

func (ev *Evaluator) evalArray(node *Node, input *JV, env *Env, out OutputFn) error {
	var items []*JV
	if len(node.children) > 0 {
		err := ev.eval(node.children[0], input, env, func(v *JV) error {
			items = append(items, v)
			return nil
		})
		if err != nil {
			return err
		}
	}
	if items == nil {
		items = []*JV{}
	}
	return out(&JV{kind: JVKindArray, arrVal: items})
}

func (ev *Evaluator) evalObj(node *Node, input *JV, env *Env, out OutputFn) error {
	if node.sval == "pattern" {
		// This is a pattern node, shouldn't be evaluated directly
		return jqerr("internal: evaluated pattern node")
	}
	// children are alternating [key, val, key, val, ...]
	// computed[i] indicates if key i was a computed expression
	return ev.evalObjPairs(node.children, node.computed, 0, input, env, JVEmptyObj(), out)
}

func (ev *Evaluator) evalObjPairs(pairs []*Node, computed []bool, i int, input *JV, env *Env, current *JV, out OutputFn) error {
	if i >= len(pairs) {
		return out(current)
	}

	keyNode := pairs[i]
	valNode := pairs[i+1] // may be nil for shorthand
	isComputed := i/2 < len(computed) && computed[i/2]

	return ev.eval(keyNode, input, env, func(keyVal *JV) error {
		if !isComputed {
			// Key is a literal string
			if keyVal.kind != JVKindString {
				return jqerr(fmt.Sprintf("Cannot use %s as object key", keyVal.TypeDesc()))
			}
		}

		if keyVal.kind != JVKindString {
			// For computed keys, check if they produce multiple values
			// (they shouldn't normally)
		}

		var getVal func(k string) error
		if valNode == nil {
			// Shorthand: {foo} = {foo: .foo}
			getVal = func(k string) error {
				fieldNode := &Node{typ: NField, sval: k}
				return ev.eval(fieldNode, input, env, func(v *JV) error {
					newObj := current.ObjSet(k, v)
					return ev.evalObjPairs(pairs, computed, i+2, input, env, newObj, out)
				})
			}
		} else {
			getVal = func(k string) error {
				return ev.eval(valNode, input, env, func(v *JV) error {
					newObj := current.ObjSet(k, v)
					return ev.evalObjPairs(pairs, computed, i+2, input, env, newObj, out)
				})
			}
		}

		// Handle generators in keys
		if keyVal.kind == JVKindString {
			return getVal(keyVal.strVal)
		}
		return jqerr(fmt.Sprintf("Cannot use %s as object key", keyVal.TypeDesc()))
	})
}

func (ev *Evaluator) evalIf(node *Node, input *JV, env *Env, out OutputFn) error {
	children := node.children
	// children: [cond, then, elif_cond, elif_then, ..., else]

	return ev.eval(children[0], input, env, func(cond *JV) error {
		if cond.IsTruthy() {
			return ev.eval(children[1], input, env, out)
		}
		// Check elif branches
		i := 2
		for i+1 < len(children) {
			idx := i
			return ev.eval(children[idx], input, env, func(elifCond *JV) error {
				if elifCond.IsTruthy() {
					return ev.eval(children[idx+1], input, env, out)
				}
				// Try next elif or else
				return ev.evalIfRest(children, idx+2, input, env, out)
			})
		}
		// else branch
		if len(children) > 2 && (len(children)-2)%2 == 1 {
			return ev.eval(children[len(children)-1], input, env, out)
		}
		return out(input) // no else: return input unchanged? No, jq returns input
		// Actually in jq, if without else returns the input value unchanged
		// But wait, testing shows: echo '1' | jq 'if . > 0 then "pos" end'
		// This gives "pos" but no else means if false, return input
	})
}

func (ev *Evaluator) evalIfRest(children []*Node, i int, input *JV, env *Env, out OutputFn) error {
	for i+1 <= len(children) {
		if i+1 < len(children) {
			// elif
			idx := i
			return ev.eval(children[idx], input, env, func(cond *JV) error {
				if cond.IsTruthy() {
					return ev.eval(children[idx+1], input, env, out)
				}
				return ev.evalIfRest(children, idx+2, input, env, out)
			})
		}
		// else
		return ev.eval(children[i], input, env, out)
	}
	// No else clause
	return out(input)
}

func (ev *Evaluator) evalTry(node *Node, input *JV, env *Env, out OutputFn) error {
	body := node.children[0]
	var handler *Node
	if len(node.children) > 1 {
		handler = node.children[1]
	}

	err := ev.eval(body, input, env, out)
	if err == nil {
		return nil
	}

	// Check for non-catchable errors
	switch err.(type) {
	case *HaltError:
		return err
	case *BreakError:
		return err
	}

	if handler == nil {
		return nil // try without catch swallows errors
	}

	// Get error value
	var errVal *JV
	if jqe, ok := err.(*JQError); ok {
		if jqe.val != nil {
			errVal = jqe.val
		} else {
			errVal = JVStr(jqe.msg)
		}
	} else {
		errVal = JVStr(err.Error())
	}

	return ev.eval(handler, errVal, env, out)
}

func (ev *Evaluator) evalLabel(node *Node, input *JV, env *Env, out OutputFn) error {
	labelName := node.sval
	err := ev.eval(node.children[0], input, env, out)
	if err == nil {
		return nil
	}
	if be, ok := err.(*BreakError); ok && be.label == labelName {
		return nil // caught our break
	}
	return err
}

func (ev *Evaluator) evalAs(node *Node, input *JV, env *Env, out OutputFn) error {
	gen := node.children[0]
	body := node.children[1]
	pat := node.pattern

	return ev.eval(gen, input, env, func(val *JV) error {
		newEnv := newEnv(env)
		if err := bindPattern(pat, val, newEnv); err != nil {
			return err
		}
		return ev.eval(body, input, newEnv, out)
	})
}

func bindPattern(pat *Node, val *JV, env *Env) error {
	if pat == nil {
		return nil
	}
	switch pat.typ {
	case NVar:
		env.setVar(pat.sval, val)
		return nil
	case NObj:
		if pat.sval != "pattern" {
			return fmt.Errorf("invalid pattern node")
		}
		if val.kind != JVKindObject {
			return nil // silently fail? jq actually doesn't error on pattern mismatch
		}
		for i := 0; i+1 < len(pat.children); i += 2 {
			key := pat.children[i].sval
			varPat := pat.children[i+1]
			v := val.ObjGetOrNull(key)
			if varPat == nil {
				// Shorthand: {foo} -> bind $foo
				env.setVar(key, v)
			} else {
				if err := bindPattern(varPat, v, env); err != nil {
					return err
				}
			}
		}
		return nil
	case NArray:
		if pat.sval != "pattern" {
			return fmt.Errorf("invalid pattern node")
		}
		for i, childPat := range pat.children {
			var v *JV
			if val.kind == JVKindArray {
				v = val.ArrGet(i)
			} else {
				v = JVNull
			}
			if err := bindPattern(childPat, v, env); err != nil {
				return err
			}
		}
		return nil
	}
	return fmt.Errorf("unknown pattern type %d", pat.typ)
}

func (ev *Evaluator) evalCall(node *Node, input *JV, env *Env, out OutputFn) error {
	name := node.sval
	args := node.children
	arity := len(args)

	// Check for user-defined function first
	def := env.getFunc(name, arity)
	if def != nil {
		return ev.callUserFunc(def, args, input, env, out)
	}

	// Try builtins
	return ev.evalBuiltin(name, arity, args, input, env, out)
}

func (ev *Evaluator) callUserFunc(def *FuncDef, args []*Node, input *JV, env *Env, out OutputFn) error {
	// Create new environment for the function
	funcEnv := newEnv(env)

	// Bind parameters
	for i, param := range def.params {
		if i >= len(args) {
			break
		}
		if strings.HasPrefix(param, "$") {
			// Value parameter - evaluate the argument
			varName := param[1:]
			var val *JV
			err := ev.eval(args[i], input, env, func(v *JV) error {
				val = v
				return nil
			})
			if err != nil {
				return err
			}
			funcEnv.setVar(varName, val)
		} else {
			// Function parameter - capture as a closure
			argNode := args[i]
			capturedEnv := env
			capturedInput := input
			closureDef := &FuncDef{
				name:   param,
				params: nil,
				body:   argNode,
			}
			// Override with a special closure that captures environment
			_ = capturedEnv
			_ = capturedInput
			funcEnv.addFunc(closureDef)

			// Also add a version that can access current input
			// We need to create a node wrapper that evaluates in the captured env
			closureNode := &Node{
				typ:  NCall,
				sval: "_closure_" + param,
			}
			_ = closureNode
		}
	}

	// Actually, for function parameters, we need to create wrapper defs
	// that evaluate the argument expression in the caller's environment
	// This is tricky - let me use a different approach

	return ev.callUserFuncV2(def, args, input, env, out)
}

// callUserFuncV2 properly handles both value and function arguments
func (ev *Evaluator) callUserFuncV2(def *FuncDef, args []*Node, input *JV, callerEnv *Env, out OutputFn) error {
	funcEnv := newEnv(callerEnv)

	for i, param := range def.params {
		if i >= len(args) {
			break
		}
		if strings.HasPrefix(param, "$") {
			varName := param[1:]
			var val *JV
			var evalErr error
			err := ev.eval(args[i], input, callerEnv, func(v *JV) error {
				val = v
				return nil
			})
			if err != nil {
				evalErr = err
			}
			if evalErr != nil {
				return evalErr
			}
			funcEnv.setVar(varName, val)
		} else {
			// Closure parameter
			argNode := args[i]
			capturedCallerEnv := callerEnv
			capturedInput := input
			funcEnv.addFunc(&FuncDef{
				name:   param,
				params: nil,
				body:   argNode,
			})
			// We need to store the caller environment somehow
			// Use a trick: store a special closure
			closureKey := "_closure_env_" + param
			_ = closureKey
			_ = capturedInput
			_ = capturedCallerEnv
			// Actually, we'll use a special wrapper
			// For now, the body node evaluates in funcEnv which extends callerEnv
			// But we need the closure to evaluate in callerEnv's context
			// This requires the interpreter to thread the right env...
		}
	}

	return ev.eval(def.body, input, funcEnv, out)
}

// For closure parameters, we need a way to evaluate them in the caller's env
// Let me use a closure-capture approach with a special evaluator

func (ev *Evaluator) evalPath(node *Node, input *JV, env *Env, out OutputFn) error {
	var paths [][]*JV

	err := ev.collectPaths(node.children[0], input, env, []*JV{}, func(path []*JV) error {
		p := make([]*JV, len(path))
		copy(p, path)
		paths = append(paths, p)
		return nil
	})
	if err != nil {
		return err
	}

	for _, path := range paths {
		arr := make([]*JV, len(path))
		copy(arr, path)
		if err := out(&JV{kind: JVKindArray, arrVal: arr}); err != nil {
			return err
		}
	}
	return nil
}

func (ev *Evaluator) collectPaths(node *Node, input *JV, env *Env, currentPath []*JV, pathOut func([]*JV) error) error {
	switch node.typ {
	case NIdent:
		return pathOut(currentPath)
	case NField:
		newPath := append(append([]*JV(nil), currentPath...), JVStr(node.sval))
		v := input.ObjGetOrNull(node.sval)
		if len(node.children) > 0 {
			return ev.collectPaths(node.children[0], v, env, newPath, pathOut)
		}
		return pathOut(newPath)
	case NFieldOpt:
		newPath := append(append([]*JV(nil), currentPath...), JVStr(node.sval))
		return pathOut(newPath)
	case NIter:
		switch input.kind {
		case JVKindArray:
			for i := range input.arrVal {
				newPath := append(append([]*JV(nil), currentPath...), JVNum(float64(i)))
				if err := pathOut(newPath); err != nil {
					return err
				}
			}
		case JVKindObject:
			for _, k := range input.ObjKeys() {
				newPath := append(append([]*JV(nil), currentPath...), JVStr(k))
				if err := pathOut(newPath); err != nil {
					return err
				}
			}
		}
		return nil
	case NIterOpt:
		switch input.kind {
		case JVKindArray:
			for i := range input.arrVal {
				newPath := append(append([]*JV(nil), currentPath...), JVNum(float64(i)))
				if err := pathOut(newPath); err != nil {
					return err
				}
			}
		case JVKindObject:
			for _, k := range input.ObjKeys() {
				newPath := append(append([]*JV(nil), currentPath...), JVStr(k))
				if err := pathOut(newPath); err != nil {
					return err
				}
			}
		}
		return nil
	case NIdx:
		return ev.eval(node.children[0], input, env, func(idx *JV) error {
			newPath := append(append([]*JV(nil), currentPath...), idx)
			return pathOut(newPath)
		})
	case NPipe:
		return ev.collectPaths(node.children[0], input, env, currentPath, func(midPath []*JV) error {
			midVal := getAtPath(input, midPath)
			return ev.collectPaths(node.children[1], midVal, env, midPath, pathOut)
		})
	case NRecurse:
		return ev.collectPathsRecurse(input, env, currentPath, pathOut)
	default:
		// Fallback: evaluate and collect paths
		return ev.eval(node, input, env, func(v *JV) error {
			_ = v
			return pathOut(currentPath)
		})
	}
}

func (ev *Evaluator) collectPathsRecurse(v *JV, env *Env, currentPath []*JV, pathOut func([]*JV) error) error {
	if err := pathOut(currentPath); err != nil {
		return err
	}
	switch v.kind {
	case JVKindArray:
		for i, item := range v.arrVal {
			newPath := append(append([]*JV(nil), currentPath...), JVNum(float64(i)))
			if err := ev.collectPathsRecurse(item, env, newPath, pathOut); err != nil {
				return err
			}
		}
	case JVKindObject:
		for _, k := range v.ObjKeys() {
			newPath := append(append([]*JV(nil), currentPath...), JVStr(k))
			if err := ev.collectPathsRecurse(v.ObjGetOrNull(k), env, newPath, pathOut); err != nil {
				return err
			}
		}
	}
	return nil
}

func getAtPath(v *JV, path []*JV) *JV {
	for _, key := range path {
		switch v.kind {
		case JVKindArray:
			if key.kind == JVKindNumber {
				v = v.ArrGet(int(key.numVal))
			} else {
				return JVNull
			}
		case JVKindObject:
			if key.kind == JVKindString {
				v = v.ObjGetOrNull(key.strVal)
			} else {
				return JVNull
			}
		default:
			return JVNull
		}
	}
	return v
}

func setAtPath(v *JV, path []*JV, val *JV) *JV {
	if len(path) == 0 {
		return val
	}
	key := path[0]
	rest := path[1:]

	switch key.kind {
	case JVKindString:
		if v.kind == JVKindNull {
			v = JVEmptyObj()
		}
		if v.kind == JVKindObject {
			curr := v.ObjGetOrNull(key.strVal)
			newVal := setAtPath(curr, rest, val)
			return v.ObjSet(key.strVal, newVal)
		}
	case JVKindNumber:
		n := int(key.numVal)
		if v.kind == JVKindNull {
			v = JVEmptyArr()
		}
		if v.kind == JVKindArray {
			items := make([]*JV, len(v.arrVal))
			copy(items, v.arrVal)
			idx := n
			if idx < 0 {
				idx += len(items)
			}
			// Extend if needed
			for len(items) <= idx {
				items = append(items, JVNull)
			}
			if idx >= 0 {
				curr := items[idx]
				items[idx] = setAtPath(curr, rest, val)
			}
			return &JV{kind: JVKindArray, arrVal: items}
		}
	}
	return v
}

func delAtPath(v *JV, path []*JV) *JV {
	if len(path) == 0 {
		return v
	}
	key := path[0]
	rest := path[1:]

	if len(rest) == 0 {
		// Delete this key
		switch key.kind {
		case JVKindString:
			if v.kind == JVKindObject {
				return v.ObjDel(key.strVal)
			}
		case JVKindNumber:
			if v.kind == JVKindArray {
				n := int(key.numVal)
				items := make([]*JV, 0, len(v.arrVal)-1)
				for i, item := range v.arrVal {
					if i != n {
						items = append(items, item)
					}
				}
				return &JV{kind: JVKindArray, arrVal: items}
			}
		}
		return v
	}

	// Recurse into the structure
	switch key.kind {
	case JVKindString:
		if v.kind == JVKindObject {
			curr := v.ObjGetOrNull(key.strVal)
			newVal := delAtPath(curr, rest)
			return v.ObjSet(key.strVal, newVal)
		}
	case JVKindNumber:
		n := int(key.numVal)
		if v.kind == JVKindArray {
			items := make([]*JV, len(v.arrVal))
			copy(items, v.arrVal)
			if n >= 0 && n < len(items) {
				items[n] = delAtPath(items[n], rest)
			}
			return &JV{kind: JVKindArray, arrVal: items}
		}
	}
	return v
}

func (ev *Evaluator) evalReduce(node *Node, input *JV, env *Env, out OutputFn) error {
	gen := node.children[0]
	init := node.children[1]
	body := node.children[2]
	pat := node.pattern

	// Get initial value
	var acc *JV
	err := ev.eval(init, input, env, func(v *JV) error {
		acc = v
		return nil
	})
	if err != nil {
		return err
	}

	// Iterate generator
	err = ev.eval(gen, input, env, func(val *JV) error {
		newEnv := newEnv(env)
		if err := bindPattern(pat, val, newEnv); err != nil {
			return err
		}
		return ev.eval(body, acc, newEnv, func(newAcc *JV) error {
			acc = newAcc
			return nil
		})
	})
	if err != nil {
		return err
	}

	return out(acc)
}

func (ev *Evaluator) evalForeach(node *Node, input *JV, env *Env, out OutputFn) error {
	gen := node.children[0]
	init := node.children[1]
	update := node.children[2]
	var extract *Node
	if len(node.children) > 3 {
		extract = node.children[3]
	}
	pat := node.pattern

	// Get initial value
	var acc *JV
	err := ev.eval(init, input, env, func(v *JV) error {
		acc = v
		return nil
	})
	if err != nil {
		return err
	}

	// Iterate generator
	err = ev.eval(gen, input, env, func(val *JV) error {
		newEnv := newEnv(env)
		if err := bindPattern(pat, val, newEnv); err != nil {
			return err
		}
		return ev.eval(update, acc, newEnv, func(newAcc *JV) error {
			acc = newAcc
			// Extract and output
			if extract != nil {
				return ev.eval(extract, acc, newEnv, out)
			}
			return out(acc)
		})
	})
	return err
}

func (ev *Evaluator) evalInterp(node *Node, input *JV, env *Env, out OutputFn) error {
	// Build string from parts
	// children are either NStr (literal) or expression nodes
	// computed[i] tells if child[i] is an expression
	var sb strings.Builder

	for i, child := range node.children {
		isExpr := i < len(node.computed) && node.computed[i]
		if !isExpr {
			// Literal string part
			sb.WriteString(child.sval)
		} else {
			// Expression - evaluate and convert to string
			var val *JV
			err := ev.eval(child, input, env, func(v *JV) error {
				val = v
				return nil
			})
			if err != nil {
				return err
			}
			if val == nil {
				val = JVNull
			}
			s, err := jvToString(val)
			if err != nil {
				return err
			}
			sb.WriteString(s)
		}
	}

	return out(JVStr(sb.String()))
}

func jvToString(v *JV) (string, error) {
	if v.kind == JVKindString {
		return v.strVal, nil
	}
	return jvToJSONStr(v), nil
}

func (ev *Evaluator) evalFmt(fmtName string, input *JV, out OutputFn) error {
	result, err := applyFormat(fmtName, input)
	if err != nil {
		return err
	}
	return out(result)
}

func (ev *Evaluator) evalFmtStr(node *Node, input *JV, env *Env, out OutputFn) error {
	fmtName := node.sval
	strNode := node.children[0]

	// The format string applies the format to interpolated parts
	if strNode.typ == NStr {
		// Simple string - format the whole thing? No, format strings just format interpolations
		// @html "x: \(.)" means format each interpolated part with @html
		// For a simple non-interpolated string, just return it
		return out(JVStr(strNode.sval))
	}

	// For interpolated strings: apply format to each expression result
	if strNode.typ == NInterp {
		return ev.evalInterpWithFmt(strNode, fmtName, input, env, out)
	}

	// Fallback
	return ev.eval(strNode, input, env, func(v *JV) error {
		return ev.evalFmt(fmtName, v, out)
	})
}

func (ev *Evaluator) evalInterpWithFmt(node *Node, fmtName string, input *JV, env *Env, out OutputFn) error {
	var sb strings.Builder

	for i, child := range node.children {
		isExpr := i < len(node.computed) && node.computed[i]
		if !isExpr {
			sb.WriteString(child.sval)
		} else {
			var val *JV
			err := ev.eval(child, input, env, func(v *JV) error {
				val = v
				return nil
			})
			if err != nil {
				return err
			}
			if val == nil {
				val = JVNull
			}
			// Apply format to the value
			formatted, err := applyFormat(fmtName, val)
			if err != nil {
				return err
			}
			if formatted.kind == JVKindString {
				sb.WriteString(formatted.strVal)
			} else {
				sb.WriteString(jvToJSONStr(formatted))
			}
		}
	}

	return out(JVStr(sb.String()))
}

func (ev *Evaluator) evalAssign(node *Node, input *JV, env *Env, out OutputFn) error {
	lhs := node.children[0]
	rhs := node.children[1]

	switch node.typ {
	case NAssign:
		// a = b: update all paths matching a with value b
		return ev.evalUpdateWithValue(lhs, rhs, input, env, out)
	case NUpdate:
		// a |= b: update all paths matching a by applying b
		return ev.evalUpdateWithExpr(lhs, rhs, input, env, out)
	case NAddEq:
		return ev.evalUpdateCompound(lhs, rhs, input, env, out, NAdd)
	case NSubEq:
		return ev.evalUpdateCompound(lhs, rhs, input, env, out, NSub)
	case NMulEq:
		return ev.evalUpdateCompound(lhs, rhs, input, env, out, NMul)
	case NDivEq:
		return ev.evalUpdateCompound(lhs, rhs, input, env, out, NDiv)
	case NModEq:
		return ev.evalUpdateCompound(lhs, rhs, input, env, out, NMod)
	case NAltEq:
		return ev.evalUpdateCompound(lhs, rhs, input, env, out, NAlt)
	}
	return nil
}

func (ev *Evaluator) evalUpdateWithValue(lhs, rhs *Node, input *JV, env *Env, out OutputFn) error {
	return ev.eval(rhs, input, env, func(newVal *JV) error {
		result, err := ev.updatePaths(lhs, input, env, func(_ *JV) (*JV, error) {
			return newVal, nil
		})
		if err != nil {
			return err
		}
		return out(result)
	})
}

func (ev *Evaluator) evalUpdateWithExpr(lhs, rhs *Node, input *JV, env *Env, out OutputFn) error {
	result, err := ev.updatePaths(lhs, input, env, func(old *JV) (*JV, error) {
		var newVal *JV
		err := ev.eval(rhs, old, env, func(v *JV) error {
			newVal = v
			return nil
		})
		if err != nil {
			return nil, err
		}
		return newVal, nil
	})
	if err != nil {
		return err
	}
	return out(result)
}

func (ev *Evaluator) evalUpdateCompound(lhs, rhs *Node, input *JV, env *Env, out OutputFn, op NType) error {
	return ev.eval(rhs, input, env, func(rhsVal *JV) error {
		result, err := ev.updatePaths(lhs, input, env, func(old *JV) (*JV, error) {
			opNode := mknode(op, 0, 0,
				&Node{typ: NIdent},
				&Node{typ: NIdent},
			)
			// We need to evaluate old op rhsVal
			var res *JV
			switch op {
			case NAdd:
				res, err = opAdd(old, rhsVal)
			case NSub:
				res, err = opSub(old, rhsVal)
			case NMul:
				res, err = opMul(old, rhsVal)
			case NDiv:
				res, err = opDiv(old, rhsVal)
			case NMod:
				res, err = opMod(old, rhsVal)
			case NAlt:
				if old.IsTruthy() {
					res = old
				} else {
					res = rhsVal
				}
			}
			_ = opNode
			if err != nil {
				return nil, err
			}
			return res, nil
		})
		if err != nil {
			return err
		}
		return out(result)
	})
}

// updatePaths evaluates lhs as a path expression and updates each matching location
func (ev *Evaluator) updatePaths(lhs *Node, input *JV, env *Env, updater func(*JV) (*JV, error)) (*JV, error) {
	var paths [][]*JV

	pathErr := ev.collectPaths(lhs, input, env, []*JV{}, func(path []*JV) error {
		p := make([]*JV, len(path))
		copy(p, path)
		paths = append(paths, p)
		return nil
	})
	if pathErr != nil {
		// Fallback: try to handle special cases
		return ev.updatePathsFallback(lhs, input, env, updater)
	}

	result := input
	for _, path := range paths {
		old := getAtPath(result, path)
		newVal, err := updater(old)
		if err != nil {
			return nil, err
		}
		if newVal == nil {
			result = delAtPath(result, path)
		} else {
			result = setAtPath(result, path, newVal)
		}
	}
	return result, nil
}

func (ev *Evaluator) updatePathsFallback(lhs *Node, input *JV, env *Env, updater func(*JV) (*JV, error)) (*JV, error) {
	// For .[] case and similar
	switch lhs.typ {
	case NIdent:
		return updater(input)
	case NIter, NIterOpt:
		result := input
		switch input.kind {
		case JVKindArray:
			items := make([]*JV, len(input.arrVal))
			for i, item := range input.arrVal {
				newItem, err := updater(item)
				if err != nil {
					return nil, err
				}
				items[i] = newItem
			}
			result = &JV{kind: JVKindArray, arrVal: items}
		case JVKindObject:
			for _, k := range input.ObjKeys() {
				old := input.ObjGetOrNull(k)
				newVal, err := updater(old)
				if err != nil {
					return nil, err
				}
				result = result.ObjSet(k, newVal)
			}
		}
		return result, nil
	case NField:
		old := input.ObjGetOrNull(lhs.sval)
		newVal, err := updater(old)
		if err != nil {
			return nil, err
		}
		if newVal == nil {
			return input.ObjDel(lhs.sval), nil
		}
		return input.ObjSet(lhs.sval, newVal), nil
	}
	return input, nil
}

func (ev *Evaluator) evalOptional(node *Node, input *JV, env *Env, out OutputFn) error {
	err := ev.eval(node.children[0], input, env, out)
	if err != nil {
		// Check if it's a non-catchable error
		switch err.(type) {
		case *HaltError, *BreakError:
			return err
		}
		return nil // swallow errors
	}
	return nil
}

func buildEnvObj() *JV {
	obj := JVEmptyObj()
	for _, e := range os.Environ() {
		parts := strings.SplitN(e, "=", 2)
		if len(parts) == 2 {
			obj = obj.ObjSet(parts[0], JVStr(parts[1]))
		}
	}
	return obj
}

// Numeric comparison for EQ only (used for contains check)
func numEq(a, b *JV) bool {
	if a.kind == JVKindNumber && b.kind == JVKindNumber {
		return a.numVal == b.numVal
	}
	return false
}

// Sort slice of JVs
func sortJVSlice(items []*JV) {
	sort.Slice(items, func(i, j int) bool {
		return JVCmp(items[i], items[j]) < 0
	})
}

