func htmlEscape(s string) string {
	var sb strings.Builder
	for _, r := range s {
		switch r {
		case '<':
			sb.WriteString("&lt;")
		case '>':
			sb.WriteString("&gt;")
		case '&':
			sb.WriteString("&amp;")
		case '\'':
			sb.WriteString("&apos;")
		}
		// Note: jq doesn't escape " in @html
		_ = r
		switch r {
		case '<', '>', '&', '\'':
			// already written
		default:
			sb.WriteRune(r)
		}
	}
	return sb.String()
}

func formatCSV(v *JV) string {
	var parts []string
	for _, item := range v.arrVal {
		switch item.kind {
		case JVKindNull:
			parts = append(parts, "")
		case JVKindFalse:
			parts = append(parts, "false")
		case JVKindTrue:
			parts = append(parts, "true")
		case JVKindNumber:
			parts = append(parts, formatNum(item.numVal))
		case JVKindString:
			// Escape for CSV: wrap in quotes if contains comma, quote, or newline
			s := item.strVal
			s = strings.ReplaceAll(s, "\"", "\"\"")
			parts = append(parts, "\""+s+"\"")
		default:
			parts = append(parts, jvToJSONStr(item))
		}
	}
	return strings.Join(parts, ",")
}

func formatTSV(v *JV) string {
	var parts []string
	for _, item := range v.arrVal {
		switch item.kind {
		case JVKindNull:
			parts = append(parts, "")
		case JVKindFalse:
			parts = append(parts, "false")
		case JVKindTrue:
			parts = append(parts, "true")
		case JVKindNumber:
			parts = append(parts, formatNum(item.numVal))
		case JVKindString:
			// Escape special chars
			s := item.strVal
			s = strings.ReplaceAll(s, "\\", "\\\\")
			s = strings.ReplaceAll(s, "\t", "\\t")
			s = strings.ReplaceAll(s, "\r", "\\r")
			s = strings.ReplaceAll(s, "\n", "\\n")
			parts = append(parts, s)
		default:
			parts = append(parts, jvToJSONStr(item))
		}
	}
	return strings.Join(parts, "\t")
}

func formatSH(v *JV) string {
	switch v.kind {
	case JVKindString:
		return "'" + strings.ReplaceAll(v.strVal, "'", "'\\''") + "'"
	case JVKindArray:
		var parts []string
		for _, item := range v.arrVal {
			parts = append(parts, formatSH(item))
		}
		return strings.Join(parts, " ")
	default:
		return "'" + strings.ReplaceAll(jvToJSONStr(v), "'", "'\\''") + "'"
	}
}
