		}
		return JVStr(htmlEscape(v.strVal)), nil
	case "uri":
		if v.kind != JVKindString {
			return nil, jqerr(fmt.Sprintf("%s is not valid for @uri formatting", v.TypeDesc()))
		}
		return JVStr(url.QueryEscape(v.strVal)), nil
	case "csv":
		if v.kind != JVKindArray {
			return nil, jqerr(fmt.Sprintf("%s cannot be csv-formatted, only array", v.TypeDesc()))
		}
		return JVStr(formatCSV(v)), nil
	case "tsv":
		if v.kind != JVKindArray {
			return nil, jqerr(fmt.Sprintf("%s cannot be tsv-formatted, only array", v.TypeDesc()))
		}
		return JVStr(formatTSV(v)), nil
	case "sh":
		return JVStr(formatSH(v)), nil
	case "base64":
		if v.kind != JVKindString {
			return nil, jqerr(fmt.Sprintf("%s is not a string", v.TypeDesc()))
		}
		return JVStr(base64.StdEncoding.EncodeToString([]byte(v.strVal))), nil
	case "base64d":
		if v.kind != JVKindString {
			return nil, jqerr(fmt.Sprintf("%s is not a string", v.TypeDesc()))
		}
		// Try standard encoding, then URL encoding, then no-padding
		s := strings.TrimRight(v.strVal, "=")
		// Add padding
		switch len(s) % 4 {
		case 2:
			s += "=="
		case 3:
			s += "="
		}
		decoded, err := base64.StdEncoding.DecodeString(s)
		if err != nil {
