		return ev.eval(args[0], input, env, func(pattern *JV) error {
			return ev.eval(args[1], input, env, func(flags *JV) error {
				return ev.evalMatch(input, pattern, flags, false, out)
			})
		})
	case "capture/1":
		return ev.eval(args[0], input, env, func(pattern *JV) error {
			return ev.evalCapture(input, pattern, JVStr(""), out)
		})
	case "capture/2":
		return ev.eval(args[0], input, env, func(pattern *JV) error {
			return ev.eval(args[1], input, env, func(flags *JV) error {
				return ev.evalCapture(input, pattern, flags, out)
			})
		})
	case "scan/1":
		return ev.eval(args[0], input, env, func(pattern *JV) error {
			return ev.evalScan(input, pattern, JVStr(""), out)
		})
	case "scan/2":
		return ev.eval(args[0], input, env, func(pattern *JV) error {
			return ev.eval(args[1], input, env, func(flags *JV) error {
				return ev.evalScan(input, pattern, flags, out)
			})
		})
	case "splits/1":
		return ev.eval(args[0], input, env, func(pattern *JV) error {
			return ev.evalSplits(input, pattern, JVStr(""), out)
		})
	case "splits/2":
		return ev.eval(args[0], input, env, func(pattern *JV) error {
			return ev.eval(args[1], input, env, func(flags *JV) error {
				return ev.evalSplits(input, pattern, flags, out)
			})
		})
	case "sub/2":
		return ev.eval(args[0], input, env, func(pattern *JV) error {
			return ev.eval(args[1], input, env, func(repl *JV) error {
				return ev.evalSub(input, pattern, JVStr(""), repl, false, env, out)
			})
		})
	case "sub/3":
		return ev.eval(args[0], input, env, func(pattern *JV) error {
			return ev.eval(args[1], input, env, func(flags *JV) error {
				return ev.eval(args[2], input, env, func(repl *JV) error {
					return ev.evalSub(input, pattern, flags, repl, false, env, out)
				})
			})
		})
	case "gsub/2":
		return ev.eval(args[0], input, env, func(pattern *JV) error {
			return ev.eval(args[1], input, env, func(repl *JV) error {
				return ev.evalSub(input, pattern, JVStr(""), repl, true, env, out)
			})
		})
	case "gsub/3":
		return ev.eval(args[0], input, env, func(pattern *JV) error {
			return ev.eval(args[1], input, env, func(flags *JV) error {
				return ev.eval(args[2], input, env, func(repl *JV) error {
					return ev.evalSub(input, pattern, flags, repl, true, env, out)
				})
			})
		})
	case "ascii/0":
		return out(JVNum(float64(input.strVal[0])))
	case "tojson/0", "format/1":
		if arity == 1 {
			return ev.eval(args[0], input, env, func(fmt *JV) error {
				if fmt.kind != JVKindString { return jqerr("format argument must be a string") }
				return ev.evalFmt(fmt.strVal, input, out)
			})
		}
		return out(JVStr(jvToJSONStr(input)))
	case "fromjson/0":
		if input.kind != JVKindString { return jqerr(fmt.Sprintf("%s cannot be parsed as JSON", input.TypeDesc())) }
		v, err := parseJSONSingle(input.strVal)
		if err != nil { return jqerr(fmt.Sprintf("Invalid JSON: %v", err)) }
		return out(v)
	case "bsearch/1":
		return ev.eval(args[0], input, env, func(needle *JV) error {
			return out(jvBsearch(input, needle))
		})
	case "env/0":
		return out(buildEnvObj())
	case "now/0":
		return out(JVNum(float64(time.Now().UnixNano()) / 1e9))
	case "gmtime/0":
		if input.kind != JVKindNumber { return jqerr("gmtime requires number") }
		t := time.Unix(int64(input.numVal), 0).UTC()
		return out(timeToJV(t))
	case "mktime/0":
		if input.kind != JVKindArray { return jqerr("mktime requires array") }
		t := jvToTime(input)
		return out(JVNum(float64(t.Unix())))
	case "strftime/1":
		return ev.eval(args[0], input, env, func(fmt *JV) error {
			if input.kind != JVKindNumber { return jqerr("strftime requires number") }
			if fmt.kind != JVKindString { return jqerr("strftime format must be string") }
			t := time.Unix(int64(input.numVal), 0).UTC()
			return out(JVStr(strftime(fmt.strVal, t)))
		})
	case "strptime/1":
		return ev.eval(args[0], input, env, func(fmt *JV) error {
			if input.kind != JVKindString { return jqerr("strptime requires string") }
			if fmt.kind != JVKindString { return jqerr("strptime format must be string") }
			t, err := strptime(input.strVal, fmt.strVal)
			if err != nil { return jqerr(fmt.Sprintf("date %q does not match format %q", input.strVal, fmt.strVal)) }
			return out(timeToJV(t))
		})
	case "localtime/0":
		if input.kind != JVKindNumber { return jqerr("localtime requires number") }
		t := time.Unix(int64(input.numVal), 0).Local()
		return out(timeToJV(t))
	case "strflocaltime/1":
		return ev.eval(args[0], input, env, func(fmt *JV) error {
			if input.kind != JVKindNumber { return jqerr("strflocaltime requires number") }
			t := time.Unix(int64(input.numVal), 0).Local()
			return out(JVStr(strftime(fmt.strVal, t)))
		})
	case "todate/0", "todateiso8601/0":
		if input.kind != JVKindNumber { return jqerr("todate requires number") }
		t := time.Unix(int64(input.numVal), 0).UTC()
		return out(JVStr(t.Format("2006-01-02T15:04:05Z")))
	case "fromdate/0", "fromdateiso8601/0":
		if input.kind != JVKindString { return jqerr("fromdate requires string") }
		t, err := time.Parse("2006-01-02T15:04:05Z", input.strVal)
		if err != nil { t, err = time.Parse("2006-01-02T15:04:05Z07:00", input.strVal) }
		if err != nil { t, err = time.Parse("2006-01-02T15:04:05.000000000Z", input.strVal) }
		if err != nil { return jqerr(fmt.Sprintf("invalid date: %q", input.strVal)) }
		return out(JVNum(float64(t.Unix())))
	case "dateadd/2":
		return ev.eval(args[0], input, env, func(f *JV) error {
			return ev.eval(args[1], input, env, func(x *JV) error {
				return out(JVNum(f.numVal + x.numVal))
			})
		})
	case "datesub/2":
		return ev.eval(args[0], input, env, func(f *JV) error {
			return ev.eval(args[1], input, env, func(x *JV) error {
				return out(JVNum(f.numVal - x.numVal))
			})
		})
	case "transpose/0":
		return out(jvTranspose(input))
	case "combinations/0":
		return jvCombinations(input, out)
	case "combinations/1":
		return ev.eval(args[0], input, env, func(n *JV) error {
			if n.kind != JVKindNumber { return jqerr("combinations argument must be a number") }
			arr := input
			// Create an array of n copies of input
			copies := make([]*JV, int(n.numVal))
			for i := range copies { copies[i] = arr }
			combined := &JV{kind: JVKindArray, arrVal: copies}
			return jvCombinations(combined, out)
		})
	case "input/0":
		if ev.inputFn == nil { return jqerr("no input available") }
		v, err := ev.inputFn()
		if err != nil { return err }
		if v == nil { return jqerr("null (null) and null (null) cannot be iterated over") }
		return out(v)
	case "inputs/0":
		if ev.inputFn == nil { return nil }
		for {
			v, err := ev.inputFn()
			if err != nil { return err }
			if v == nil { return nil }
			if err := out(v); err != nil { return err }
		}
	case "input_line_number/0":
		return out(JVNum(float64(ev.inputLine)))
	case "input_filename/0":
		if ev.inputFilename == "" { return out(JVNull) }
		return out(JVStr(ev.inputFilename))
	case "debug/0":
		fmt.Fprintf(os.Stderr, "%s\\n", jvToJSONStr(JVArr(JVStr("DEBUG:"), input)))
		return out(input)
	case "debug/1":
		return ev.eval(args[0], input, env, func(msg *JV) error {
			fmt.Fprintf(os.Stderr, "%s\\n", jvToJSONStr(JVArr(JVStr("DEBUG:"), msg)))
			return out(input)
		})
	case "stderr/0":
		fmt.Fprintf(os.Stderr, "%s", jvToJSONStr(input))
		return out(input)
	case "halt/0":
		return &HaltError{code: 0}
	case "halt_error/0":
		if input.kind == JVKindString {
			fmt.Fprint(os.Stderr, input.strVal)
		}
		return &HaltError{code: 5}
	case "halt_error/1":
		return ev.eval(args[0], input, env, func(code *JV) error {
			exitCode := 5
			if code.kind == JVKindNumber { exitCode = int(code.numVal) }
			if input.kind == JVKindString { fmt.Fprint(os.Stderr, input.strVal) }
			return &HaltError{code: exitCode}
		})
	case "walk/1":
		return ev.evalWalk(args[0], input, env, out)
	case "pick/1":
		return ev.evalPick(args[0], input, env, out)
	case "builtins/0":
		return out(JVStr("builtins_placeholder"))
	case "modulemeta/0":
		if input.kind != JVKindString { return jqerr("modulemeta input module name must be a string") }
		return out(JVEmptyObj())
	case "get_jq_origin/0":
		return out(JVStr("."))
	case "get_prog_origin/0":
		wd, _ := os.Getwd()
		return out(JVStr(wd))
	case "get_search_list/0":
		return out(JVArr(JVStr("~/.jq"), JVStr("$ORIGIN/../lib/jq"), JVStr("$ORIGIN/../lib")))
	case "have_decnum/0":
		return out(JVTrue)
	case "have_literal_numbers/0":
		return out(JVTrue)
	case "IN/1":
		return ev.eval(args[0], input, env, func(set *JV) error {
			// Check if input is in the set of values generated by set
			found := false
			err := ev.eval(args[0], input, env, func(v *JV) error {
				if JVEqual(input, v) { found = true }
				return nil
			})
			if err != nil { return err }
			return out(JVFromBool(found))
		})
	case "IN/2":
		return ev.eval(args[0], input, env, func(gen *JV) error {
			return ev.eval(args[1], input, env, func(v *JV) error {
				if JVEqual(gen, v) { return out(JVTrue) }
				return nil
			})
		})
	case "INDEX/1":
		return ev.evalIndex1(args[0], input, env, out)
	case "INDEX/2":
		return ev.evalIndex2(args[0], args[1], input, env, out)
	case "JOIN/2":
		return ev.evalJoin(args, 2, input, env, out)
	case "JOIN/3":
		return ev.evalJoin(args, 3, input, env, out)
	case "JOIN/4":
		return ev.evalJoin(args, 4, input, env, out)
	case "truncate_stream/1":
		return ev.evalTruncateStream(args[0], input, env, out)
	case "fromstream/1":
		return ev.evalFromStream(args[0], input, env, out)
	case "tostream/0":
		return ev.evalToStream(input, out)
	default:
		return jqerr(fmt.Sprintf("%s/%d is not defined at <top-level>, line %d, column %d:\\n    %s\\n    ^\\njq: 1 compile error", name, arity, 1, 1, name))
	}
}

func parseJSONSingle(s string) (*JV, error) {
	p := NewJSONParser(s)
	return p.Parse()
}

